window.IA = {"lang": "it", "ui": {"app_title": "ClayArena Interpreter Academy", "tagline": "Il tiro a volo per interpreti, partendo da zero", "hero_p": "Dodici missioni per imparare la lingua del Parcours de Chasse – Sporting™ e del Compak® Sporting: i piattelli e le loro traiettorie, il fucile, l'anticipo e la tecnica di tiro, il regolamento FITASC, le decisioni dell'arbitro e l'etichetta di questo sport. Poi ti eserciti come su una vera pedana: traduci l'istruttore, riconosci il piattello, trova l'anticipo e prendi la decisione dell'arbitro.", "missions": "Missioni", "practice": "Pratica", "start": "Inizia", "continue": "Continua", "lessons_n": "lezioni", "min": "min", "back": "Indietro", "back_mission": "Alla missione", "home": "Home", "key_points": "Punti chiave", "coach_says": "L'istruttore dice", "listen": "Ascolta", "reveal": "Mostra il significato", "meaning": "Significato", "say_it": "Come dirlo", "terms": "Termini", "rules_refs": "Nel regolamento FITASC", "sources": "Fonti", "quiz": "Mettiti alla prova", "correct": "Esatto!", "wrong": "Non proprio.", "next": "Avanti", "next_lesson": "Lezione successiva", "finish_lesson": "Lezione completata", "xp": "XP", "level": "Livello", "levels": ["Principiante", "Ascoltatore", "Interprete al campo", "Interprete in pedana", "Interprete professionista"], "done_of": "completate", "game_coach": "Traduci l'istruttore", "game_coach_d": "Ascolta una frase dell'istruttore in inglese e scegli che cosa significa davvero.", "game_flight": "Riconosci la traiettoria", "game_flight_d": "Guarda il volo di un piattello e indica di che presentazione si tratta.", "game_lead": "Laboratorio dell'anticipo", "game_lead_d": "Guarda come funziona l'anticipo con ogni metodo, poi premi tu il grilletto.", "game_call": "La decisione dell'arbitro", "game_call_d": "Situazioni reali in pedana: che cosa decide l'arbitro?", "game_terms": "Schede dei termini", "game_terms_d": "Abbina il termine inglese alla parola che usano i tiratori nella tua lingua.", "game_exam": "Esame finale", "game_exam_d": "30 domande da tutte le missioni. Superalo con l'80% e ottieni il tuo attestato.", "which_flight": "Che presentazione è questa?", "which_meaning": "Che cosa intende l'istruttore?", "which_term": "Come lo dicono i tiratori nella tua lingua?", "which_def": "Che cosa significa questo termine?", "launch": "Lancia", "again": "Ancora", "score": "Punteggio", "play_again": "Gioca ancora", "method": "Metodo", "m_maintained": "Anticipo mantenuto (maintained lead)", "m_swing": "Swing-through", "m_pullaway": "Pull-away", "m_ambush": "Ambush (tiro d'attesa)", "speed": "Velocità del piattello", "distance": "Distanza", "demo": "Guarda il metodo", "try": "Tocca a te: premi quando spareresti", "shoot": "Spara", "hit": "Colpito! Il piattello si rompe.", "behind": "Dietro: la rosata è passata dietro il piattello", "ahead": "Davanti: la rosata è passata davanti al piattello", "perceived": "Anticipo che vedi al momento della decisione", "actual": "Anticipo reale al momento dello sparo", "lab_note": "Rallentatore e fisica semplificata a scopo didattico: velocità media dei pallini di circa 330 m/s e 0,15 s tra la decisione e lo sparo. L'anticipo reale dipende anche dal tiratore, dalla cartuccia e dall'angolo.", "exam_pass": "Superato! Ora puoi ottenere il tuo attestato.", "exam_fail": "Non ancora: serve l'80%. Ripassa le missioni e riprova.", "cert_name": "Il tuo nome per l'attestato", "cert_print": "Stampa o salva in PDF", "cert_title": "Attestato", "cert_text": "ha completato il corso ClayArena Interpreter Academy sulla terminologia, la tecnica, il regolamento FITASC e l'etichetta del Parcours de Chasse – Sporting™ e del Compak® Sporting.", "cert_note": "Attestato di autoapprendimento di ClayArena; non è una qualifica FITASC.", "question": "Domanda", "of": "di", "term_all": "In tutte le lingue di ClayArena", "term_note_anglicism": "Spesso i tiratori usano semplicemente la parola inglese.", "confidence_low": "da confermare", "reset": "Azzera i progressi", "reset_confirm": "Eliminare tutti i progressi e gli XP su questo dispositivo?", "saved_local": "I progressi sono salvati su questo dispositivo.", "disclaimer": "Corso di ClayArena. Il regolamento FITASC è riportato con una nostra parafrasi e con i link alle pagine delle regole; fa fede solo il testo ufficiale FITASC. Parcours de Chasse – Sporting™ e Compak® Sporting sono marchi della FITASC.", "language": "Lingua", "all_missions_done": "Tutte le missioni completate: è il momento dell'esame finale!", "decision": "decisione", "shot_moment": "sparo", "lead_word": "anticipo", "unit_m": "m", "unit_ft": "ft", "unit_ms": "m/s", "glossary_page": "Pagina del glossario", "pair_report": "Doppio allo sparo (on report): il 2º piattello parte al rumore del 1º colpo", "pair_sim": "Doppio simultaneo: entrambi i piattelli partono insieme", "pair_rafale": "Doppio a raffica (rafale, following pair): il 2º piattello dalla stessa macchina subito dopo il 1º"}, "missions": [{"id": "sport", "icon": "flag", "title": "Questo sport in dieci minuti", "intro": "Prima di tradurre anche un solo consiglio tecnico, ti serve il quadro generale: a che cosa si spara davvero, chi scrive le regole, com'è fatto un percorso di Parcours de Chasse – Sporting™ e un campo di Compak® Sporting, e come si svolge una giornata di gara. Cinque brevi lezioni ti danno la mappa; ogni missione successiva aggiunge i dettagli.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Piattelli, non uccelli: che sport è questo", "body": ["Il tiro a volo è uno sport in cui il tiratore rompe con un fucile dei piccoli dischi in volo. Il disco si chiama piattello (target o clay in inglese); i tiratori inglesi lo chiamano spesso bird, «uccello», ma nessuno spara ad animali vivi. Il regolamento FITASC dice chiaramente che sparare ad animali vivi non è consentito e che la sicurezza e il rispetto dell'ambiente vengono prima di tutto.", "Ogni piattello viene lanciato da una macchina lanciapiattelli (trap). Il percorso che compie in aria (o rotolando sul terreno) è la traiettoria. L'arma è un fucile a canna liscia: spara una cartuccia piena di piccoli pallini (shot), che si allargano in una piccola nuvola, la rosata. Per questo il tiratore punta il fucile dove il piattello sta andando, non dove si trova in quel momento.", "Questo corso riguarda due discipline della federazione internazionale FITASC. Il Parcours de Chasse – Sporting™ (in breve Sporting™, in Italia «Percorso di Caccia») imita la caccia: le macchine sono nascoste nei campi e nei boschi e i piattelli volano come una starna, un'anatra o un fagiano, oppure rotolano come una lepre. Il Compak® Sporting è la versione compatta: la stessa varietà di piattelli, ma su un unico piccolo campo con cinque pedane in linea e sei macchine.", "Sentirai parlare anche di Trap (Fossa) e di Skeet. Sono discipline diverse, con traiettorie fisse e ripetute; la Fossa Olimpica e lo Skeet appartengono a un'altra federazione. Non mescolare le loro regole con quelle dello Sporting™ o del Compak® Sporting.", "Un colpo a segno si vede subito: il piattello si rompe o almeno se ne stacca un pezzo visibile. Proprio questa chiarezza rende lo sport facile da guardare e, per te, facile da seguire fin dal primo giorno."], "key_points": ["Si spara a piattelli lanciati da macchine, mai ad animali vivi.", "Il fucile spara una nuvola di piccoli pallini (la rosata), quindi il tiratore punta davanti al piattello.", "Lo Sporting™ imita la caccia su terreno naturale; il Compak® Sporting è la sua versione compatta su un unico campo.", "Trap (Fossa) e Skeet sono altre discipline con regole proprie."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "«Bird» è un piattello, non un vero uccello; trap B è la macchina contrassegnata con la lettera B.", "say": "Guarda questo piattello dalla macchina B."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Due discipline diverse in due giorni diversi.", "say": "Oggi facciamo il percorso di Sporting, domani il Compak."}, {"en": "Point it, don't aim it.", "meaning": "Il fucile da caccia si muove e si punta tenendo entrambi gli occhi sul piattello; non si mira come con una carabina.", "say": "Puntalo, non mirare."}], "quiz": [{"q": "L'istruttore dice «Watch the next bird». Che cosa vedrai?", "options": ["Un piccione vivo liberato da una cassetta", "Un piattello lanciato da una macchina", "Un bersaglio di carta a forma di uccello su un pannello", "Un drone"], "answer": 1, "why": "«Bird» è il gergo dei tiratori per il piattello; il regolamento FITASC vieta di sparare ad animali vivi."}, {"q": "Che cosa spara un fucile da caccia?", "options": ["Un'unica palla", "Un piccolo dardo simile a una freccia", "Una nuvola di piccoli pallini (shot)", "Una pallina piena di vernice"], "answer": 2, "why": "I pallini escono dalla volata come una piccola nuvola, quindi il tiratore punta davanti al piattello in movimento."}, {"q": "Quale affermazione sul Compak® Sporting è corretta?", "options": ["È una versione compatta su un unico campo, con le pedane in linea", "È la versione olimpica della disciplina Skeet", "Si tira solo a selvaggina viva sul terreno", "Usa una sola macchina e una sola pedana"], "answer": 0, "why": "Il Compak® Sporting porta piattelli in stile Sporting™ su un unico piccolo campo con cinque pedane e sei macchine."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "La FITASC, le federazioni e ClayArena", "body": ["La FITASC è la federazione internazionale del tiro a volo di tipo venatorio. Scrive e aggiorna i regolamenti del Parcours de Chasse – Sporting™ e del Compak® Sporting; le edizioni che seguiamo sono datate 01/01/2025. Compak® Sporting è anche un marchio tutelato dalla FITASC: per questo il nome si scrive sempre con ®.", "Questo sport è costruito come una piramide. Alla base ci sono i club e i campi di tiro, sopra di loro le federazioni nazionali, e le federazioni nazionali sono membri della FITASC. I percorsi per le gare nazionali sono approvati dalla federazione nazionale, quelli per le gare internazionali dalla FITASC. Una federazione può affidare una gara a un club, ma resta responsabile dell'applicazione delle regole.", "Sul campo le regole sono applicate dagli arbitri. Ogni arbitro ha un'abilitazione rilasciata da una federazione nazionale, mentre il giudice arbitro (chief referee) deve avere un'abilitazione internazionale FITASC. Nelle gare internazionali una giuria si occupa di reclami, penalizzazioni e problemi tecnici. Tradurrai per tutti loro, quindi impara i titoli: arbitro, giudice arbitro, giuria.", "Esistono anche altri organismi. In Gran Bretagna e negli Stati Uniti le associazioni nazionali gestiscono le proprie versioni di questo sport, come l'English Sporting, con regole e parole diverse. Un istruttore britannico o americano può usare quelle parole anche in una gara FITASC; le missioni successive ti mostrano come gestire la cosa.", "ClayArena è la piattaforma dietro questo corso. Pubblica i calendari delle gare, un glossario e una sintesi in linguaggio semplice del regolamento FITASC e, attraverso ClayAway, organizza tour di allenamento. Ricorda: fa fede solo il testo ufficiale FITASC; una sintesi è una guida, non la regola stessa."], "key_points": ["La FITASC scrive i regolamenti dello Sporting™ e del Compak® Sporting (edizioni del 01/01/2025).", "Club, federazione nazionale, FITASC: i percorsi nazionali li approva la federazione, quelli internazionali la FITASC.", "Gli arbitri hanno abilitazioni nazionali; il giudice arbitro ha un'abilitazione internazionale FITASC; la giuria esamina i reclami.", "Fa fede solo il testo ufficiale FITASC; ClayArena offre una sintesi."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "L'istruttore passa dal lessico britannico al nome FITASC.", "say": "Questo è un termine CPSA: per la FITASC è un doppio simultaneo."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "La domanda va rivolta al più alto ufficiale di gara.", "say": "Chiedi al giudice arbitro, non all'arbitro di pedana."}, {"en": "The jury will decide this one.", "meaning": "La questione va oltre l'arbitro di pedana e passa alla giuria della gara.", "say": "Su questo deciderà la giuria."}], "quiz": [{"q": "Chi approva i percorsi per una gara internazionale di Sporting™?", "options": ["Il club locale", "La federazione nazionale", "L'arbitro del giorno", "La FITASC"], "answer": 3, "why": "I percorsi nazionali sono approvati dalla federazione nazionale, quelli internazionali dalla FITASC."}, {"q": "Quale abilitazione deve avere il giudice arbitro?", "options": ["Un'abilitazione internazionale FITASC", "Solo la tessera del club, nient'altro", "Una licenza nazionale da istruttore rilasciata dal suo club", "Nessuna: può farlo qualsiasi tiratore esperto"], "answer": 0, "why": "Gli arbitri di pedana hanno bisogno di un'abilitazione nazionale; il giudice arbitro di un'abilitazione internazionale FITASC."}, {"q": "Durante una contestazione un cliente ti mostra la sintesi del regolamento di ClayArena. Che valore ha?", "options": ["Prevale sul testo ufficiale FITASC", "È solo una guida; fa fede il testo FITASC", "È vincolante, ma solo nel Compak® Sporting", "Sostituisce la decisione dell'arbitro in pedana"], "answer": 1, "why": "Una sintesi ti aiuta a capire le regole, ma l'arbitro e la giuria applicano il testo ufficiale FITASC."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Un percorso di Sporting™: campi, pedane e macchine", "body": ["Nel Parcours de Chasse – Sporting™ il terreno è diviso in layout (in italiano si dice «percorso» o, più spesso tra i tiratori, «campo»). Un layout è un gruppo di pedane di tiro che insieme danno 25 piattelli: 15 singoli e 5 doppi. A seconda del sistema, un layout ha tre, quattro o cinque pedane, ognuna con le proprie macchine.", "La pedana (shooting stand) è il punto in cui sta il tiratore: un quadrato di 1 m di lato o un cerchio di 1 m di diametro, piano e non scivoloso. Attenzione alla parola inglese stand: in italiano «stand» fa pensare a uno spazio espositivo, e «campo» indica l'intero layout; traduci stand con «pedana». Il resto della batteria (squad) aspetta lì vicino, abbastanza vicino da seguire ma senza mai disturbare il tiratore.", "Le macchine sono collocate in base al terreno, spesso in parte nascoste da cespugli o alberi, in modo che i piattelli sembrino vera selvaggina: traversoni, piattelli in arrivo, in allontanamento, in diagonale, alti o bassi, allo scoperto o tra gli alberi. Le macchine di una pedana sono contrassegnate con le lettere A, B, C, D, lette da sinistra a destra come le vede chi sta in pedana.", "Davanti a ogni pedana c'è il menu dei piattelli: elenca le macchine nell'ordine di tiro e indica i piattelli speciali, come un piattello da 90 mm, 70 mm o 60 mm, una battuta o una lepre (rabbit). Il tiratore lo legge prima di salire in pedana, e dovresti farlo anche tu.", "Le traiettorie sono classificate per difficoltà. Un piattello di classe A viene rotto da un tiratore medio più dell'80% delle volte, uno di classe B dal 60 all'80%, uno di classe C dal 40 al 60%. Quindi un piattello di classe C è pensato per essere difficile: mancarlo non è un disastro."], "key_points": ["Un layout (campo) dà 25 piattelli: 15 singoli e 5 doppi.", "La pedana è un quadrato di 1 m o un cerchio di 1 m; traduci stand con «pedana», non con «stand» né con «campo».", "Le macchine sono contrassegnate A, B, C, D da sinistra a destra come si vedono dalla pedana.", "Il menu indica l'ordine delle macchine e gli eventuali piattelli speciali.", "Classi di difficoltà: A oltre l'80%, B 60–80%, C 40–60%."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "Sul terzo campo ci sono molti piattelli piccoli che volano tra gli alberi.", "say": "Oggi il campo tre è quello difficile: tanti mini tra gli alberi."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Prima controlla l'ordine delle macchine e i piattelli speciali.", "say": "Su questa pedana leggi il menu prima di salire."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "Il piattello è classificato come difficile; un errore è previsto.", "say": "La pedana due è un piattello di classe C, non preoccuparti."}], "quiz": [{"q": "Quanti piattelli dà un layout (campo) di Sporting™?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Ogni tipo di layout dà 25 piattelli: 15 singoli e 5 doppi."}, {"q": "L'istruttore dice «Go to stand two». Come traduci «stand»?", "options": ["«campo di tiro» (l'intero impianto)", "«pedana»", "«tribuna»", "«rastrelliera» (portafucili)"], "answer": 1, "why": "Nello Sporting™ lo stand è la postazione di tiro di 1 m, cioè la pedana; «stand» in italiano fa pensare a uno spazio espositivo e il campo è l'intero layout."}, {"q": "Come si identificano le macchine di una pedana di Sporting™?", "options": ["Con i numeri da 1 a 6, contati da destra", "Con colori dipinti su ogni macchina", "Con le lettere A, B, C, D da sinistra a destra", "Con il nome della persona che le aziona"], "answer": 2, "why": "Le lettere A, B, C, D si leggono da sinistra a destra come si vedono dalla pedana, e il menu e lo statino le usano."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Un campo di Compak® Sporting: cinque pedane, sei macchine", "body": ["Il Compak® Sporting sta su un unico campo. Davanti ai tiratori c'è un rettangolo obbligatorio, largo da 35 a 40 m e profondo 25 m, delimitato da quattro paletti d'angolo con bandierine. In assenza di vento ogni piattello deve sorvolarlo in un punto della sua traiettoria.", "Cinque pedane di tiro, ognuna un quadrato di 1 m di lato, sono disposte in linea con 2–5 m tra i loro centri. Sono numerate da 1 a 5 da sinistra a destra (in italiano «pedana 1», «pedana 2» e così via). Ogni pedana ha un Firing Angle Limiter (limitatore dell'angolo di tiro): un telaio di tubi che impedisce al fucile di ruotare troppo di lato o verso l'alto e impedisce al tiratore di fare un passo avanti.", "Sei macchine, dalla A alla F da sinistra a destra, hanno ciascuna un pannello con la propria lettera. Possono essere davanti, ai lati, dietro i tiratori o su una torre; una macchina dietro la linea di tiro deve stare almeno 4 m più in alto. Ogni Compak ha tre piattelli obbligatori: un traversone da sinistra a destra, un traversone da destra a sinistra e un piattello in allontanamento.", "Una serie è di 25 piattelli, cinque per ogni pedana. Quando tira una batteria di sei, cinque tiratori stanno sulle pedane e il sesto aspetta dietro la pedana 1. Ogni tiratore spara a turno i cinque piattelli del menu della sua pedana, cominciando dalla pedana 1. Quando la pedana 5 ha finito, quel tiratore va ad aspettare dietro la pedana 1, tutti gli altri si spostano di una pedana verso destra e il tiratore in attesa sale sulla pedana 1.", "In alcune gare il Compak® Sporting si tira invece in linea: ogni tiratore comincia dalla pedana 1 e finisce sulla pedana 5. Chiedi all'organizzatore quale sistema si usa, perché la procedura cambia."], "key_points": ["Un rettangolo di 35–40 m × 25 m che ogni piattello deve attraversare.", "Cinque pedane di 1 m in linea, a 2–5 m l'una dall'altra, ognuna con un Firing Angle Limiter.", "Sei macchine con le lettere dalla A alla F da sinistra a destra; una macchina dietro la linea sta su una torre alta almeno 4 m.", "25 piattelli per serie, cinque per pedana; la batteria ruota di una pedana verso destra.", "Il Compak® Sporting si può tirare a batterie o in linea."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "La batteria ruota; il tiratore della pedana 5 va dietro la pedana 1.", "say": "Tutti avanti di una pedana a destra. Il numero cinque va in attesa."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "Il piattello della macchina E è lanciato da una torre alta e passa sopra la testa.", "say": "La macchina E è sulla torre: ti passa sopra la testa."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Rispetta il Firing Angle Limiter; non portare il fucile oltre.", "say": "Attento al telaio: non andare oltre il paletto."}], "quiz": [{"q": "Quante macchine e quante pedane ha un campo di Compak® Sporting?", "options": ["4 macchine, 3 pedane", "6 macchine, 5 pedane", "5 macchine, 6 pedane", "8 macchine, 8 pedane"], "answer": 1, "why": "Macchine dalla A alla F e pedane dalla 1 alla 5."}, {"q": "In una batteria di sei, dove sta il sesto tiratore mentre gli altri sparano?", "options": ["Nella club house", "Accanto all'arbitro alla pedana 5", "Dietro la macchina F", "In attesa dietro la pedana 1"], "answer": 3, "why": "Il tiratore in attesa sta dietro la pedana 1 e ci sale dopo ogni rotazione."}, {"q": "A che cosa serve il Firing Angle Limiter?", "options": ["Limita la rotazione del fucile e impedisce di fare un passo avanti", "Misura la velocità di ogni piattello lanciato", "Contiene le cartucce per tutta la serie", "Lancia i piattelli alla chiamata del tiratore"], "answer": 0, "why": "È un telaio di sicurezza su ogni pedana che limita la rotazione laterale e verticale."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Una giornata di gara dall'inizio alla fine", "body": ["La giornata comincia con la registrazione: il tiratore conferma l'iscrizione, riceve il pettorale (numero di gara) e lo appunta in alto sulla schiena, ben visibile. Poi tutti controllano le liste delle batterie e gli orari di tiro. Rispettare l'orario è responsabilità del tiratore stesso.", "Una batteria (squad) è un gruppo di massimo sei tiratori, sorteggiati, che tirano insieme. In ClayAway la parola squad indica anche un sottogruppo di un tour, quindi chiarisci di quale dei due parli. Nel Parcours de Chasse – Sporting™ la batteria tira prima tutti i singoli di una pedana, poi i doppi, e l'ordine di tiro ruota da una pedana all'altra. Il primo tiratore della batteria vede i piattelli mostrati prima che chiunque spari.", "Una serie è di 25 piattelli: un campo nello Sporting™, un campo nel Compak® Sporting. Una gara internazionale è di 200 piattelli, quindi otto serie in più giorni. L'arbitro segna ogni piattello sullo statino, di solito X per un piattello colpito e O per un errore. I tiratori controllano il punteggio quando lasciano una pedana nello Sporting™ e firmano lo statino alla fine di una serie di Compak® Sporting.", "Arrivare in ritardo costa caro. Nello Sporting™ l'arbitro chiama il nome tre volte nell'arco di un minuto; un tiratore che salta il proprio turno riceve zero per i piattelli non tirati. Nel Compak® Sporting un tiratore che arriva dopo che il primo tiratore della batteria ha chiamato il piattello riceve 25 zeri per la serie.", "Se ci sono tiratori a pari merito per i primi tre posti, si fa uno spareggio (shoot-off): 25 piattelli, poi morte improvvisa (sudden death). Le parità nelle posizioni inferiori si risolvono con lo spareggio a ritroso (countback), confrontando prima l'ultima serie. La giornata si chiude con il tabellone dei risultati e la premiazione."], "key_points": ["Registrazione, pettorale sulla schiena, liste delle batterie e orari.", "Una batteria è di massimo sei tiratori sorteggiati; nello Sporting™ prima i singoli, poi i doppi, con ordine di tiro a rotazione.", "Una serie è di 25 piattelli; le gare internazionali sono di 200 piattelli.", "Il ritardo costa zeri; nel Compak® Sporting 25 zeri per la serie.", "Parità per i primi tre posti: spareggio su 25, poi morte improvvisa; parità inferiori: spareggio a ritroso."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Numero della batteria, campo di partenza e orario di partenza.", "say": "Sei nella batteria dodici, si parte dal campo cinque alle nove e mezza."}, {"en": "Check your card before you leave the stand.", "meaning": "Assicurati subito che l'arbitro abbia registrato correttamente il tuo punteggio; dopo è troppo tardi.", "say": "Controlla lo statino prima di lasciare la pedana."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22 su 25 nella prima serie; in una gara da 200 piattelli restano sette serie.", "say": "Ventidue nella prima serie va bene: ne mancano altre sette."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Un tiratore che può finire allo spareggio deve essere pronto poco dopo la chiamata.", "say": "Resta qui vicino: se c'è una parità, spari entro quindici minuti dalla chiamata."}], "quiz": [{"q": "Di quanti piattelli è una gara internazionale FITASC?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 piattelli in serie da 25."}, {"q": "Nel Compak® Sporting a batterie, un tiratore arriva dopo che il primo tiratore ha chiamato il primo piattello. Che cosa succede?", "options": ["Niente, si unisce agli altri", "Riceve 25 zeri per quella serie", "Tira la serie da solo più tardi, senza penalità", "Perde un piattello"], "answer": 1, "why": "Nel Compak® Sporting a batterie chi arriva dopo la prima chiamata riceve 25 zeri; per un motivo valido è possibile ricorrere alla giuria."}, {"q": "Due tiratori sono a pari merito al 5º posto. Come si separano?", "options": ["Con uno spareggio su 25 piattelli", "Con un sorteggio dopo la gara", "Con lo spareggio a ritroso a partire dall'ultima serie", "Per età, prima il più giovane"], "answer": 2, "why": "Gli spareggi si fanno solo per i primi tre posti; sotto, lo spareggio a ritroso confronta l'8ª serie, poi la 7ª e così via."}]}]}, {"id": "gear", "icon": "tool", "title": "Fucile ed equipaggiamento", "intro": "Gli istruttori parlano del fucile tutto il giorno: «raise the comb» (alza il nasello), «check your selector» (controlla il selettore), «change chokes» (cambia gli strozzatori), «nines in the bottom» (il 9 nella canna inferiore). Questa missione ti dà le parole per il fucile, le sue parti, gli strozzatori, le cartucce e le protezioni, insieme alle poche regole sull'equipaggiamento che ogni interprete deve conoscere.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Tipi di fucile e che cosa ammette il regolamento", "body": ["Ogni fucile che vedrai in pedana è un fucile a canna liscia. In quasi tutte le pedane di gara si tratta di un sovrapposto (over-and-under, O/U): due canne una sopra l'altra, che si aprono «spezzando» il fucile sulla sua cerniera. Ogni canna può montare il proprio strozzatore, cosa importante per i doppi.", "Un giustapposto (side-by-side), che nell'uso si chiama anche «doppietta», ha due canne affiancate. È il classico fucile da caccia ed è ammesso, ma in gara si vede raramente. Non tradurre over-and-under semplicemente con «doppietta»: in italiano doppietta indica proprio il fucile a canne affiancate, cioè l'altro tipo.", "Un semiautomatico (semi-automatic; nel gergo spesso «automatico») ha una sola canna e si ricarica da solo dopo ogni colpo, espellendo il bossolo vuoto di lato. La FITASC lo ammette a certe condizioni: non più di due cartucce nell'arma, otturatore aperto ogni volta che lo si trasporta e, nel Compak® Sporting, un dispositivo che impedisce ai bossoli espulsi di colpire il vicino.", "I fucili a pompa (pump-action), che si ricaricano facendo scorrere a mano l'astina, non sono ammessi né nel Parcours de Chasse – Sporting™ né nel Compak® Sporting. I regolamenti si limitano a stabilire il divieto senza dare una motivazione, quindi non inventarne una quando un cliente te lo chiede: di' semplicemente che è la regola. Il Compak® Sporting vieta anche i drilling, armi che combinano canne lisce e canne rigate.", "In entrambe le discipline valgono altri due limiti: il calibro non può essere maggiore del 12 (quindi il calibro 20 va bene) e le canne devono essere lunghe almeno 66 cm. Sono vietati le cinghie, le telecamere montate sul fucile e qualsiasi dispositivo di mira artificiale."], "key_points": ["La maggior parte dei tiratori in gara usa un sovrapposto (over-and-under).", "I semiautomatici sono ammessi: al massimo due cartucce, otturatore aperto durante il trasporto, raccoglibossoli nel Compak® Sporting.", "I fucili a pompa sono vietati in entrambe le discipline; il regolamento non dà motivazioni.", "Calibro non maggiore del 12, canne di almeno 66 cm, niente cinghie né dispositivi di mira."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "Il fucile da gara a due canne più degli strozzatori di ricambio.", "say": "Porta il sovrapposto e un set di strozzatori di ricambio."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Regola di sicurezza: il semiautomatico si trasporta con l'otturatore aperto.", "say": "Con il semiautomatico tieni l'otturatore aperto finché non sei in pedana."}, {"en": "No pumps on this ground.", "meaning": "I fucili a pompa non sono ammessi.", "say": "Su questo campo niente fucili a pompa."}], "quiz": [{"q": "Quale fucile NON è ammesso nello Sporting™ e nel Compak® Sporting FITASC?", "options": ["Un sovrapposto calibro 20", "Un giustapposto", "Un fucile a pompa", "Un semiautomatico con due cartucce"], "answer": 2, "why": "I fucili a pompa sono vietati; gli altri sono ammessi se rispettano i limiti di calibro e di lunghezza delle canne."}, {"q": "Quante cartucce può contenere un semiautomatico?", "options": ["Una", "Due", "Tre", "Quante ne entrano nel serbatoio"], "answer": 1, "why": "Entrambi i regolamenti limitano il semiautomatico a due cartucce."}, {"q": "Un cliente chiede perché i fucili a pompa sono vietati. Qual è la risposta onesta?", "options": ["Il regolamento stabilisce il divieto senza spiegarlo", "Il regolamento dice che sono troppo lenti per i doppi", "Il regolamento dice che sono meno sicuri", "In realtà sono ammessi nel Compak® Sporting"], "answer": 0, "why": "I regolamenti non danno motivazioni; come interprete riferisci la regola e non inventare spiegazioni."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "Le parti del fucile, dalla spalla alla volata", "body": ["Gli istruttori nominano continuamente le parti del fucile, quindi imparale da dietro in avanti. Il calcio (stock) va appoggiato alla spalla. Il suo bordo superiore, dove poggia la guancia, è il nasello (comb, detto anche cresta o poggiaguancia); «raise the comb» o «drop the comb» (alzare o abbassare il nasello) riguardano la calciatura su misura. La parte stretta impugnata dalla mano del grilletto è l'impugnatura (grip) e il tampone di gomma all'estremità è il calciolo (recoil pad).", "Il cuore metallico del fucile è la bascula (receiver o action). Sopra c'è la chiave di apertura (top lever): spingila di lato e il fucile si apre. Dietro di essa c'è la sicura (safety catch), spesso unita al selettore delle canne (barrel selector, «selector»), che decide quale canna spara per prima. Sotto c'è il grilletto (trigger) con il suo ponticello.", "Uno scatto a rilascio (release trigger) fa partire il colpo quando il grilletto viene lasciato, non quando viene premuto. Un fucile di questo tipo deve avere, come avvertimento, un adesivo con una grande «R» su fondo fluorescente sul lato esterno del calcio.", "Sotto le canne l'altra mano tiene l'astina (fore-end). Le canne (barrels) hanno dietro le camere di scoppio (chambers) per le cartucce e davanti le volate (muzzles), dove si avvitano gli strozzatori. Lungo la parte superiore corre la bindella (rib), con il mirino (bead) in punta. Il mirino è un riferimento, non un organo di mira: «guarda il piattello, non il mirino».", "Due falsi amici: rib qui non è la «costola», e «break the gun» significa aprire il fucile, non romperlo. E una regola di sicurezza legata alle parti del fucile: dopo un colpo mancato (misfire) o qualsiasi altro guasto dell'arma o della cartuccia, il tiratore non deve aprire il fucile né toccare la sicura finché l'arbitro non l'ha controllato."], "key_points": ["Calcio, nasello, impugnatura, calciolo; bascula con chiave di apertura, sicura e selettore; grilletto.", "Astina, canne con camere di scoppio e volate, bindella con mirino.", "Uno scatto a rilascio richiede un adesivo con la «R» sul calcio.", "Rib = bindella, non «costola»; break the gun = aprire il fucile.", "Dopo un colpo mancato: non aprire il fucile né toccare la sicura prima del controllo dell'arbitro."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "L'occhio è troppo alto sopra la bindella, di solito perché la testa si stacca dal nasello.", "say": "Vedi troppa bindella: hai la testa alta."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "Il selettore delle canne è impostato al contrario.", "say": "Controlla il selettore: hai sparato prima con la canna superiore."}, {"en": "Break your gun and show me it's clear.", "meaning": "Apri il fucile e mostra che le camere sono vuote.", "say": "Apri il fucile e fammi vedere che è scarico."}, {"en": "Forget the bead — look at the target.", "meaning": "Concentrati sul piattello, non sulla punta della canna.", "say": "Lascia stare il mirino: guarda il piattello."}], "quiz": [{"q": "L'istruttore dice «Raise the comb». Di quale parte parla?", "options": ["La parte superiore del calcio, dove poggia la guancia", "Il piccolo mirino in punta alla bindella", "Il ponticello intorno al grilletto", "Lo strozzatore alla volata"], "answer": 0, "why": "Il comb è il nasello, la parte superiore del calcio; alzarlo porta l'occhio più in alto sopra la bindella."}, {"q": "Che cosa deve avere un fucile con scatto a rilascio?", "options": ["Una canna dipinta di rosso per avvisare gli altri", "Un grande adesivo con la «R» sul calcio", "Una seconda sicura separata", "Niente: non serve alcun contrassegno"], "answer": 1, "why": "Entrambi i regolamenti richiedono l'adesivo di avvertimento con la «R», su fondo fluorescente, sul lato esterno del calcio."}, {"q": "Come traduci «Break your gun»?", "options": ["«Rompi il fucile»", "«Smonta il fucile in pezzi»", "«Apri (spezza) il fucile»", "«Pulisci le canne del fucile»"], "answer": 2, "why": "Su un campo di tiro «break» significa aprire il fucile sulla cerniera in modo che non possa sparare."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Gli strozzatori: che cosa fanno e come ne parlano gli istruttori", "body": ["Lo strozzatore (choke; la strozzatura è il restringimento stesso) è un leggero restringimento della canna alla volata. Controlla la velocità con cui si allarga la rosata. Più strozzatura tiene i pallini uniti più a lungo e dà una rosata più stretta per i piattelli lontani; meno strozzatura li allarga prima e dà una rosata più ampia e più tollerante per i piattelli vicini.", "La maggior parte dei fucili da gara ha strozzatori intercambiabili (multichoke): brevi tubi avvitati nella volata con un'apposita chiave per strozzatori. I fucili più vecchi possono avere la strozzatura fissa, ricavata nella canna. Spesso i tubi di produttori diversi non sono compatibili tra loro, e i produttori avvertono di non sparare mai con un fucile multichoke senza strozzatori.", "I nomi vengono dall'inglese, dal più aperto al più stretto: cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. In Europa si usano spesso le frazioni: un quarto (quarter, improved cylinder), mezzo (half, modified), tre quarti (three-quarter, improved modified) e full, piena strozzatura. Molti fucili italiani indicano gli strozzatori con le stelle, e lì la regola è capovolta: più stelle significa uno strozzatore più aperto.", "Gli istruttori dicono cose come «quarter and half» (un quarto e mezzo), «open up the bottom barrel» (apri la canna inferiore), «go tighter in the top» (più strozzato sopra) o «change chokes for this stand» (cambia strozzatori per questa pedana). Riporta i nomi esattamente come li dice l'istruttore; non convertirli in millimetri, che variano da un produttore all'altro.", "Le regole cambiano da una disciplina all'altra. Nel Parcours de Chasse – Sporting™ gli strozzatori si possono cambiare tra una pedana e l'altra, o tra i singoli e i doppi, se non causa ritardi, ma mai quando il tiratore è già salito in pedana. Nel Compak® Sporting fucile, canne e strozzatori non si possono cambiare affatto durante una serie, solo tra una serie e l'altra, salvo in caso di guasto."], "key_points": ["Lo strozzatore restringe la volata: più stretto per i piattelli lontani, più aperto per quelli vicini.", "I tubi intercambiabili si avvitano con la chiave per strozzatori; i produttori avvertono di non sparare mai senza.", "Frazioni: un quarto = improved cylinder, mezzo = modified, tre quarti = improved modified, full.", "Riporta i nomi degli strozzatori come vengono detti; non convertirli in millimetri.", "Sporting™: cambio tra le pedane, mai in pedana; Compak®: nessun cambio durante una serie."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Improved cylinder in una canna, modified nell'altra.", "say": "Che strozzatori usi? Un quarto e mezzo."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Strozzatore più aperto per il primo piattello, più vicino; più stretto per il secondo, più lontano.", "say": "Metti il quarto sotto e il mezzo sopra: il secondo piattello è più lungo."}, {"en": "Open up — these are all close.", "meaning": "Monta strozzatori più aperti, perché i piattelli sono vicini.", "say": "Apri: sono tutti vicini."}, {"en": "Check your tubes are tight before the round.", "meaning": "Assicurati che gli strozzatori non si siano allentati.", "say": "Prima della serie controlla che gli strozzatori siano ben stretti."}], "quiz": [{"q": "Quale strozzatore dà la rosata più ampia?", "options": ["Full", "Improved modified", "Modified", "Cylinder"], "answer": 3, "why": "Il cylinder non ha strozzatura, quindi i pallini si allargano prima."}, {"q": "Nello Sporting™ un tiratore già in pedana vuole cambiare uno strozzatore. È consentito?", "options": ["Sì, purché non causi ritardi", "No, non quando è già in pedana", "Sì, ma solo prima dei doppi", "Solo con il permesso della giuria"], "answer": 1, "why": "I cambi sono ammessi tra le pedane o tra i singoli e i doppi, senza ritardi, ma mai quando il tiratore è già salito in pedana."}, {"q": "Su un fucile italiano, uno strozzatore a cinque stelle è…", "options": ["il più aperto", "il più stretto", "uno strozzatore rotto", "una canna rigata"], "answer": 0, "why": "Con la marcatura a stelle, più stelle significa uno strozzatore più aperto."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Le cartucce: calibro, numero del pallino e limiti", "body": ["Una cartuccia (cartridge) contiene tutto il necessario per un colpo: il bossolo (hull) con il fondello metallico, l'innesco (primer), la polvere (powder), la borra (wad) e i pallini (shot). I tiratori inglesi dicono anche shell. Gli «empties» sono i bossoli sparati.", "Il calibro (gauge) si conta alla vecchia maniera: più piccolo è il numero, più larga è la canna, quindi il calibro 12 è più largo del 20. La FITASC ammette fucili non più grandi del calibro 12 e la maggior parte dei tiratori usa il 12. Non tradurre mai «12 gauge» con «12 mm».", "Anche il numero del pallino è al contrario: più alto è il numero, più piccolo è il pallino, quindi il n. 9 è più fine del n. 7½. Lo stesso numero può indicare misure leggermente diverse in Gran Bretagna, nell'Europa continentale e negli Stati Uniti, quindi riporta il numero così com'è e controlla i millimetri sulla scatola. «Nines» (il 9) e «seven-and-a-halfs» (il 7½) sono parole frequenti in bocca agli istruttori.", "Le regole del Parcours de Chasse – Sporting™ e del Compak® Sporting sono le stesse: al massimo 28 g di pallini di piombo, con una tolleranza del +2%; pallini sferici da 2,0 a 2,5 mm (±0,1 mm). Sono vietati le cartucce ricaricate, i dispersori, i pallini di misure diverse mescolati, la polvere nera e i traccianti. Nello Sporting™ l'arbitro può prelevare due cartucce da controllare, una da ciascuna tasca del gilet; nel Compak® Sporting i colpi sparati con cartucce non conformi prima di un controllo valgono zero.", "Alcuni campi aggiungono proprie regole ambientali per l'allenamento, per esempio solo borre in feltro o solo pallini d'acciaio: controlla le regole del campo prima del tour. I bossoli vuoti vanno nel contenitore in pedana e chi tira con il semiautomatico raccoglie i propri bossoli espulsi quando se ne va."], "key_points": ["Cartuccia = bossolo, innesco, polvere, borra, pallini.", "Calibro: numero più piccolo, canna più larga; il massimo FITASC è il calibro 12.", "Numero del pallino: numero più alto, pallino più piccolo; la numerazione cambia da paese a paese, controlla i millimetri.", "Limiti: 28 g di piombo (+2%), pallini da 2,0–2,5 mm; niente ricariche, pallini misti, polvere nera o traccianti.", "I bossoli vuoti nel contenitore; chi usa il semiautomatico raccoglie i propri bossoli."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Pallino più fine n. 9 per i piattelli vicini, più grosso n. 7½ per i traversoni lontani.", "say": "Il 9 per i piattelli vicini, il 7½ per i traversoni lunghi."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "Il limite di carica della gara, come nel regolamento FITASC.", "say": "In questa gara massimo ventotto grammi."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Metti i bossoli sparati nel contenitore.", "say": "I bossoli nel contenitore, per favore, non sull'erba."}, {"en": "Steel only on this ground.", "meaning": "Su questo campo i pallini di piombo non sono ammessi (una regola locale, non della FITASC).", "say": "Su questo campo solo acciaio."}], "quiz": [{"q": "Qual è il pallino più fine?", "options": ["N. 7", "N. 7½", "N. 8", "N. 9"], "answer": 3, "why": "Più alto è il numero del pallino, più piccolo è il pallino."}, {"q": "Qual è la carica massima di pallini secondo il regolamento FITASC?", "options": ["24 g, senza tolleranza", "28 g, con una tolleranza del +2%", "32 g, solo per i piattelli lunghi", "Nessun limite, qualsiasi carica è ammessa"], "answer": 1, "why": "Entrambe le discipline ammettono al massimo 28 g di pallini di piombo, +2%."}, {"q": "Un cliente dice che il suo fucile è un «12 gauge». Che cosa significa?", "options": ["La misura della canna: più larga del calibro 20", "La canna ha un diametro di 12 millimetri", "Nel serbatoio entrano dodici cartucce", "Le canne sono lunghe 12 pollici"], "answer": 0, "why": "Il calibro è un'unità antica: più piccolo è il numero, più larga è la canna. Non sono millimetri."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Protezioni, gilet e abbigliamento", "body": ["Le protezioni auditive sono obbligatorie per tutti quelli che si trovano su un campo o vicino: tiratori, arbitri, personale e spettatori, e quindi anche per te. Vanno bene sia i tappi auricolari (earplugs) sia le cuffie (ear muffs); le cuffie elettroniche amplificano le voci e attenuano lo sparo, cosa che ti aiuta a sentire l'istruttore e l'arbitro. Un tiratore che si presenta in pedana senza protezioni è considerato assente.", "Anche gli occhiali di protezione (safety glasses) sono obbligatori, per tiratori, arbitri e personale e, nel Parcours de Chasse – Sporting™, per chiunque si trovi vicino a una pedana. Le lenti hanno diversi colori (giallo, arancione, viola, fumé) per vedere meglio i piattelli con luci diverse.", "Il gilet da tiro (shooting vest) tiene le cartucce in due tasche anteriori e ha un'imbottitura sulla spalla. Per lo Sporting™ porta una linea orizzontale di colore contrastante 25 cm sotto l'asse delle spalle: prima della chiamata la parte superiore del calcio deve restare sotto questa linea, e l'arbitro lo controlla. Il Compak® Sporting non ha questa linea, perché la posizione del fucile alla chiamata è libera.", "Le regole sull'abbigliamento sono le stesse in entrambe le discipline: niente pantaloncini corti (solo bermuda che finiscono non più di 5 cm sopra il ginocchio), magliette almeno a maniche corte, niente gilet sul petto nudo e niente sandali, per sicurezza. Il pettorale si porta sulla schiena, ben visibile. Una violazione comporta prima un avvertimento, poi ulteriori penalizzazioni.", "Molti tiratori portano anche un cappellino con visiera contro il sole e la pioggia, i guanti, e hanno una borsa portacartucce per la scorta della giornata. Queste sono abitudini, non regole."], "key_points": ["Le protezioni auditive sono obbligatorie per tutti vicino a un campo, interpreti compresi.", "Gli occhiali di protezione sono obbligatori; senza protezioni il tiratore è considerato assente.", "Gilet per lo Sporting™: linea di colore contrastante 25 cm sotto l'asse delle spalle; il Compak® non ce l'ha.", "Abbigliamento: pantaloncini non più di 5 cm sopra il ginocchio, maniche, niente petto nudo sotto il gilet, niente sandali.", "Pettorale sulla schiena, ben visibile."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Metti protezioni auditive e occhiali prima di avvicinarti alla pedana.", "say": "Cuffie e occhiali prima di salire."}, {"en": "Butt under the tape until you see the target.", "meaning": "Regola dello Sporting™ sul fucile non imbracciato: il calcio resta sotto la linea del gilet finché non compare il piattello.", "say": "Calcio sotto la linea finché non vedi il piattello."}, {"en": "No marker needed here — it's Compak.", "meaning": "Il Compak® non prevede la linea sul gilet.", "say": "Qui la linea non serve: è Compak."}], "quiz": [{"q": "Sei un interprete e stai vicino alla pedana. Devi indossare le protezioni auditive?", "options": ["No, solo i tiratori in pedana", "Solo durante le finali e gli spareggi", "Sì, tutti quelli che si trovano su un campo o vicino", "Solo se te lo chiede l'arbitro"], "answer": 2, "why": "Le protezioni auditive sono obbligatorie per tiratori, arbitri, personale e spettatori."}, {"q": "Dov'è la linea sul gilet nello Sporting™?", "options": ["25 cm sotto l'asse delle spalle", "In vita, all'altezza della cintura", "Sulla manica del braccio che spara", "Nello Sporting™ non c'è"], "answer": 0, "why": "La linea di colore contrastante è 25 cm sotto l'asse delle spalle e parallela a esso; il calcio deve restare sotto prima che compaia il piattello."}, {"q": "Quali calzature sono vietate in entrambe le discipline?", "options": ["Scarpe da trail", "Sandali", "Scarponcini", "Scarpe da ginnastica"], "answer": 1, "why": "I sandali sono vietati per motivi di sicurezza."}]}]}, {"id": "targets", "icon": "target", "title": "I piattelli", "intro": "Un istruttore che dice «it's a midi off the tower, then a rabbit on report» (un midi dalla torre, poi una lepre allo sparo) dà per scontato che tu riesca a immaginarlo. Questa missione ti insegna i tipi di piattello, come il colore e la luce cambiano ciò che vede il tiratore, come le macchine lanciano i piattelli, come si legge un menu e l'unica domanda di punteggio che decide tutto: colpito o perso.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Tipi di piattello: standard, midi, mini, battuta, lepre, flash, ZZ", "body": ["L'elenco FITASC per il Parcours de Chasse – Sporting™ indica sette tipi di piattello: standard, midi, super mini, battuta (battue), lepre (rabbit), flash e ZZ. Il Compak® Sporting ammette qualsiasi piattello standard o speciale e nel suo elenco compare anche il rocket. Ogni tipo vola in modo diverso.", "Lo standard, il piattello più comune, è una cupola di circa 108–110 mm di diametro. Il midi è di 90 mm: mantiene bene la velocità e sembra più lontano di quanto sia. Il mini è di 60 mm: esce dalla macchina veloce e rallenta in fretta, quindi i tiratori tendono a dargli troppo anticipo. L'elenco dello Sporting™ chiama il piattello piccolo «super mini» e la regola sul menu indica sia la misura da 70 mm sia quella da 60 mm; i nomi non sono usati in modo uniforme, quindi fai sempre riferimento ai millimetri scritti sul menu.", "La battuta (battue) è un piattello piatto e sottile da 110 mm. Vola di taglio, quasi invisibile, poi si gira mostrando la faccia e scende rapidamente. La lepre (rabbit) è un piattello da 110 mm con un bordo spesso e robusto, lanciato di taglio a rotolare sul terreno; rimbalza e può saltare sulle gobbe. In Italia sentirai sia «lepre» sia «rabbit»; questo corso usa «lepre».", "Il piattello flash è riempito di polvere colorata che lascia una nuvola ben visibile quando viene colpito; si conta come qualsiasi altro piattello. Il piattello ZZ, detto anche elica (helice), è un'elica di plastica con un cappuccio centrale bianco che vola in modo irregolare. Il rocket è un piattello speciale citato solo nell'elenco del Compak® Sporting; non ne diamo le specifiche.", "Nello Sporting™ un piattello di colore, misura o tipo sbagliato è un No bird e viene ripetuto."], "key_points": ["Elenco dello Sporting™: standard, midi, super mini, battuta, lepre, flash, ZZ; il Compak® ammette qualsiasi tipo, rocket compreso.", "Standard circa 108–110 mm, midi 90 mm, mini 60 mm; il menu può indicare anche 70 mm: fai riferimento ai millimetri.", "Battuta: piatta, vola di taglio, si gira e scende; lepre: bordo spesso, rotola e salta.", "Il flash lascia una nuvola di polvere; lo ZZ è un piattello a elica.", "Sporting™: colore, misura o tipo sbagliato = No bird."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "Un piattello da 90 mm sembra più lontano di quanto sia, quindi serve meno anticipo di quanto pensi il tiratore.", "say": "Il midi sembra lontano ma non lo è: non dargli troppo anticipo."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Spara alla battuta quando ti mostra la sua faccia piatta.", "say": "La battuta alla fine si gira e scende: prendila quando ti fa vedere la pancia."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "Il piattello piccolo perde velocità in fretta; non aspettare.", "say": "Il mini muore in fretta: sparagli presto."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Tieni le volate basse sul piattello che rotola, così anche se salta incontra la rosata.", "say": "Su quella gobba la lepre salta: stai sotto."}], "quiz": [{"q": "Quale piattello rotola sul terreno?", "options": ["Midi", "Battuta", "Lepre", "Flash"], "answer": 2, "why": "La lepre (rabbit) ha un bordo spesso e viene lanciata di taglio sul terreno."}, {"q": "Il menu dice «70 mm». L'istruttore lo chiama mini. Che cosa traduci?", "options": ["Correggi in 60 mm, visto che un mini è di 60 mm", "Mantieni la parola dell'istruttore e i 70 mm del menu", "Lo chiami midi, visto che supera i 60 mm", "Chiedi all'istruttore di dire «super mini»"], "answer": 1, "why": "Il regolamento indica le misure da 70 mm e da 60 mm e il nome «super mini»; fidati dei millimetri sul menu e non correggere l'istruttore."}, {"q": "Su una pedana di Sporting™ una macchina lancia un midi invece dello standard indicato nel menu. Che cosa succede?", "options": ["No bird, il piattello si ripete", "Conta come colpito", "Il tiratore perde il piattello", "La serie viene annullata"], "answer": 0, "why": "Nello Sporting™ un piattello di colore, misura o tipo sbagliato è un No bird e viene ripetuto."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Colori, luce e visibilità", "body": ["Entrambi i regolamenti chiedono la stessa cosa: il colore del piattello deve risaltare chiaramente sullo sfondo. I piattelli bicolori sono sconsigliati. Quindi il colore è una scelta del tracciatore del percorso, fatta per ogni traiettoria, e non un tipo di piattello a sé.", "Sentirai parlare di piattelli neri, arancioni, bianchi, gialli e rosa. Molti tracciatori usano il nero contro il cielo e l'arancione contro gli alberi e l'erba. Un piattello «blazed» ha la cupola dipinta di arancione brillante. Attenzione: quando l'istruttore dice «the orange one» (quello arancione), intende un colore, non una misura. Un midi nero e uno standard arancione possono partire dalla stessa pedana.", "Se viene lanciato un piattello del colore sbagliato, l'arbitro chiama No bird e il piattello si ripete. Nel Compak® Sporting il regolamento aggiunge che il maltempo non è mai un motivo per un No bird: un piattello rotto conta e uno mancato è perso, qualunque siano le condizioni. Nel Parcours de Chasse – Sporting™ l'arbitro può sospendere il tiro per un temporale o un acquazzone breve e violento.", "La luce cambia tutto. Gli istruttori parlano di controluce (il sole dietro il piattello), luce piatta nelle giornate grigie, ombre sotto gli alberi e dello sfondo dietro il piattello: cielo, linea degli alberi o terreno. Un piattello può «sparire» contro alberi scuri e «saltare fuori» contro il cielo. Per questo i tiratori cambiano il colore delle lenti nel corso della giornata.", "Quando traduci, mantieni le parole su colore e luce precise e brevi: «it's coming out of the dark trees» (esce dagli alberi scuri), «you lose it in the sun» (lo perdi nel sole). Spiegano perché un tiratore ha sbagliato, quindi sono importanti."], "key_points": ["Il colore del piattello deve risaltare sullo sfondo; i piattelli bicolori sono sconsigliati.", "Il colore non è il tipo: «the orange one» è un colore, non una misura.", "Colore sbagliato = No bird.", "Compak®: il maltempo non giustifica mai un No bird; nello Sporting™ l'arbitro può sospendere per un breve temporale.", "Controluce, luce piatta, sfondo: traduci con precisione le parole sulla luce."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Due piattelli della pedana sono diversi per colore e misura.", "say": "Quello nero è il midi, quello arancione è lo standard: non confonderli."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "Davanti agli alberi il piattello si vede male; comincia a guardarlo dove dietro c'è il cielo.", "say": "Contro gli alberi lo perdi: prendilo più tardi, nel cielo."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Luce grigia, senza contrasto; una lente gialla aiuta il contrasto.", "say": "Oggi luce piatta: metti la lente gialla."}], "quiz": [{"q": "Che cosa richiede il regolamento per il colore del piattello?", "options": ["Deve essere sempre arancione", "Deve risaltare chiaramente sullo sfondo", "Deve essere bicolore", "Qualsiasi colore: il regolamento non dice nulla"], "answer": 1, "why": "Il requisito è la visibilità sullo sfondo; i piattelli bicolori sono sconsigliati."}, {"q": "Nel Compak® Sporting comincia a piovere forte e un tiratore sbaglia. Può chiedere un No bird per il maltempo?", "options": ["Sì, il maltempo lo giustifica sempre", "Solo per il primo piattello di un doppio", "Solo se la giuria è d'accordo", "No, il maltempo non giustifica mai un No bird"], "answer": 3, "why": "Il regolamento del Compak® Sporting stabilisce che il maltempo non è mai un motivo per un No bird."}, {"q": "L'istruttore dice «Watch the orange one». Che cosa sta descrivendo?", "options": ["Il colore di un piattello", "Un piattello da 90 mm", "Una lepre", "Un piattello rotto"], "answer": 0, "why": "Il colore si sceglie per la visibilità e non dice nulla sulla misura o sul tipo."}]}, {"id": "targets-traps", "minutes": 5, "title": "Le macchine, il lancio e il puller", "body": ["La macchina lanciapiattelli (trap) è la macchina che lancia i piattelli. Le macchine possono essere manuali o automatiche (il regolamento del Compak® Sporting cita anche quelle semiautomatiche). Nel Parcours de Chasse – Sporting™ le macchine di una pedana sono contrassegnate A, B, C, D da sinistra a destra come si vedono dalla pedana; nel Compak® Sporting le sei macchine vanno dalla A alla F, ognuna con un pannello con la lettera. Mantieni le lettere latine quando traduci: il menu le usa.", "Il tiratore fa partire il piattello con la chiamata: il regolamento indica «pull» o «ready» (in Italia anche «Pronto!» o «Via!»), ma in pratica le parole di chiamata variano da tiratore a tiratore. Nello Sporting™ l'arbitro trasmette il comando al puller (trapper, l'addetto al lancio che aziona la macchina) con un segnale acustico, e il piattello deve partire entro tre secondi. Non tradurre la chiamata in sé: è un comando per la macchina, non una frase.", "Nel Compak® Sporting i piattelli possono essere lanciati a mano, con un telecomando o con un phonopull (sonopull) a comando vocale. Con il lancio manuale il piattello parte da 0 a 3 secondi dopo la chiamata; il phonopull ha un ritardo fisso di 0,5 secondi. Il Compak® Sporting internazionale in linea usa solo il phonopull con arbitraggio elettronico.", "Il lancio a comando vocale ha un microfono sulla pedana. Anche la tua voce può farlo scattare. Su una pedana di questo tipo non parlare mai ad alta voce mentre il tiratore è pronto: sussurra tra un piattello e l'altro o fai un passo indietro.", "Gli errori della macchina sono No bird: un piattello lanciato più di tre secondi dopo la chiamata, un piattello dalla macchina sbagliata, un piattello lanciato senza chiamata, due piattelli da macchine della stessa pedana nello Sporting™, o un piattello lanciato per errore da una macchina dello stesso Compak."], "key_points": ["Macchine: A–D per pedana nello Sporting™, A–F su un campo di Compak®; mantieni le lettere latine.", "La chiamata («pull», «ready») fa partire il piattello; non tradurla.", "Sporting™: l'arbitro dà il segnale al puller; il piattello deve partire entro 3 secondi.", "Compak®: lancio manuale 0–3 s, telecomando o phonopull con ritardo fisso di 0,5 s.", "I piattelli in ritardo, dalla macchina sbagliata o senza chiamata sono No bird; un microfono può sentirti."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "La traiettoria della macchina è cambiata; il tiratore deve segnalarlo prima di sparare.", "say": "La macchina B lancia più basso che nella presentazione: dillo all'arbitro."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Un microfono fa partire i piattelli; parlando se ne può lanciare uno.", "say": "Qui c'è il comando vocale: niente chiacchiere in pedana."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "Il piattello è partito più di tre secondi dopo la chiamata.", "say": "Su quello il puller era in ritardo: è un no bird."}], "quiz": [{"q": "Nello Sporting™, quanto tempo può passare tra il segnale dell'arbitro e la partenza del piattello?", "options": ["Fino a 1 secondo", "Fino a 3 secondi", "Fino a 10 secondi", "Qualsiasi tempo"], "answer": 1, "why": "Un piattello lanciato dopo più di tre secondi è un No bird."}, {"q": "Qual è il ritardo fisso del phonopull nel Compak®?", "options": ["0 secondi", "3 secondi", "0,5 secondi", "Lo imposta ogni tiratore"], "answer": 2, "why": "Il phonopull deve applicare un ritardo fisso e non modificabile di 0,5 secondi."}, {"q": "Sei su una pedana con comando vocale e il tiratore è pronto. Che cosa fai?", "options": ["Traduci ad alta voce perché ti senta", "Chiedi al puller di aspettare un momento", "Ripeti per lui la parola di chiamata", "Stai in silenzio; sussurra solo tra un piattello e l'altro"], "answer": 3, "why": "La tua voce può far scattare il microfono e lanciare un piattello che nessuno ha chiamato."}]}, {"id": "targets-menu", "minutes": 5, "title": "Leggere il menu dei piattelli", "body": ["Il menu dei piattelli (target menu) è il cartello sulla pedana che dice al tiratore che cosa arriverà. I tiratori dicono davvero «menu», quindi mantieni la parola.", "Nel Parcours de Chasse – Sporting™ il menu elenca le macchine nell'ordine di tiro e deve indicare i piattelli speciali: 90 mm, 70 mm, 60 mm, battuta o lepre. Gli arbitri controllano in anticipo che le macchine corrispondano al menu. Un layout dà 15 singoli e 5 doppi, e i doppi possono usare solo piattelli già presentati come singoli dalla stessa pedana. La batteria tira prima i singoli, poi i doppi.", "Un doppio è indicato con il suo tipo: allo sparo (on report: il secondo piattello parte al suono del primo colpo), simultaneo (simultaneous: entrambi insieme) o a raffica (rafale: due dalla stessa macchina, uno dopo l'altro; solo nello Sporting™). I menu cambiano da campo a campo, quindi leggi le parole, non solo le lettere. Esempio per una pedana con tre macchine: singoli A, B, C; doppi A + B simultaneo e C + C a raffica (su una pedana così non sono ammessi due doppi allo sparo).", "Nel Compak® Sporting c'è un menu su ciascuna delle cinque pedane. Ogni pedana ha cinque piattelli: cinque singoli, tre singoli e un doppio, oppure un singolo e due doppi. Il tipo di doppio è lo stesso su tutte e cinque le pedane di un Compak, e il primo piattello di ogni doppio è l'ultimo piattello della pedana precedente. La FITASC offre 40 menu già pronti per le gare.", "Prima che il tuo tiratore salga in pedana, leggigli il menu ad alta voce nella sua lingua, lettera per lettera: «A, poi F, poi il doppio C ed E allo sparo»."], "key_points": ["Mantieni la parola «menu».", "Menu dello Sporting™: macchine in ordine più i piattelli speciali (90, 70, 60 mm, battuta, lepre).", "15 singoli + 5 doppi; i doppi usano piattelli già presentati come singoli; prima i singoli.", "Doppi: allo sparo, simultaneo, a raffica (solo Sporting™).", "Compak®: cinque piattelli per pedana, stesso tipo di doppio su tutte le pedane, ogni doppio comincia con l'ultimo piattello della pedana precedente."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then the pair C and E on report.", "meaning": "L'ordine dei piattelli alla pedana 3, che finisce con un doppio allo sparo.", "say": "Leggi il menu: alla pedana tre hai A, poi F, poi il doppio C ed E allo sparo."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "L'ordine è cambiato rispetto alla serie precedente.", "say": "Stesse macchine, menu nuovo: non sparare a memoria."}, {"en": "Three singles, then a simo pair.", "meaning": "«Simo» è l'abbreviazione di doppio simultaneo.", "say": "Tre singoli, poi un doppio simultaneo."}], "quiz": [{"q": "Quali piattelli speciali deve indicare un menu dello Sporting™?", "options": ["Solo i colori dei piattelli", "90 mm, 70 mm, 60 mm, battuta o lepre", "Solo lepri e battute", "Nessuno; li annuncia l'arbitro"], "answer": 1, "why": "Il menu deve elencare le macchine in ordine e ogni tipo di piattello speciale."}, {"q": "Nel Compak® Sporting, con quale piattello comincia ogni doppio?", "options": ["Sempre con la macchina A", "Con un piattello mai visto prima", "Con l'ultimo piattello tirato alla pedana precedente", "Con qualsiasi piattello scelga il tiratore"], "answer": 2, "why": "I doppi si concatenano tra le pedane: ognuno comincia con l'ultimo piattello della pedana precedente."}, {"q": "Quale tipo di doppio esiste solo nello Sporting™?", "options": ["A raffica", "Allo sparo", "Simultaneo", "Nessuno"], "answer": 0, "why": "I doppi del Compak® sono allo sparo o simultanei; il doppio a raffica è dello Sporting™."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Colpito o perso: il pezzo visibile e la trappola del «fumo»", "body": ["Un piattello vale «uno» (colpito, in Italia l'arbitro dice «Buono») quando è stato lanciato regolarmente, il tiratore ha sparato secondo le regole e almeno un pezzo visibile si è staccato, oppure il piattello è stato distrutto del tutto o in parte. I piattelli flash seguono la stessa regola. Un piattello vale «zero» (perso, «Zero») quando non si stacca nessun pezzo visibile e c'è solo polvere o fumo.", "Quindi la regola dipende da un'unica immagine: un pezzo visibile. Una piccola scheggia che vola via conta come colpito. Uno sbuffo di polvere con il piattello che continua a volare intero è perso. Sullo statino di solito un piattello colpito si segna X e un errore O.", "Decide solo l'arbitro. I membri della batteria non possono esprimere opinioni e nessuno può raccogliere un piattello per controllarlo. Nel Compak® Sporting l'arbitro annuncia ogni zero ad alta voce o con un segnale acustico. Nel Parcours de Chasse – Sporting™ il tiratore deve rompere i piattelli dove l'arbitro può vederli. Chiamando il piattello successivo il tiratore accetta la decisione sul precedente, quindi qualsiasi obiezione va fatta subito.", "Ed ecco la trappola per gli interpreti. Gli istruttori lodano un colpo perfetto con «smoked it», «inked it» o «powdered it» (l'hai polverizzato): il piattello si è trasformato in una nuvola nera. È il miglior colpo possibile, non uno zero. Ma nel regolamento «solo polvere o fumo» significa perso. «Dusted it» è rischioso: di solito significa che si è alzata solo polvere, quindi piattello perso, ma alcuni lo usano come complimento. Se non sei sicuro, chiedi, perché i due significati sono opposti.", "Inoltre: «dead» significa colpito (non «morto»), «lost» significa mancato (si dice «zero», non «perso» nel senso di smarrito)."], "key_points": ["Uno = almeno un pezzo visibile si è staccato, oppure il piattello è stato distrutto del tutto o in parte.", "Zero = nessun pezzo visibile, solo polvere o fumo.", "Decide solo l'arbitro; non si raccolgono i piattelli; chiamare il piattello successivo significa accettare la decisione.", "Gergo degli istruttori «smoked it» = colpo perfetto; formula del regolamento «solo fumo» = perso.", "«Dead» = colpito, «lost» = mancato; chiedi se «dusted» non è chiaro."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Un colpo perfetto: il piattello è diventato polvere; il tiratore deve ricordare quell'immagine.", "say": "Polverizzato! Ecco l'immagine giusta."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Si è staccato un piccolo pezzo visibile, quindi è colpito.", "say": "Buono: solo una scheggia, ma conta."}, {"en": "Lost — you were just behind it.", "meaning": "Un errore; la rosata è passata dietro il piattello.", "say": "Zero: eri appena dietro."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "Un'obiezione va fatta subito; chiamando il piattello successivo si accetta la decisione.", "say": "Non venire a discutere dopo: dimmelo adesso, prima di chiamare."}], "quiz": [{"q": "Il piattello continua a volare intero, ma compare uno sbuffo di polvere. Qual è il punteggio?", "options": ["Zero (perso)", "Uno (colpito)", "No bird", "Mezzo punto"], "answer": 0, "why": "Solo polvere o fumo, senza un pezzo visibile, significa perso."}, {"q": "L'istruttore grida «Smoked it!». Come ne traduci il significato?", "options": ["Ha fatto solo fumo, quindi il piattello è perso", "Le canne si stanno surriscaldando", "Un colpo perfetto: il piattello è diventato polvere", "La macchina lanciapiattelli sta bruciando"], "answer": 2, "why": "Nel gergo degli istruttori «smoked it» è un complimento per una rottura totale; la formula del regolamento «solo fumo» significa il contrario."}, {"q": "Un membro della batteria dice che l'ultimo piattello è stato colpito. Chi decide?", "options": ["Una votazione della batteria", "L'istruttore", "L'interprete", "Solo l'arbitro"], "answer": 3, "why": "Le decisioni sui piattelli spettano all'arbitro; i membri della batteria non possono intervenire."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Come volano i piattelli (le presentazioni)", "intro": "Gli istruttori chiamano ogni piattello in base a come vola: crosser, incomer, teal, looper, rabbit, report pair. In sei brevi lezioni imparerai che cosa significa ciascun nome, che cosa deve fare il tiratore con quel piattello e quali parole è facile tradurre male.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "Il traversone (crosser): un piattello che vola di traverso", "body": ["Il traversone (crosser) attraversa il campo visivo davanti al tiratore, più o meno ad angolo retto rispetto alla linea dello sguardo: da sinistra a destra (si scrive L→R) o da destra a sinistra (R→L). Su un layout di Parcours de Chasse – Sporting™ il regolamento chiede un insieme di traversoni, diagonali, piattelli in arrivo e in allontanamento. Nel Compak® Sporting un traversone da sinistra a destra e uno da destra a sinistra sono due delle tre traiettorie obbligatorie, quindi ogni Compak li ha.", "Il traversone mostra tutta la sua velocità laterale, quindi è la presentazione che richiede più anticipo (lead, lo spazio da dare davanti al piattello), e più è lontano, più anticipo serve. Un «long crosser» è un traversone lontano, non uno che vola a lungo.", "Leggine la linea e la velocità: vola piatto, sale o è già in discesa al punto di rottura? Mostra la faccia (la cupola o la pancia) o solo il taglio? Rallenta? Un traversone che rallenta richiede meno anticipo di uno a piena velocità.", "Piano tipico: piedi orientati verso il punto di rottura, occhi che lo prendono presto, poi pull-away o anticipo mantenuto (maintained lead), con il fucile ancora in movimento al momento dello sparo. Il verdetto più frequente dell'istruttore su un traversone è «behind», dietro: anticipo insufficiente, oppure fucile che si è fermato.", "Le direzioni si danno dal punto di vista del tiratore. Se stai di fronte al tiratore, il suo «da sinistra a destra» per te è da destra a sinistra, quindi non invertire mai le parole."], "key_points": ["Il traversone vola di traverso a circa 90° rispetto alla linea dello sguardo: L→R o R→L.", "Richiede il massimo anticipo; più distanza significa più anticipo.", "«Long crosser» = lontano, non di lunga durata.", "Il Compak® Sporting ha sempre un traversone L→R e uno R→L.", "Sinistra e destra sono sempre dal punto di vista del tiratore."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "Il piattello è lontano e vola dalla destra alla sinistra del tiratore; dagli l'anticipo previsto e non fermare lo swing.", "say": "Traversone lungo, da destra a sinistra: fidati dell'anticipo e tieni il fucile in movimento."}, {"en": "You're behind it — give it more.", "meaning": "La rosata è passata dietro il piattello: serve più anticipo.", "say": "Sei dietro: dagliene di più."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "Dove il tiratore lo rompe, il traversone sta già scendendo, quindi il fucile deve passare leggermente sotto la sua traiettoria.", "say": "Al tuo punto di rottura scende: stai sotto la linea."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Cerca il piattello più vicino alla macchina del solito, perché esce veloce.", "say": "Prendilo presto, esce veloce dalla macchina."}], "quiz": [{"q": "Quale presentazione richiede di solito più anticipo?", "options": ["Un piattello che si allontana dritto", "Un piattello in arrivo dritto verso il tiratore", "Un traversone alla stessa distanza", "Una lepre che rotola dritta in allontanamento"], "answer": 2, "why": "Il traversone mostra tutta la sua velocità laterale, quindi il fucile deve stare più avanti; i piattelli in linea retta richiedono poco anticipo laterale."}, {"q": "L'istruttore dice «long crosser». Che cosa significa «long»?", "options": ["Il piattello è lontano", "Il piattello vola a lungo", "Il piattello è lungo e ovale", "Il tiratore deve aspettare a lungo"], "answer": 0, "why": "Nel linguaggio degli istruttori «long» indica la distanza. Un long crosser è un traversone lontano, che richiede più anticipo."}, {"q": "Che cosa è vero dei traversoni nel Compak® Sporting?", "options": ["Su un Compak i traversoni non sono ammessi", "Sono ammessi solo i traversoni da destra a sinistra", "I traversoni si possono lanciare solo come lepri", "Un traversone L→R e uno R→L sono obbligatori"], "answer": 3, "why": "Il regolamento del Compak® Sporting rende obbligatorie tre traiettorie: un traversone L→R, un traversone R→L e un piattello in allontanamento."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "In arrivo, in allontanamento, passante alto e sopra la testa", "body": ["Un piattello in arrivo (incomer) vola verso il tiratore, spesso da una macchina lontana o da una torre, e di solito scende man mano che si avvicina. Può sembrare che rallenti e resti sospeso, e questo spinge il tiratore a mirare. Normalmente si prende davanti, prima che arrivi sopra la testa, e al momento dello sparo le canne possono coprire («blot out») il piattello. È voluto, non è un errore.", "Un piattello in allontanamento (going-away, detto anche fuggente) parte vicino o dietro al tiratore e vola via. Richiede poco anticipo laterale, ma rimpicciolisce in fretta e spesso sale o scende, quindi l'anticipo è soprattutto verticale e conta il tempo: non aspettare. Nel Compak® Sporting un piattello in allontanamento sopra il lato BC è obbligatorio; può arrivare da una fossa davanti o da una torre dietro le pedane, almeno 4 m più in alto.", "Un piattello passante alto (driven) è un piattello in arrivo che passa sopra la testa del tiratore, come un fagiano spinto dai battitori. Prendilo presto, muoviti con lui, sali da dietro attraversandolo, spara quando le canne lo coprono e continua lo swing. Attenzione: in italiano «in battuta» (come il francese «en battue») indica la selvaggina spinta, non il piattello battuta.", "Un piattello da dietro sopra la testa (overhead from behind) arriva alle spalle del tiratore e si allontana. Si vede tardi, quindi il tiratore lo cerca presto guardando indietro, imbraccia accompagnandolo, spara quando la volata ne tocca la parte anteriore e accompagna il colpo (follow-through).", "«In arrivo» e «in allontanamento» descrivono sempre il piattello rispetto al tiratore."], "key_points": ["In arrivo: viene verso il tiratore, di solito scendendo; prendilo davanti.", "In allontanamento: poco anticipo laterale, soprattutto verticale; spara senza esitare.", "Passante alto (driven): un piattello in arrivo sopra la testa; attraversalo da dietro e coprilo.", "Da dietro sopra la testa: guarda indietro presto, imbraccia accompagnandolo, accompagna il colpo.", "Il Compak® Sporting comprende sempre un piattello in allontanamento."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Rompi il piattello in arrivo quando è ancora davanti, non quando è sopra la testa.", "say": "Prendilo davanti, prima che ti arrivi addosso."}, {"en": "Blot it out and keep swinging.", "meaning": "Lascia che le canne coprano il piattello al momento dello sparo e non fermare il fucile.", "say": "Coprilo e continua lo swing."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Spara subito al piattello in allontanamento, perché si allontana in fretta.", "say": "Non aspettare il fuggente: sta diventando piccolo."}, {"en": "It comes from behind you — look back for it early.", "meaning": "È un piattello da dietro sopra la testa; gira gli occhi verso di lui prima di chiamare.", "say": "Arriva da dietro: guarda indietro presto."}], "quiz": [{"q": "L'istruttore dice «Blot it out». Che cosa deve fare il tiratore?", "options": ["Pulire le lenti degli occhiali di protezione", "Lasciare che le canne coprano il piattello allo sparo", "Aspettare che il piattello sparisca dalla vista", "Sparare solo ai pezzi che cadono"], "answer": 1, "why": "Sui piattelli in arrivo, passanti alti e in salita il fucile spesso copre il piattello al momento dello sparo; l'istruttore chiede proprio questo."}, {"q": "Perché non bisogna lasciar andare troppo un piattello in allontanamento?", "options": ["Si allontana e rimpicciolisce in fretta", "Il regolamento concede solo tre secondi", "Diventa sempre un traversone", "Dopo il punto più alto l'arbitro chiama No bird"], "answer": 0, "why": "Un piattello in allontanamento guadagna distanza in fretta, quindi più aspetti, più diventa difficile. I tre secondi sono il tempo di lancio, non un limite per sparare."}, {"q": "Che cosa distingue un piattello passante alto (driven) da un normale piattello in arrivo?", "options": ["È sempre una lepre", "Arriva da dietro il tiratore", "Passa sopra la testa del tiratore", "Si lancia solo nel Compak® Sporting"], "answer": 2, "why": "Driven significa un piattello in arrivo che passa sopra la testa, come la selvaggina spinta. Un piattello che arriva da dietro è un overhead from behind."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Le diagonali: in allontanamento e in arrivo", "body": ["Una diagonale (quartering target) vola ad angolo: in parte di traverso, in parte in allontanamento o in arrivo. La diagonale in allontanamento (quartering away) si allontana dal tiratore ad angolo, per esempio verso destra in avanti. La diagonale in arrivo (quartering towards, detta anche «quartering in») viene verso il tiratore ad angolo e passa da un lato o scende davanti. L'angolo è spesso intorno ai 45°, ma è possibile qualsiasi valore tra un piattello dritto e un traversone pieno.", "L'anticipo dipende dall'angolo: più che per un piattello che si allontana dritto, meno che per un traversone pieno. Un angolo stretto richiede poco anticipo, uno quasi di traverso quasi quanto un traversone.", "La diagonale in allontanamento rimpicciolisce e rallenta in fretta, quindi va presa senza esitare. Il pull-away le si adatta bene, perché il fucile resta sulla linea del piattello. La diagonale in arrivo si ingrandisce e sembra lenta, cosa che spinge il tiratore ad aspettare; allora può passare troppo vicino o sparire dalla vista scendendo.", "La stessa macchina dà presentazioni diverse da pedane diverse: da una pedana un piattello è un traversone, dalla successiva è una diagonale. Per questo i piattelli vanno letti esattamente dalla pedana da cui sparerà il tiratore.", "In italiano di' «diagonale in allontanamento» e «diagonale in arrivo» (nel regolamento FITASC in italiano si trova anche «mezzo traverso»). Una parola costruita alla lettera su «quarter» («quarto») non dice nulla a un tiratore."], "key_points": ["Diagonale = piattello che vola ad angolo, tra il dritto e il traversone.", "La diagonale in allontanamento si allontana ad angolo; quella in arrivo (quartering in) arriva ad angolo.", "L'anticipo cresce con l'angolo: meno di un traversone, più di un piattello dritto.", "Una macchina si vede diversa da ogni pedana: leggila dalla tua pedana.", "In italiano: «diagonale in allontanamento / in arrivo»."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "Il primo piattello si allontana ad angolo verso la sinistra del tiratore; rompilo presto.", "say": "Il primo è una diagonale in allontanamento verso sinistra: prendilo subito, prima che diventi piccolo."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "Il piattello viene verso il tiratore ad angolo da destra; non aspettarlo.", "say": "Diagonale in arrivo da destra: non lasciarla avvicinare troppo."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "Il piattello è quasi dritto, quindi richiede solo un piccolo anticipo.", "say": "Meno anticipo di quanto pensi: l'angolo è minimo."}], "quiz": [{"q": "Un piattello viene verso il tiratore ad angolo e passa di lato. Come si chiama?", "options": ["In allontanamento", "Diagonale in arrivo", "Teal (candela)", "Doppio a raffica"], "answer": 1, "why": "La diagonale in arrivo (quartering towards o quartering in) è un piattello ad angolo che arriva; la diagonale in allontanamento è il piattello ad angolo che si allontana."}, {"q": "Come si confronta l'anticipo su una diagonale con quello su un traversone pieno alla stessa distanza e velocità?", "options": ["È uguale a quello del traversone", "È sempre zero", "È maggiore di quello del traversone", "È minore, a seconda dell'angolo"], "answer": 3, "why": "Solo la componente laterale del movimento richiede anticipo laterale, quindi più stretto è l'angolo, minore è l'anticipo."}, {"q": "Perché un piattello va letto esattamente dalla pedana da cui sparerai?", "options": ["Una macchina può essere un traversone da una pedana e una diagonale da un'altra", "Il regolamento vieta di guardare da qualsiasi altro punto", "I piattelli cambiano colore da una pedana all'altra", "Solo l'arbitro può stare altrove"], "answer": 0, "why": "L'angolo tra il tiratore e la linea del piattello cambia con la posizione, quindi cambia anche la presentazione."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Candela (teal), chandelle, parabola (looper) e piattelli in discesa", "body": ["Queste presentazioni riguardano l'altezza e la curva più che l'angolo. I loro nomi sono parole dei tracciatori, non termini del regolamento: il regolamento elenca i tipi di piattello, e quello del Compak® Sporting chiede traiettorie varie, per esempio in salita, in discesa e a campanile.", "Il teal (springing o rising teal, dal nome della piccola anatra alzavola; in italiano «candela») viene lanciato quasi in verticale, rallenta, si ferma in alto e ricade. Si prende o in salita, risalendolo dal basso, o in cima mentre resta sospeso. L'errore classico è «punzecchiarlo» in cima. Alcuni tracciatori usano «springing» (in italiano «frullo») per un piattello che sale ad angolo invece che in verticale, come un uccello che si alza.", "La chandelle (in francese «candela») sale ripida con una leggera curva, si incurva in alto e scende quasi in verticale. È più facile in salita; sulla curva l'anticipo va di lato e sotto.", "Il looper (in italiano «parabola») descrive un ampio arco nel cielo, come un arcobaleno, spesso con una battuta lanciata da una macchina inclinata: sale, gira la faccia e cade. Il fucile segue la curva, davanti e sotto.", "Un piattello in discesa (dropping target) è qualsiasi piattello nella parte discendente del suo volo. L'anticipo è in parte verticale: sotto e davanti, con il fucile in movimento.", "Attenzione: i nomi cambiano da paese a paese. Molti francofoni usano «chandelle» per un piattello che sale quasi in verticale, quello che un istruttore inglese chiama teal, e in italiano «candela» indica di solito proprio la salita verticale. Ogni volta che senti chandelle, candle o «candela», chiedi: dritto in su o ad arco?"], "key_points": ["Teal (candela): sale quasi in verticale, si ferma, ricade; prendilo in salita o in cima.", "Chandelle: salita ripida e curva, si incurva in alto, scende quasi in verticale.", "Looper (parabola): ampio arco ad arcobaleno, spesso una battuta che gira e cade.", "In discesa: anticipo sotto e davanti, non fermare mai il fucile.", "I nomi cambiano: i francofoni dicono spesso «chandelle» per il teal; anche «candela» va chiarita."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Rompi la candela in salita, prima del punto più alto; il fucile continua a salire oltre il piattello.", "say": "Prendi la candela in salita: tieni le canne in movimento sopra il piattello."}, {"en": "Don't poke at it on the top.", "meaning": "Non fermarti a mirare il piattello mentre è sospeso in cima.", "say": "Non punzecchiarlo in cima."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "Il piattello sta passando sopra il culmine dell'arco e comincia a cadere; l'anticipo va sotto e davanti.", "say": "La parabola si sta girando: sotto e davanti."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "Il secondo piattello del doppio sta cadendo; spara sotto di lui con il fucile in movimento.", "say": "Il secondo scende: vai sotto e tieni il fucile in movimento."}], "quiz": [{"q": "Quale piattello viene lanciato quasi in verticale, si ferma in alto e ricade?", "options": ["Looper (parabola)", "Diagonale in allontanamento", "Lepre", "Teal (candela)"], "answer": 3, "why": "È il teal (springing o rising teal, la candela). Il looper descrive un ampio arco nel cielo."}, {"q": "Dove va di solito l'anticipo su un piattello in discesa?", "options": ["Sopra e dietro", "Sotto e davanti", "Dritto sul piattello", "Solo di lato, mai in basso"], "answer": 1, "why": "Un piattello che cade si muove sia in basso sia in avanti, quindi parte dell'anticipo è verticale: sotto e davanti."}, {"q": "Un istruttore francofono dice «chandelle». Qual è la cosa più sicura da fare?", "options": ["Verificare: dritto in su o ad arco sopra il culmine?", "Tradurlo sempre come il looper inglese", "Tradurlo sempre come il teal inglese", "Ignorarlo, visto che non è un termine del regolamento"], "answer": 0, "why": "I francofoni intendono spesso un piattello quasi verticale (un teal inglese), mentre la chandelle di un tracciatore inglese sale in curva e si incurva in alto; una rapida verifica evita un piano sbagliato."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "La lepre (rabbit): rotola, salta e scatta", "body": ["La lepre (rabbit) è un piattello da 110 mm con un bordo spesso e robusto, lanciato di taglio in modo che rotoli sul terreno come una lepre che corre. È un piattello speciale, quindi nel Parcours de Chasse – Sporting™ deve essere indicato nel menu della pedana.", "Gli istruttori descrivono come corre: una lepre che rotola (rolling) corre regolare; una lepre che salta (hopping o bouncing) rimbalza su gobbe e sassi; una lepre che scatta (bolting) esce di colpo dalla copertura e corre veloce. Le lepri possono andare di traverso, verso il tiratore o in allontanamento.", "La lepre è pesante e rallenta in fretta, quindi i tiratori spesso le danno troppo anticipo. Gli istruttori chiedono di tenere la volata bassa e di sparare al bordo inferiore anteriore, così anche un salto improvviso incontra la rosata. Spesso è visibile solo in un breve varco tra i cespugli, quindi il punto di rottura va pianificato con precisione.", "Regole: ogni piattello, lepri comprese, si tira con il fucile alla spalla; sparare dal fianco non è ammesso in nessuna delle due discipline. Un caso particolare: se il primo colpo sbaglia e la lepre poi si rompe da sola, per esempio su un sasso, prima del secondo colpo, è un No bird. Nella ripetizione conta solo una rottura con il secondo colpo.", "«Fur and feather» («pelo e piuma») è il gergo dell'English Sporting per un doppio formato da una lepre («pelo») e da un piattello in volo («piuma»). In Italia sentirai «lepre» o «rabbit»; questo corso usa «lepre»."], "key_points": ["Lepre: 110 mm, bordo spesso, rotola di taglio sul terreno.", "Rotola, salta (rimbalza), scatta: descrivono come corre.", "Rallenta in fretta: non darle troppo anticipo; tieni la volata bassa.", "Si tira sempre dalla spalla; una lepre che si rompe da sola dopo un primo colpo mancato è un No bird.", "«Fur and feather» = doppio di lepre + piattello in volo."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "La lepre salta in un punto noto; tieni il fucile basso e in movimento.", "say": "Su quella gobba salta: stai sotto e continua a muoverti."}, {"en": "Shoot its feet.", "meaning": "Metti la rosata sul bordo inferiore della lepre, non sopra.", "say": "Sparale ai piedi."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "La lepre perde velocità in fretta, quindi richiede meno anticipo.", "say": "Rallenta molto: meno anticipo di quanto pensi."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "Nel doppio lepre più piattello in volo, spara prima alla lepre, perché sparisce nella copertura.", "say": "Pelo e piuma: prima la lepre, prima che arrivi ai cespugli."}], "quiz": [{"q": "Il primo colpo manca la lepre, che poi si rompe su un sasso prima del secondo colpo. Che cosa succede?", "options": ["Si conta come colpita, visto che si è rotta", "Si conta zero per il primo errore", "No bird: si ripete e conta solo una rottura con il secondo colpo", "Il tiratore passa semplicemente al piattello successivo"], "answer": 2, "why": "Entrambi i regolamenti lo considerano un No bird; nella ripetizione il tiratore deve sbagliare volutamente con il primo colpo."}, {"q": "Perché gli istruttori mettono in guardia dal dare troppo anticipo alla lepre?", "options": ["Il regolamento limita l'anticipo", "È pesante e rallenta in fretta", "Vola sempre verso l'alto", "È più piccola di un mini"], "answer": 1, "why": "La lepre ha un bordo spesso e rotola sul terreno perdendo velocità in fretta, quindi l'anticipo abituale da traversone manda la rosata davanti."}, {"q": "Che cosa significa «fur and feather»?", "options": ["Un doppio formato da una lepre e da un piattello in volo", "Un codice di abbigliamento da caccia", "Un piattello con piume incollate", "Un doppio di due lepri"], "answer": 0, "why": "Nel gergo dell'English Sporting «fur» (pelo) è la lepre e «feather» (piuma) il piattello in volo."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Singoli e doppi: allo sparo, a raffica, simultaneo", "body": ["Un singolo è un piattello da una macchina. In entrambe le discipline gli si possono sparare due colpi, quindi un errore si può recuperare con la seconda canna. Un doppio (pair o double) è formato da due piattelli tirati come un'unica unità dopo una sola chiamata.", "Doppio allo sparo (report pair, double on report): la chiamata fa partire il primo piattello e il colpo sparato su di esso fa partire il secondo. Nel Parcours de Chasse – Sporting™ il secondo parte da 0 a 3 secondi dopo quel colpo. L'ordine è fisso. «Report» qui indica il rumore dello sparo, non un rapporto scritto.", "Doppio a raffica (following pair, che la FITASC chiama rafale): due piattelli dalla stessa macchina sulla stessa traiettoria, il secondo appena la macchina si ricarica; si può sparare prima all'uno o all'altro. Esiste solo nello Sporting™: un doppio del Compak® Sporting è allo sparo o simultaneo.", "Doppio simultaneo (simultaneous pair, «simo»; nell'English Sporting «true pair»): entrambi i piattelli partono nello stesso momento, da una o da due macchine (nel Compak® Sporting sempre da due macchine diverse), e si possono tirare in qualsiasi ordine.", "Cartucce: nello Sporting™ ce ne sono due per il doppio ed entrambe possono essere sparate a un solo piattello; se un colpo li rompe tutti e due, contano entrambi. Nel Compak® Sporting è ammessa una sola cartuccia per piattello, e due colpi su un solo piattello valgono zero-zero; anche un colpo che rompe entrambi i piattelli non viene semplicemente contato due volte (lo spiega la missione sul Compak®).", "Su una pedana di Sporting™ la batteria tira prima i singoli, poi i doppi. I doppi simultanei e a raffica vengono presentati prima del tiro; i doppi allo sparo no."], "key_points": ["Singolo: un piattello, due colpi ammessi.", "Doppio allo sparo: il colpo sul primo fa partire il secondo; ordine fisso.", "A raffica (following pair): stessa macchina, stessa traiettoria, solo nello Sporting™.", "Simultaneo (true pair): entrambi insieme, in qualsiasi ordine.", "Sporting™: entrambe le cartucce possono andare a un solo piattello; Compak® Sporting: una per piattello."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "Il secondo piattello arriva solo quando il tiratore spara al primo, quindi non c'è bisogno di avere fretta con il primo.", "say": "È allo sparo: chiudi bene il primo, il secondo aspetta il tuo colpo."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "Nel doppio simultaneo spara prima alla lepre, perché la candela resta in aria più a lungo.", "say": "Simultaneo: prima la lepre, la candela ti aspetta."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Entrambi i piattelli arrivano dalla stessa macchina; dopo il primo colpo riporta occhi e fucile verso la macchina per prendere il secondo.", "say": "A raffica: dopo il primo torna subito sulla macchina per il secondo."}, {"en": "True pair from the tower, five of them.", "meaning": "Cinque doppi simultanei lanciati dalla torre (formula dell'English Sporting).", "say": "Doppi simultanei dalla torre, cinque."}], "quiz": [{"q": "In un doppio allo sparo, che cosa fa partire il secondo piattello?", "options": ["Una seconda chiamata", "Il segnale dell'arbitro", "Il colpo sparato al primo piattello", "Un timer di esattamente 5 secondi"], "answer": 2, "why": "«On report» significa al rumore dello sparo: sparare al primo piattello fa partire il secondo."}, {"q": "Nel Compak® Sporting un tiratore spara entrambe le cartucce al primo piattello di un doppio simultaneo. Risultato?", "options": ["È consentito, come nello Sporting™", "Zero-zero", "No bird e ripetizione", "Solo il secondo piattello vale zero"], "answer": 1, "why": "Il Compak® Sporting ammette una cartuccia per ogni piattello del doppio; sparare volutamente entrambe a un solo piattello vale zero-zero. Nello Sporting™ sarebbe consentito."}, {"q": "Un istruttore britannico dice «true pair». Come lo traduci?", "options": ["Un doppio corretto e regolare", "Una coppia di uccelli veri", "Un doppio a raffica", "Un doppio simultaneo"], "answer": 3, "why": "«True pair» è il nome dell'English Sporting per il doppio simultaneo; «true» non ha niente a che fare con la correttezza."}]}]}, {"id": "basics", "icon": "stance", "title": "I fondamentali del tiro", "intro": "Prima di parlare di anticipo, l'istruttore sistema le basi: piedi, imbracciata, occhi, un piano in tre punti e un fucile che non smette di muoversi. Queste cinque lezioni ti danno le parole dell'istruttore per ogni passaggio e le regole che limitano che cosa può fare il tiratore.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "La posizione: i piedi verso il punto di rottura", "body": ["La posizione (stance) è il modo in cui il tiratore sta in piedi prima del colpo. Lo spazio è ridotto: nel Parcours de Chasse – Sporting™ la pedana è un quadrato o un cerchio di 1 m e prima della chiamata entrambi i piedi devono trovarsi al suo interno. Nel Compak® Sporting ogni pedana è un quadrato di 1 m con un Firing Angle Limiter (limitatore dell'angolo di tiro), un telaio che impedisce al tiratore di fare un passo avanti e limita la rotazione del fucile.", "La base abituale: piedi più o meno alla larghezza delle spalle; per un destrimane il piede sinistro leggermente avanti (un mancino fa il contrario); ginocchia morbide, non bloccate; peso leggermente in avanti, circa il 60 per cento sul piede anteriore. Gli istruttori dicono «nose over toes», il naso sopra le punte dei piedi.", "L'istruzione chiave: punta il piede anteriore verso il punto di rottura (break point), dove il tiratore intende rompere il piattello. Così il corpo è comodo, «srotolato», proprio dove avviene il colpo. Il tiratore ruota all'indietro dai fianchi fino al punto di attesa delle canne (hold point) e si srotola nel colpo. Se i piedi sono rivolti verso la macchina, avvertono gli istruttori, il corpo esaurisce la rotazione e il fucile si ferma o la testa si alza.", "Il corpo ruota dai fianchi, non dalle braccia. I piedi possono essere posizionati in modo leggermente diverso per ogni piattello.", "Traduci «front foot» e «back foot» come piede anteriore e piede posteriore, non come sinistro e destro: il tuo tiratore potrebbe essere mancino."], "key_points": ["Sporting™: entrambi i piedi dentro la pedana di 1 m prima della chiamata.", "Compak® Sporting: pedana di 1 m con un Firing Angle Limiter.", "Piedi alla larghezza delle spalle, ginocchia morbide, peso leggermente in avanti.", "Il piede anteriore punta verso il punto di rottura; si ruota all'indietro dai fianchi fino al punto di attesa.", "Traduci piede anteriore/posteriore, non sinistro/destro."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Gira la punta del piede anteriore verso il punto in cui verrà rotto il piattello.", "say": "Punta il piede avanti verso il punto di rottura."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Prima posiziona i piedi per il punto di rottura, poi ruota il busto all'indietro fino al punto di attesa.", "say": "Piedi sul punto di rottura, poi torna indietro sul punto di attesa."}, {"en": "Weight forward, soft knees.", "meaning": "Appoggiati leggermente sul piede anteriore e non bloccare le ginocchia.", "say": "Peso avanti, ginocchia morbide."}, {"en": "Turn from the hips, not the arms.", "meaning": "Ruota tutto il busto; le braccia da sole non muovono il fucile.", "say": "Ruota dai fianchi, non dalle braccia."}], "quiz": [{"q": "Verso dove vuole di solito l'istruttore che punti il piede anteriore?", "options": ["Verso la macchina", "Verso il punto di presa visiva", "Verso l'arbitro", "Verso il punto di rottura"], "answer": 3, "why": "I piedi orientati verso il punto di rottura lasciano il corpo comodo dove avviene il colpo; i piedi rivolti verso la macchina fanno esaurire la rotazione."}, {"q": "Che cosa richiede il regolamento del Parcours de Chasse – Sporting™ per i piedi prima della chiamata?", "options": ["Entrambi i piedi dentro la pedana", "Il piede anteriore sulla linea della pedana", "Piedi uniti", "Nessun requisito"], "answer": 0, "why": "La regola sulla posizione di attesa chiede che entrambi i piedi siano dentro la pedana di 1 m prima che il tiratore chiami."}, {"q": "Un tiratore mancino. L'istruttore dice «Open your front foot». Di quale piede si tratta?", "options": ["Sempre il sinistro, qualunque sia la mano", "Il destro: il piede anteriore di un mancino", "Il piede posteriore, più vicino alla macchina", "Entrambi i piedi insieme"], "answer": 1, "why": "Per un mancino il piede anteriore è il destro. Tradurre «front foot» con «piede anteriore» evita l'errore."}]}, {"id": "basics-mount", "minutes": 6, "title": "Posizione di attesa e imbracciata", "body": ["Nel Parcours de Chasse – Sporting™ si parte con il fucile non imbracciato (gun-down). Prima della chiamata il tallone del calcio tocca il corpo e la parte superiore posteriore del calcio resta sotto una linea sul gilet, 25 cm sotto l'asse delle spalle, di colore contrastante. Il tiratore mantiene questa posizione finché il piattello non è stato lanciato ed è visibile. Imbracciare prima comporta un avvertimento verbale con cartellino giallo; una ripetizione sullo stesso campo comporta il cartellino rosso e il piattello vale zero.", "Nel Compak® Sporting la posizione del fucile alla chiamata è libera, quindi il fucile può essere già imbracciato. In entrambe le discipline ogni piattello si tira con il fucile alla spalla e nello Sporting™ la posizione del fucile tra i due piattelli di un doppio è libera.", "L'imbracciata (gun mount) porta il fucile alla guancia e alla spalla. Gli istruttori insegnano «muzzles first», prima le volate: la mano anteriore avvia il movimento delle volate lungo la linea del piattello, il calcio sale alla guancia e si assesta nell'incavo della spalla mentre il fucile aggancia la linea. «Move, mount, shoot» (muoviti, imbraccia, spara) è un unico movimento fluido. È il fucile che va al viso, non il viso al fucile; la guancia resta sul nasello, perché l'occhio è la tacca di mira.", "Un istruttore britannico può dire «gun up» o «pre-mount this one» (imbraccia prima). In una gara FITASC di Sporting™ è irregolare, nel Compak® Sporting è normale, e in allenamento è solo un esercizio. Imbracciare e seguire una traiettoria immaginaria prima di chiamare (simulazione di tiro, mock shooting) è vietato nello Sporting™: prima un avvertimento, poi uno zero."], "key_points": ["Sporting™: calcio sotto la linea del gilet (25 cm sotto l'asse delle spalle) finché il piattello non è visibile.", "Imbracciata anticipata: cartellino giallo, poi cartellino rosso e piattello perso sullo stesso campo.", "Compak® Sporting: posizione del fucile libera alla chiamata; si spara sempre dalla spalla.", "Prima le volate, fucile al viso, guancia sul nasello: muoviti, imbraccia, spara.", "«Pre-mount» è un esercizio di allenamento, mai in una gara FITASC di Sporting™."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Porta il calcio alla guancia; non abbassare la testa per andare incontro al fucile.", "say": "Il fucile al viso, non il viso al fucile."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Avvia le canne con il piattello, imbraccia durante il movimento, spara quando l'imbracciata è completa.", "say": "Prima le volate: muoviti, imbraccia, spara."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "Il fucile sale troppo tardi e con uno strappo; la mano anteriore deve guidare il movimento prima.", "say": "Imbracci tardi e troppo in fretta: parti con la mano avanti."}, {"en": "Low gun on this one, like in competition.", "meaning": "Parti con il calcio sotto la linea del gilet, come richiede il regolamento FITASC dello Sporting™.", "say": "Su questo fucile basso, come in gara."}], "quiz": [{"q": "Nel Parcours de Chasse – Sporting™, fino a quando il calcio deve restare sotto la linea del gilet?", "options": ["Finché il tiratore non ha chiamato", "Finché l'arbitro non fa un cenno", "Finché il piattello non è uscito ed è visibile", "Finché non viene sparato il primo colpo"], "answer": 2, "why": "La posizione di attesa si mantiene finché il piattello non è stato lanciato ed è visibile; solo allora si può imbracciare."}, {"q": "Nel Compak® Sporting un tiratore può chiamare il piattello con il fucile già alla spalla?", "options": ["No: prende un cartellino giallo", "Solo per le lepri e gli altri piattelli bassi", "Solo tra i due piattelli di un doppio", "Sì: la posizione del fucile alla chiamata è libera"], "answer": 3, "why": "Il Compak® Sporting non ha la regola del fucile basso: alla chiamata il fucile può essere imbracciato o no, ma ogni piattello si tira dalla spalla."}, {"q": "Perché gli istruttori insistono che la guancia resti sul nasello?", "options": ["L'occhio è la tacca di mira, quindi deve stare sempre nello stesso punto", "Per ridurre il rumore che arriva all'orecchio", "Perché lo richiedono i regolamenti di entrambe le discipline", "Per nascondere il viso all'arbitro"], "answer": 0, "why": "Un fucile da caccia non ha tacca di mira: è l'occhio sopra la bindella a fare da mira, quindi una guancia sollevata manda il colpo alto."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Gli occhi: dominanza, entrambi gli occhi aperti, messa a fuoco netta", "body": ["La maggior parte delle persone ha un occhio dominante (master eye, in italiano anche «occhio direttore») di cui il cervello si fida di più, di solito dallo stesso lato della mano dominante. L'occhio dominante deve essere quello che guarda lungo la bindella. La dominanza crociata (cross-dominance) significa che l'occhio dominante è dal lato opposto alla spalla di tiro; la visione centrale significa che nessun occhio domina chiaramente. In entrambi i casi il fucile punta dove il tiratore non se lo aspetta, spesso di lato.", "Un test semplice: con entrambi gli occhi aperti, inquadra un oggetto lontano in un piccolo triangolo fatto con le mani, poi chiudi un occhio alla volta; l'occhio che mantiene l'oggetto nel triangolo è quello dominante. L'istruttore può anche mettersi davanti al tiratore e guardare attraverso il triangolo.", "Rimedi scelti dall'istruttore: chiudere o socchiudere l'altro occhio durante l'imbracciata; un piccolo bollino sugli occhiali di protezione; imparare a sparare dall'altra spalla; oppure, più raramente, un calcio con forte vantaggio (cross-over stock). Quando possibile si preferiscono entrambi gli occhi aperti, perché due occhi valutano meglio velocità, angolo e distanza.", "La messa a fuoco: uno sguardo morbido e ampio mentre si aspetta al punto di presa visiva, poi una messa a fuoco netta sul piattello stesso, idealmente sul suo bordo anteriore. Tornare a guardare la canna o il mirino per controllare l'anticipo ferma il fucile.", "Gli occhiali di protezione sono obbligatori per i tiratori in entrambe le discipline, quindi il bollino si mette su di essi."], "key_points": ["L'occhio dominante deve guardare lungo la bindella.", "La dominanza crociata e la visione centrale fanno puntare il fucile fuori bersaglio.", "Test con il triangolo delle mani; il rimedio lo sceglie l'istruttore.", "Sguardo morbido alla presa visiva, messa a fuoco netta sul bordo anteriore; mai tornare a guardare il mirino.", "Gli occhiali di protezione sono obbligatori in entrambe le discipline."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Chiudi l'occhio sinistro durante l'imbracciata, non prima, così è l'occhio destro a guidare il fucile.", "say": "Chiudi l'occhio sinistro mentre imbracci."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Continua a guardare il piattello; controllare la canna ferma il fucile.", "say": "Occhi sul piattello, non sulla canna."}, {"en": "Look at the leading edge.", "meaning": "Metti a fuoco il bordo anteriore del piattello in movimento, non il suo centro.", "say": "Guarda il bordo anteriore."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Aspetta con lo sguardo un po' più avanti lungo la linea, dove il piattello si vede nitido per la prima volta.", "say": "Non guardare la macchina: guarda più fuori, sul punto di presa."}], "quiz": [{"q": "Un tiratore destrimane ha l'occhio dominante sinistro. Come si chiama?", "options": ["Visione centrale", "Messa a fuoco netta", "Dominanza crociata", "Bordo anteriore"], "answer": 2, "why": "La dominanza crociata è un occhio dominante dal lato opposto alla spalla di tiro."}, {"q": "Perché tornare a guardare il mirino per controllare l'anticipo è un errore?", "options": ["È vietato dal regolamento", "Ferma il fucile e il colpo va dietro", "Il mirino riflette il sole", "Fa cambiare colore al piattello"], "answer": 1, "why": "Quando la messa a fuoco passa al fucile, lo swing si ferma e il piattello finisce nella visione periferica, quindi il colpo va dietro."}, {"q": "Dove si mette di solito il bollino contro la dominanza?", "options": ["Sugli occhiali di protezione, davanti all'occhio da escludere", "Sul mirino in punta alla bindella", "Sulla bindella, a metà", "Sulla linea del gilet, sotto la spalla"], "answer": 0, "why": "Gli occhiali di protezione sono comunque obbligatori, quindi un piccolo bollino sulla lente davanti all'occhio non dominante è il rimedio più semplice."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Presa visiva, attesa e rottura: pianificare una pedana", "body": ["Prima di ogni piattello il tiratore fissa tre punti. Il punto di presa visiva (pick-up point) è dove gli occhi vedono nitidamente il piattello per la prima volta, un po' fuori dalla macchina e non alla sua bocca, dove il piattello è solo una scia confusa. Il punto di attesa delle canne (hold point) è dove le volate aspettano al momento della chiamata, di solito sulla linea del piattello o appena sotto, tra il punto di presa visiva e il punto di rottura. Il punto di rottura (break point) è dove il tiratore intende rompere il piattello.", "Ordine di pianificazione: scegli prima il punto di rottura, orienta i piedi verso di esso, torna indietro fino al punto di attesa, poi porta gli occhi sul punto di presa visiva. Nel Parcours de Chasse – Sporting™ il calcio è basso finché non compare il piattello, quindi lì il punto di attesa indica dove puntano le volate mentre il fucile è basso.", "Errori tipici: un punto di rottura troppo lontano significa uno swing veloce e incontrollato o un piattello che sta già scendendo; troppo vicino significa troppo poco movimento e un colpo «punzecchiato» (poke). Un punto di attesa troppo vicino alla macchina costringe il fucile a inseguire; troppo fuori e il piattello supera il fucile.", "I piattelli si leggono durante la presentazione. Nello Sporting™ tutte le traiettorie vengono mostrate al primo tiratore e, su richiesta, l'arbitro ripete la presentazione, fino a due piattelli per ogni piattello del menu; nel Compak® Sporting a batterie i singoli vengono mostrati una sola volta al mattino, alla prima batteria. Il piattello va rotto dove l'arbitro può vederlo, entro il limite di tiro.", "«Where are you taking it?» (dove lo prendi?) chiede il punto di rottura; «kill point» è un sinonimo neutro."], "key_points": ["Presa visiva = occhi; attesa = volate; rottura = dove si rompe il piattello.", "Si pianifica a ritroso dal punto di rottura: piedi, attesa, occhi.", "Il punto di attesa è di solito tra presa visiva e rottura, sulla linea o appena sotto.", "Leggi i piattelli durante la presentazione; rompili dove l'arbitro può vederli.", "«Where are you taking it?» = dov'è il tuo punto di rottura?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "L'istruttore chiede dove il tiratore intende rompere il piattello.", "say": "Dove lo prendi?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Tieni le volate più vicine alla macchina, a metà della distanza attuale.", "say": "Sposta il punto di attesa a metà strada verso la macchina."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Sposta lo sguardo lontano dalla macchina, dove il piattello si vede nitido per la prima volta.", "say": "Guarda più fuori: prendilo dove è nitido."}, {"en": "Hold a little lower, just under the line.", "meaning": "Alla chiamata tieni le volate leggermente sotto la traiettoria del piattello.", "say": "Aspetta un po' più basso, appena sotto la linea."}], "quiz": [{"q": "Quale punto riguarda gli occhi e non il fucile?", "options": ["Punto di attesa", "Punto di rottura", "Punto di presa visiva", "Punto di inserimento"], "answer": 2, "why": "Il punto di presa visiva è dove gli occhi vedono nitidamente il piattello per la prima volta; il punto di attesa riguarda le volate."}, {"q": "Che cosa succede di solito se il punto di attesa è troppo vicino alla macchina?", "options": ["Il piattello supera il fucile", "L'arbitro chiama No bird", "Il fucile deve inseguire il piattello", "Il piattello rallenta"], "answer": 2, "why": "Troppo vicino alla macchina, il piattello passa davanti alle volate a piena velocità e il tiratore deve inseguirlo."}, {"q": "Nel Parcours de Chasse – Sporting™ il tiratore in pedana chiede di rivedere la presentazione. Qual è il massimo per ogni piattello del menu?", "options": ["Due piattelli", "Nessuno: le ripetizioni non sono ammesse", "Quanti ne vuole", "Esattamente cinque"], "answer": 0, "why": "L'arbitro ripete la presentazione su richiesta, fino a un massimo di due piattelli per ogni piattello del menu."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Accompagnamento, velocità del fucile e tempo", "body": ["L'accompagnamento (follow-through) significa che il fucile continua a muoversi lungo la linea del piattello dopo aver premuto il grilletto, come lo swing nel golf o nel tennis. Tra la decisione di sparare e l'uscita del colpo dalle canne c'è un piccolo ritardo; se il fucile si ferma al grilletto, il colpo va dietro. Gli istruttori guardano le volate dopo lo sparo: se si bloccano o si abbassano, l'accompagnamento è mancato.", "La velocità del fucile è la velocità delle volate rispetto al piattello e definisce il metodo di anticipo: la stessa velocità del piattello è l'anticipo mantenuto (maintained lead); più veloce del piattello è lo swing-through; la stessa velocità, poi una breve accelerazione, è il pull-away. Un fucile troppo lento resta indietro; uno troppo veloce, dicono gli istruttori, va oltre, e allora spesso il tiratore lo ferma.", "Il tempo (tempo) è la velocità con cui si esegue l'intero colpo; il ritmo (rhythm) è la sua regolarità. Un piattello veloce e vicino richiede un tempo rapido, un traversone lungo e lento uno più calmo, ma il ritmo resta fluido. Molti istruttori dicono che i tiratori con un unico tempo per tutto perdono i piattelli che richiedono il contrario.", "«Stay in the gun» (resta nel fucile): guancia sul calcio e occhi sul piattello finché non si rompe. Questo tiene anche il tiratore pronto per la seconda canna, perché su un singolo si possono sparare due colpi.", "Traduci «finish the shot» come continuare il movimento, non come fermarsi."], "key_points": ["Accompagnamento: il fucile continua a muoversi dopo il grilletto; se si ferma, il colpo va dietro.", "La velocità del fucile definisce il metodo: uguale (anticipo mantenuto), più veloce (swing-through), uguale poi più veloce (pull-away).", "Tempo = velocità dell'intero colpo; ritmo = la sua regolarità.", "Resta nel fucile: pronto per la seconda canna su un singolo.", "«Finish the shot» = continua il movimento."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Non fermare lo swing al momento dello sparo.", "say": "Accompagna: il fucile continua a muoversi dopo il colpo."}, {"en": "You stopped the gun.", "meaning": "Le volate si sono fermate al grilletto, quindi il colpo è andato dietro.", "say": "Hai fermato il fucile."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "Il fucile si muove molto più veloce del piattello; muoviti alla velocità del piattello.", "say": "Vai alla velocità del piattello: lo stai rincorrendo."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "Il piattello è lento o lungo, quindi tutto il movimento può essere più calmo.", "say": "Rallenta il tempo, questo ti dà un sacco di tempo."}, {"en": "Stay in the gun until you see it break.", "meaning": "Tieni la guancia sul calcio e gli occhi sul piattello finché non si rompe.", "say": "Resta nel fucile finché non lo vedi rompersi."}], "quiz": [{"q": "L'istruttore dice «You stopped the gun». Dove è andato molto probabilmente il colpo?", "options": ["Davanti", "Sopra", "Esattamente sul piattello", "Dietro"], "answer": 3, "why": "Il piattello continua a muoversi mentre il fucile fermo no, quindi il colpo passa dietro."}, {"q": "Quale velocità del fucile descrive l'anticipo mantenuto?", "options": ["Molto più veloce del piattello", "La stessa del piattello", "Zero: il fucile aspetta", "Più lenta del piattello"], "answer": 1, "why": "Nell'anticipo mantenuto le volate si muovono alla velocità del piattello, mantenendo costante la distanza. Un fucile che aspetta è l'ambush; più veloce è lo swing-through."}, {"q": "Qual è la differenza tra tempo e ritmo?", "options": ["Il tempo è la velocità del colpo, il ritmo la sua regolarità", "Sono due parole per la stessa cosa", "Il tempo è la musica che si suona al campo", "Il ritmo è il tempo massimo tra un piattello e l'altro"], "answer": 0, "why": "Gli istruttori cambiano il tempo per ogni piattello mantenendo un ritmo fluido, quindi traduci le due parole separatamente."}]}]}, {"id": "lead", "icon": "lead", "title": "L'anticipo (lead) e i metodi di tiro", "intro": "L'anticipo è l'argomento di cui gli istruttori parlano di più: perché il fucile deve puntare davanti a un piattello in movimento, i quattro modi per arrivarci e le strane unità con cui lo descrivono. Questa missione mostra ogni metodo passo per passo e ti insegna a tradurre «four foot», «half a bird» o «double it» senza cambiarne il significato.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Perché esiste l'anticipo: anticipo reale e anticipo percepito", "body": ["I pallini impiegano una frazione di secondo per raggiungere il piattello, e in quel tempo il piattello va avanti. Un fucile puntato dritto su un traversone, quindi, spara dietro. Il fucile deve puntare davanti, in modo che rosata e piattello si incontrino. Quella distanza è l'anticipo (lead, in inglese britannico anche «forward allowance»).", "L'anticipo cresce con la velocità del piattello, con la sua distanza e con il suo angolo. Un traversone pieno ne richiede più di tutti; un piattello che vola dritto verso il tiratore o lontano da lui non richiede quasi anticipo laterale, anche se i piattelli in salita e in discesa richiedono un anticipo verticale (sopra o sotto).", "I numeri reali sorprendono. Un sito di tiro indica circa 3–4 piedi, più o meno un metro, di anticipo reale per un traversone a circa 21–25 iarde (circa 20 m). Molti tiratori dicono che cresce più o meno in proporzione alla distanza, quindi la stessa piccola distanza alla volata significa molto più anticipo reale su un piattello lontano.", "L'anticipo reale è la distanza effettiva davanti al piattello in aria. L'anticipo percepito (il «lead picture» o «sight picture», l'immagine di mira) è la distanza che il tiratore vede tra volata e piattello. Un metro a 20 m sembra pochi centimetri alla volata. Il metodo cambia l'immagine: chi tira con l'anticipo mantenuto vede la distanza più grande, chi tira in swing-through poca o nessuna, perché la velocità del fucile aggiunge anticipo.", "Un istruttore americano osserva che un tiratore destrimane spesso ha la sensazione che un traversone da sinistra a destra richieda più anticipo di uno da destra a sinistra; l'anticipo reale è lo stesso, cambia solo la percezione. Quindi i «four feet» di un istruttore descrivono la sua immagine, non una misura."], "key_points": ["L'anticipo esiste perché il piattello si muove mentre i pallini viaggiano.", "Più velocità, distanza e angolo significano più anticipo.", "L'anticipo reale (in aria) è molto più grande dell'anticipo percepito (alla volata).", "Il metodo cambia l'immagine: con l'anticipo mantenuto si vede di più, con lo swing-through di meno.", "Il numero dell'istruttore è un'immagine, non una misura."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Non ragionare in metri in aria; ricorda la distanza che hai visto alla volata quando l'hai colpito.", "say": "Lascia stare la distanza reale: conta la tua immagine."}, {"en": "That's the picture — remember it.", "meaning": "Su quel colpo l'anticipo era giusto; mantieni la stessa immagine di mira.", "say": "Ecco l'immagine giusta: ricordatela."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "L'anticipo reale è uguale nelle due direzioni; cambia solo la percezione.", "say": "Stesso anticipo su quello da destra a sinistra, sembra solo diverso."}], "quiz": [{"q": "Che cos'è l'anticipo percepito?", "options": ["La distanza reale davanti al piattello in aria", "La distanza che il tiratore vede tra volata e piattello", "L'anticipo scritto sul menu", "La distanza tra la pedana e la macchina"], "answer": 1, "why": "L'anticipo percepito è l'immagine alla volata; l'anticipo reale è la distanza effettiva in aria ed è molto più grande."}, {"q": "Quale metodo dà di solito l'anticipo percepito più grande?", "options": ["Swing-through", "Pull-away", "Anticipo mantenuto", "Sono tutti uguali"], "answer": 2, "why": "Con l'anticipo mantenuto il fucile si muove alla velocità del piattello e la velocità del fucile non aggiunge nulla, quindi il tiratore deve vedere tutta la distanza."}, {"q": "Quale piattello non richiede quasi anticipo laterale?", "options": ["Un piattello che si allontana dritto", "Un traversone lungo", "Una diagonale in allontanamento a 45°", "Un traversone a 40 m"], "answer": 0, "why": "Un piattello che si allontana dritto non ha movimento laterale; l'eventuale anticipo che richiede è verticale."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Anticipo mantenuto: mettiti davanti e resta davanti", "body": ["L'anticipo mantenuto (maintained lead; negli Stati Uniti sustained lead; in italiano anche «anticipo costante») tiene le volate davanti al piattello dall'inizio fino allo sparo.", "Come si presenta, passo per passo, su un traversone. 1) Partenza: le volate aspettano a un punto di attesa ben avanti lungo la linea, davanti al punto in cui passerà il piattello; gli occhi guardano indietro verso il punto di presa visiva. 2) Inserimento: mentre il piattello arriva, il fucile si muove e le volate entrano sulla linea davanti al piattello, mai dietro; questo è il punto di inserimento. 3) Inseguimento: le volate si muovono alla velocità del piattello, quindi la distanza resta la stessa. 4) Sparo: il grilletto si preme mentre la distanza è giusta e il fucile è ancora in movimento. 5) Il fucile continua a muoversi dopo lo sparo.", "Punti di forza: preciso, poco movimento del fucile, rapido tra un piattello e l'altro, e l'anticipo è facile da correggere. È adatto a piattelli regolari e prevedibili: traversoni lunghi, piattelli alti e costanti.", "Punti deboli: è il metodo più difficile da imparare; il tiratore deve conoscere in anticipo la velocità e la linea del piattello; e poiché il fucile non è più veloce del piattello, il tiratore vede la distanza più grande ed è tentato di misurarla, rallentare e fermarsi.", "Gli istruttori dicono «insert the gun in front» (inserisci il fucile davanti), «stay ahead of it» (stagli davanti), «match its speed» (vai alla sua velocità)."], "key_points": ["Le volate partono davanti ed entrano sulla linea davanti al piattello.", "Velocità del fucile = velocità del piattello; la distanza resta costante.", "Grilletto mentre la distanza è giusta e il fucile si muove; poi accompagna il colpo.", "Ideale su piattelli lunghi e prevedibili.", "Rischio principale: misurare la distanza e fermare il fucile."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Porta le volate davanti al piattello e tienile lì fino a dopo lo sparo.", "say": "Mettiti davanti e resta davanti."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "Le volate sono entrate sulla linea dietro il piattello; devono entrare davanti.", "say": "Il tuo punto di inserimento è dietro il piattello: metti il fucile davanti."}, {"en": "Match its speed — don't let it catch you.", "meaning": "Muovi il fucile alla velocità del piattello, così la distanza non si riduce.", "say": "Vai alla sua velocità: non farti raggiungere."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "Il tiratore rallenta per controllare la distanza; spara appena l'immagine è giusta.", "say": "Lo stai misurando: fidati dell'immagine e spara."}], "quiz": [{"q": "Nell'anticipo mantenuto, dove entrano le volate sulla linea del piattello?", "options": ["Dietro il piattello", "Sul piattello", "Davanti al piattello", "Sotto la macchina"], "answer": 2, "why": "Le volate vengono inserite davanti al piattello e restano davanti; dietro è lo swing-through, sul piattello è il pull-away."}, {"q": "Qual è l'errore tipico di chi tira con l'anticipo mantenuto?", "options": ["Partire troppo dietro", "Misurare la distanza e fermare il fucile", "Imbracciare dal fianco", "Sparare troppo presto vicino alla macchina"], "answer": 1, "why": "La distanza è grande e visibile, quindi i tiratori sono tentati di controllarla; il fucile rallenta o si ferma e il colpo va dietro."}, {"q": "Per quale piattello si consiglia spesso l'anticipo mantenuto?", "options": ["Un traversone lungo e prevedibile", "Una lepre che salta in un breve varco", "Un piattello a sorpresa da dietro", "Un piattello ZZ"], "answer": 0, "why": "Il metodo richiede velocità e linea note, che i traversoni lunghi e regolari offrono; i piattelli irregolari o a sorpresa si adattano ad altri metodi."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Swing-through: da dietro, attraverso il piattello", "body": ["Nello swing-through le volate partono dietro il piattello e lo superano. In italiano lo sentirai chiamare semplicemente «swing-through» o, a volte, «anticipo per sorpasso».", "Come si presenta, passo per passo. 1) Partenza: le volate entrano sulla linea del piattello dietro di esso, sulla sua coda. 2) Sorpasso: il fucile si muove più veloce del piattello, lungo la sua linea, attraverso il suo corpo. 3) Sparo: il grilletto si preme mentre le volate passano la parte anteriore del piattello, appena davanti. Poiché tra decisione e sparo c'è un piccolo ritardo e il fucile si muove più veloce del piattello, quando parte il colpo le volate sono già più avanti: l'anticipo reale allo sparo è maggiore di quello che vede il tiratore, che vede poca o nessuna distanza. 4) Lo swing continua dopo lo sparo. La filastrocca per ricordarlo è «butt, belly, beak, bang»: coda, corpo, punta, sparo. In inglese britannico puoi sentire «bum» invece di «butt»; traducilo con «coda».", "Punti di forza: naturale e veloce; adatto ai principianti, ai piattelli vicini e veloci, ai passanti alti e ai piattelli sopra la testa e ai piattelli irregolari o a sorpresa.", "Punti deboli: una finestra molto breve per il grilletto; sui traversoni lunghi il tiratore può restare senza tempo, perdere la linea o andare oltre; rallentare quando le volate raggiungono il piattello porta a un errore dietro.", "Le fonti non sono d'accordo sul nome «metodo CPSA»: alcune lo descrivono come swing-through, mentre oggi si dice che l'insegnamento CPSA è basato sul pull-away. Se un istruttore dice «CPSA method», chiedigli quale intende."], "key_points": ["Le volate partono dietro, sulla linea del piattello.", "Fucile più veloce del piattello: coda, corpo, punta, sparo.", "Grilletto mentre le volate passano la parte anteriore; l'anticipo reale è maggiore di quello visto.", "Adatto a piattelli vicini, veloci, passanti alti e a sorpresa; più difficile sui traversoni lunghi.", "«Metodo CPSA» è ambiguo: chiedi quale metodo si intende."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Parti dietro il piattello, attraversalo e spara quando davanti si apre uno spazio.", "say": "Vieni da dietro, attraversa il piattello e spara quando vedi luce."}, {"en": "Butt, belly, beak, bang.", "meaning": "Filastrocca: coda, corpo, punta del piattello, poi sparo.", "say": "Coda, corpo, punta, sparo."}, {"en": "You slowed down as you got to it.", "meaning": "Il fucile ha perso velocità quando ha raggiunto il piattello, quindi il colpo è andato dietro.", "say": "Hai rallentato quando ci sei arrivato."}, {"en": "Brush it out and keep going.", "meaning": "Attraversa il piattello come se lo cancellassi dal cielo, senza fermarti.", "say": "Cancellalo e continua."}], "quiz": [{"q": "Da dove partono le volate nello swing-through?", "options": ["Davanti al piattello", "Sul bordo anteriore del piattello", "Da un punto fisso al punto di rottura", "Dietro il piattello, sulla sua linea"], "answer": 3, "why": "Lo swing-through parte da dietro e supera il piattello; partire davanti è l'anticipo mantenuto, un punto fisso è l'ambush."}, {"q": "Perché chi tira in swing-through vede poco o nessun anticipo?", "options": ["I piattelli sono sempre più lenti", "È la velocità del fucile a creare l'anticipo", "Il regolamento vieta una distanza visibile", "Il tiratore chiude entrambi gli occhi"], "answer": 1, "why": "Il fucile si muove più veloce del piattello, quindi tra la decisione e lo sparo va avanti da solo."}, {"q": "Un istruttore dice «bum, belly, beak, bang». Come traduci «bum»?", "options": ["Con «coda»", "Con una parola volgare, alla lettera", "Con «bum» (un rumore)", "Lo ometti del tutto"], "answer": 0, "why": "Indica la coda del piattello; un neutro «coda» mantiene il significato e il ritmo della filastrocca."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Pull-away: sopra, con lui, stacca, spara", "body": ["Nel pull-away (in italiano a volte «anticipo in uscita»; lo stacco in avanti si può chiamare semplicemente «stacco») le volate prima si uniscono al piattello, poi si staccano davanti a lui. È molto insegnato nella scuola britannica moderna e oggi viene spesso chiamato metodo CPSA.", "Come si presenta, passo per passo. 1) «On it», sopra: il fucile viene imbracciato sul piattello o sul suo bordo anteriore; le volate lo toccano sulla sua linea. 2) «With it», con lui: le volate seguono il piattello per un attimo alla sua velocità, rispettandone linea e andatura. 3) «Pull away», stacca: il fucile accelera in modo fluido in avanti finché non compare l'immagine di anticipo giusta. 4) «Shoot», spara: il grilletto si preme mentre il fucile sta ancora accelerando o è in movimento. 5) Accompagnamento: il fucile continua dopo lo sparo.", "Punti di forza: seguire prima il piattello permette al tiratore di valutarne velocità, distanza e linea prima di impegnarsi, quindi la linea è buona. È adatto ai piattelli lunghi, alle diagonali e ai piattelli in salita. Grazie all'accelerazione, l'anticipo percepito è minore rispetto all'anticipo mantenuto.", "Punti deboli: l'accelerazione necessaria varia da piattello a piattello, quindi ci vuole pratica per sentirla; seguire troppo a lungo diventa «riding the target», cavalcare il piattello, e fermare la spinta porta a un errore dietro.", "Gli istruttori dicono «touch it and go» (toccalo e vai), «mount on it and push out» (imbraccia sul piattello e spingi fuori) o la formula in quattro tempi «on it, with it, pull away, shoot». Quando traduci mantieni il ritmo in quattro tempi: conta più delle parole esatte."], "key_points": ["Le volate partono sul piattello (o sul suo bordo anteriore).", "Seguilo alla sua velocità, poi accelera in avanti.", "Grilletto mentre il fucile si muove ancora in avanti; poi accompagna il colpo.", "Buon controllo della linea; adatto a piattelli lunghi, diagonali e in salita.", "Quando traduci, mantieni il ritmo in quattro tempi."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Unisciti al piattello, seguilo, accelera in avanti, spara.", "say": "Sopra, con lui, stacca, spara."}, {"en": "Touch it and go.", "meaning": "Incontra il piattello con le volate e comincia subito a staccarti in avanti.", "say": "Toccalo e vai."}, {"en": "You rode it too long.", "meaning": "Il tiratore ha seguito il piattello troppo a lungo prima di staccarsi e ha perso la linea o il momento.", "say": "L'hai cavalcato troppo."}, {"en": "Mount on it and push out a bit more.", "meaning": "Imbraccia sul piattello, poi staccati ancora un po' più avanti prima di sparare.", "say": "Imbraccia sul piattello e spingi fuori ancora un po'."}], "quiz": [{"q": "Nel pull-away, che cosa succede subito prima di premere il grilletto?", "options": ["Il fucile si ferma sul piattello", "Il fucile accelera davanti al piattello", "Il fucile scende sotto il piattello", "Il fucile aspetta al punto di rottura"], "answer": 1, "why": "Il pull-away vero e proprio è l'accelerazione in avanti; si spara mentre il fucile si muove ancora in avanti."}, {"q": "L'istruttore dice «You rode it too long». Che cosa è andato storto?", "options": ["È rimasto troppo in pedana prima di chiamare", "Ha imbracciato il fucile troppo presto", "Lo ha seguito troppo a lungo prima di staccarsi", "Il puller ha lanciato il piattello in ritardo"], "answer": 2, "why": "«Riding the target» significa seguirlo troppo a lungo, così il piattello rallenta, scende o scappa e la linea si perde."}, {"q": "Rispetto all'anticipo mantenuto, l'anticipo percepito nel pull-away è di solito…", "options": ["minore, perché l'accelerazione aggiunge anticipo", "maggiore, perché il fucile parte sul piattello", "sempre esattamente il doppio", "zero su ogni piattello"], "answer": 0, "why": "La breve accelerazione porta il fucile in avanti durante il ritardo dello sparo, quindi serve vedere meno distanza."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Ambush e tiro istintivo", "body": ["L'ambush, o spot shooting (in italiano si può descrivere come «tiro d'attesa» o «tiro a punto fisso»), è il contrario di uno swing. 1) Le volate si piazzano in un punto davanti al piattello, sulla sua linea, vicino al punto di rottura. 2) Aspettano con poco o nessun movimento. 3) Il grilletto si preme quando il piattello arriva in quel punto.", "Come abitudine generale, tipica dei tiratori non allenati, è poco affidabile: il fucile è fermo e il tempo deve essere perfetto. Ma un ambush deliberato a volte è la scelta giusta: un piattello che va preso molto in fretta, o una lepre visibile solo in un breve varco tra i cespugli. Una mossa simile sulle battute di taglio nel punto più alto del volo è il «collapse»: attesa molto vicina al punto di rottura e movimento minimo. Il piattello deve comunque rompersi dove l'arbitro può vederlo.", "Il tiro istintivo (instinctive shooting) significa nessun anticipo consapevole. Il tiratore tiene una messa a fuoco netta sul piattello e lascia che le mani seguano; swing e imbracciata avvengono insieme e il colpo parte quando il fucile arriva al viso. La scuola classica è quella associata all'armaiolo inglese Robert Churchill, diffusa nella caccia.", "Molti dei migliori tiratori di Parcours de Chasse – Sporting™ combinano i metodi, scegliendo piattello per piattello. «Which method for this one?» (che metodo usi su questo?) è una domanda normale per un istruttore."], "key_points": ["Ambush: volate ferme in un punto davanti; si spara quando arriva il piattello.", "Poco affidabile come abitudine, utile se deliberato (piattelli molto veloci, varchi brevi).", "«Collapse»: movimento minimo vicino al punto di rottura sulle battute di taglio.", "Istintivo: nessun anticipo consapevole, messa a fuoco netta, imbracciata e swing insieme (scuola Churchill).", "I bravi tiratori scelgono il metodo piattello per piattello."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "Il tiratore aspetta in un punto; qui l'istruttore vuole un metodo in movimento.", "say": "Lo stai aspettando fermo: tieni il fucile in movimento con il piattello."}, {"en": "Ambush this one in the gap.", "meaning": "Aspetta deliberatamente al varco e spara quando il piattello lo attraversa.", "say": "Questo aspettalo nel varco."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Tira d'istinto: concentrati sul piattello e lascia che le mani seguano.", "say": "Non pensare all'anticipo, guarda solo il piattello e lascia che il fucile ci vada."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Metti le volate quasi sul punto di rottura e fai solo un movimento minimo quando arriva la battuta.", "say": "Aspetta proprio sul punto di rottura e chiudici sopra."}], "quiz": [{"q": "Che cosa caratterizza l'ambush (spot shooting)?", "options": ["Il fucile si muove più veloce del piattello", "Il fucile aspetta in un punto davanti al piattello", "Il fucile segue il piattello, poi accelera", "Il fucile parte dietro il piattello, sulla sua linea"], "answer": 1, "why": "L'ambush significa poco o nessuno swing: le volate aspettano sulla linea e il piattello vola dentro il colpo."}, {"q": "Quando un ambush deliberato può essere una buona scelta?", "options": ["Su ogni traversone lungo e regolare", "Mai: il regolamento lo vieta", "Solo nel Compak® Sporting, mai nello Sporting™", "Su una lepre visibile solo in un breve varco"], "answer": 3, "why": "Quando il piattello è visibile solo per poco, non c'è tempo per uno swing, quindi aspettare al varco può funzionare. Nessuna regola vieta un metodo."}, {"q": "Che cos'è il tiro istintivo?", "options": ["Messa a fuoco netta sul piattello, nessun anticipo consapevole", "Sparare senza occhiali di protezione", "Sparare dal fianco, senza imbracciare", "Aspettare vicino alla macchina per ogni piattello"], "answer": 0, "why": "Il tiro istintivo si basa sulla coordinazione occhio–mano; si fa comunque con il fucile alla spalla, come richiede il regolamento."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Come gli istruttori esprimono l'anticipo e come tradurlo", "body": ["Unità di misura. Gli istruttori britannici e americani parlano in piedi e iarde: «give it four foot» (in inglese britannico «four foot» per four feet, quattro piedi), «two feet in front» (due piedi davanti). Gli istruttori europei usano i metri. Un piede è circa 30 cm, una iarda circa 0,9 m. Ma un numero di anticipo è l'immagine dell'istruttore, non una misura, quindi mantieni il suo numero e la sua unità. Non convertire mai nel mezzo di un'istruzione; se il tiratore chiede, spiega in modo approssimativo tra un piattello e l'altro. Le distanze da un piattello («it's 30 yards») si possono rendere con «circa 27 m».", "Larghezze del piattello: «half a bird», «a bird's width», «a clay's length». Bird significa piattello, mai un uccello vero: «mezzo piattello». Larghezze della canna: «a barrel's width», «two barrels» indicano la distanza vista alla volata. Attenzione: i «two barrels» di un arbitro significano due canne sparate insieme.", "Parole relative: «more», «less», «a touch more», «double it», «half that», «same lead» (di più, di meno, un filo di più, raddoppia, la metà, stesso anticipo). Mantienile relative e non inventare mai un numero. «Same lead» è fondamentale: il tiratore non deve aggiungere anticipo.", "Direzioni: «in front» (davanti) e «behind» (dietro) si riferiscono al movimento del piattello; «over» e «high», «under» e «low» sono sinonimi (sopra/alto, sotto/basso). Il quadrante dell'orologio descrive le posizioni: ore 12 è in alto, ore 3 a destra, come vede il tiratore. «You hit it at six» indica il bordo inferiore; «it comes from eleven» dà una direzione.", "Metodo: traduci numero, unità, riferimento e direzione con precisione, in breve, con il ritmo dell'istruttore. Se non è chiaro, chiedigli una sola parola: «Feet?». In gara l'assistenza tecnica (coaching) è vietata."], "key_points": ["Mantieni il numero e l'unità dell'istruttore; non convertire mai l'anticipo a metà istruzione.", "Bird = piattello: «half a bird» = «mezzo piattello».", "Le parole relative restano relative; «same lead» va tradotto.", "Quadrante: ore 12 in alto, ore 3 a destra, come vede il tiratore.", "I «two barrels» di un arbitro sono una doppia scarica, non un anticipo."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Dai l'anticipo che l'istruttore chiama «quattro piedi»; descrive la sua immagine, quindi mantieni il suo numero e la sua unità.", "say": "Dagli quattro piedi."}, {"en": "Half a bird more.", "meaning": "Aggiungi all'immagine di anticipo mezza larghezza di piattello.", "say": "Mezzo piattello in più."}, {"en": "Double it.", "meaning": "Rendi l'immagine di anticipo due volte più grande dell'ultima volta.", "say": "Raddoppialo."}, {"en": "Same lead, just keep it moving.", "meaning": "L'anticipo era giusto; l'errore è venuto dal fucile fermo.", "say": "Stesso anticipo, tieni solo il fucile in movimento."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "La rosata era sopra e a destra del piattello sul quadrante dell'orologio; spara leggermente più basso e dai un po' più di anticipo.", "say": "Eri a ore due: un filo più basso e più davanti."}, {"en": "A barrel's width in front.", "meaning": "Tieni davanti al piattello una distanza pari alla larghezza della canna, vista alla volata.", "say": "Una canna davanti."}], "quiz": [{"q": "L'istruttore dice «Give it four foot» a un tiratore che ragiona in metri. Che cosa dici?", "options": ["«Dagli 1,22 metri»", "«Dagli circa un metro»", "«Dagli quattro piedi»", "«Dagli quattro metri»"], "answer": 2, "why": "Un numero di anticipo è l'immagine dell'istruttore; convertirlo a metà istruzione aggiunge una falsa precisione o errori, e «quattro metri» cambia del tutto il significato. Se il tiratore chiede, spiega in modo approssimativo tra un piattello e l'altro."}, {"q": "Che cosa significa «half a bird»?", "options": ["Metà della larghezza di un piattello", "Un piattello rotto", "Un uccellino che vola vicino alla macchina", "Metà della serie"], "answer": 0, "why": "Nel tiro a volo «bird» significa piattello, quindi l'istruttore chiede un anticipo pari a mezza larghezza di piattello."}, {"q": "L'istruttore dice «Same lead, keep it moving». Perché «same lead» va tradotto?", "options": ["È una chiamata che usa l'arbitro", "Altrimenti il tiratore può aggiungere anticipo e sbagliare", "È un saluto cortese tra tiratori", "Cambia l'ordine dei piattelli"], "answer": 1, "why": "Dopo un errore la maggior parte dei tiratori aggiunge anticipo da sola; «same lead» dice loro che la causa era il fucile fermo, non l'anticipo."}]}]}, {"id": "faults", "icon": "search", "title": "Gli errori e come li diagnostica l'istruttore", "intro": "Quando un piattello viene mancato, l'istruttore nomina l'errore con una o due parole e poi la causa. Questa missione ti insegna le parole per gli errori e i difetti, che cosa significa davvero ciascuna e come passare al tiratore la diagnosi dell'istruttore in modo rapido ed esatto.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Dietro, davanti, sopra, sotto, scheggiato", "body": ["Ogni errore ha una direzione. Un istruttore che osserva da dietro il tiratore di solito dice prima dove è andata la rosata rispetto al piattello, e solo dopo perché. Riportalo subito: il tiratore si sta già preparando per il piattello successivo.", "Behind (dietro) significa che la rosata è passata dietro un piattello in movimento: anticipo insufficiente, oppure un fucile che ha rallentato. È l'errore più comune sui traversoni. In front (davanti) è il contrario: troppo anticipo, spesso dopo una correzione eccessiva del tiratore. Molti istruttori preferiscono un errore davanti: dimostra che il fucile ha continuato a muoversi.", "Over (anche «high», «over the top», sopra/alto) e under («low», sotto/basso) descrivono l'errore verticale. Sopra è comune sui piattelli in discesa, sulle lepri e sui piattelli in arrivo, ed è spesso legato alla testa che si stacca dal calcio. Sotto è tipico sui piattelli in salita che stanno ancora salendo al momento dello sparo.", "Chipped (scheggiato) significa che si è staccato solo un piccolo pezzo. Per l'istruttore è mezzo complimento e mezza correzione: il piattello era sul bordo della rosata. Per l'arbitro è un piattello colpito, purché il pezzo sia visibile. La trappola è la polvere: secondo il regolamento un piattello che emette solo polvere o fumo, senza un pezzo visibile, è perso. Eppure «smoked it» nel gergo degli istruttori è un colpo perfetto e centrato, e «dusted it» si sente in entrambi i sensi, quindi chiedi quando non sei sicuro.", "Mantieni l'ordine dell'istruttore: direzione, causa, correzione. Se l'istruttore dice «behind, you stopped» (dietro, ti sei fermato), conta di più la causa: un tiratore che sente solo «dietro» aggiungerà anticipo, e questo non cura un fucile che si ferma."], "key_points": ["Riporta prima la direzione: dietro, davanti, sopra, sotto.", "Dietro = troppo poco anticipo o fucile che rallenta; davanti = troppo anticipo.", "Una scheggia visibile è un piattello colpito per l'arbitro; solo polvere o fumo è perso.", "«Smoked it» è un complimento dell'istruttore, non il «fumo» del regolamento: non confonderli mai.", "Mantieni l'ordine dell'istruttore: direzione, causa, correzione."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "La rosata è passata dietro il piattello; aumenta l'anticipo.", "say": "Dietro, dagliene di più."}, {"en": "Just over the top, it was already dropping.", "meaning": "La rosata è andata sopra perché il piattello stava cadendo; spara più basso e davanti.", "say": "Appena sopra, stava già scendendo."}, {"en": "In front this time, good, now a touch less.", "meaning": "Troppo anticipo, ma il fucile si muoveva; riduci leggermente l'anticipo.", "say": "Stavolta davanti, bene, ora un filo di meno."}, {"en": "You just chipped it, a little more in front.", "meaning": "Colpito sul bordo della rosata; un po' più di anticipo lo centra.", "say": "L'hai solo scheggiato, un po' più davanti."}, {"en": "Smoked it! Same again.", "meaning": "Un colpo perfetto e centrato (gergo, non il «fumo» del regolamento); ripeti esattamente.", "say": "Polverizzato! Uguale anche il prossimo."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "La causa è il fucile fermo; aggiungere solo anticipo non serve.", "say": "Dietro, ma ti sei fermato, quindi non aggiungere solo anticipo."}], "quiz": [{"q": "L'istruttore grida «Behind, you stopped!». Qual è la parte più importante da tradurre?", "options": ["La causa: il fucile si è fermato", "Solo la direzione «dietro»", "Niente: il tiratore ha visto l'errore", "Una richiesta di aggiungere molto più anticipo"], "answer": 0, "why": "Aggiungere anticipo non cura un fucile che si ferma; la causa è ciò che il tiratore deve correggere."}, {"q": "Dal piattello si stacca un pezzo piccolo ma ben visibile. L'istruttore dice «just chipped it». Come lo valuta l'arbitro?", "options": ["Perso, perché la maggior parte del piattello ha continuato a volare", "No bird", "Colpito (uno)", "Colpito solo se l'istruttore è d'accordo"], "answer": 2, "why": "Almeno un pezzo visibile rende il piattello colpito sia nello Sporting™ sia nel Compak® Sporting; decide solo l'arbitro."}, {"q": "Dopo un colpo l'istruttore grida «Smoked it!». Che cosa intende?", "options": ["Si è alzata solo polvere, quindi è perso", "Un colpo perfetto e centrato", "Era un piattello flash", "Il tiratore deve cambiare cartucce"], "answer": 1, "why": "Nel gergo degli istruttori «smoked it» è un complimento per un piattello ridotto in polvere; nel regolamento polvere o fumo senza un pezzo visibile è un errore."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Testa alzata, fucile fermo, piattello cavalcato, colpo punzecchiato", "body": ["Dopo la direzione, l'istruttore nomina la causa. Quattro cause tornano in ogni giornata di allenamento, ognuna con la sua parola breve. Imparale a coppie: il difetto e il rimedio.", "Testa alzata (head lift): la guancia si stacca dal calcio al momento dello sparo o subito prima, spesso perché il tiratore vuole vedere il piattello rompersi. L'occhio è la tacca di mira, quindi sollevarlo sposta l'immagine e il colpo di solito va sopra. Rimedio: «head down» (testa giù), «cheek on the stock» (guancia sul calcio), «stay in the gun» (resta nel fucile).", "Fucile fermo (stopping the gun): le volate si fermano allo sparo, di solito perché il tiratore controlla l'anticipo sulla canna. Il colpo va dietro. Una versione più leggera è il «checking»: lo swing esita per una frazione di secondo. Rimedio: «keep the gun moving» (tieni il fucile in movimento), «follow through» (accompagna), «finish the shot» (chiudi il colpo continuando il movimento).", "Cavalcare il piattello (riding the target): seguire il piattello troppo a lungo prima di sparare, così rallenta, scende o devia e il tiratore perde la linea. Rimedio: «take it earlier» (prendilo prima), «commit to it» (deciditi). Punzecchiare (poking, anche «aiming», «measuring»: mirare, misurare): puntare il fucile lentamente come una carabina, con gli occhi sul mirino invece che sul piattello. È tipico quando il punto di rottura è troppo vicino, o su una candela nel punto più alto. Rimedio: «eyes on the clay» (occhi sul piattello), «let the gun go» (lascia andare il fucile).", "Spesso gli istruttori nominano la causa prima ancora che il tiratore abbia abbassato il fucile. Traducila nello stesso respiro e con lo stesso verbo: «you stopped» (ti sei fermato) non è «you missed» (hai sbagliato). Una parola come «aiming» è quasi sempre una critica, quindi non trasformarla mai in un consiglio come «mira meglio»."], "key_points": ["Testa alzata: colpo di solito sopra; rimedio: testa giù, resta nel fucile.", "Fucile fermo o esitazione: colpo dietro; rimedio: tieni il fucile in movimento, accompagna.", "Piattello cavalcato: il piattello rallenta o scende; rimedio: prendilo prima, deciditi.", "Colpo punzecchiato o mirato: puntamento lento come con una carabina; rimedio: occhi sul piattello.", "Traduci subito la causa, con il verbo stesso dell'istruttore."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "La guancia si è staccata dal calcio, quindi il colpo è andato sopra il piattello.", "say": "Hai alzato la testa, per questo è andato sopra."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "Lo swing si è fermato allo sparo; continua il movimento attraverso il piattello e dopo.", "say": "Tieni il fucile in movimento, ti sei fermato sul piattello."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Una breve esitazione prima di sparare; deciditi e spara senza rallentare.", "say": "Hai esitato proprio prima del colpo, deciditi."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Critica: il tiratore punta come con una carabina; concentrati sul piattello e muovi il fucile liberamente.", "say": "Smetti di mirare, guarda il piattello e lascia andare il fucile."}, {"en": "You rode it too long, take it earlier.", "meaning": "Il tiratore ha seguito il piattello troppo a lungo; rompilo prima.", "say": "L'hai cavalcato troppo, prendilo prima."}, {"en": "Stay in the gun.", "meaning": "Tieni la guancia sul calcio fino a dopo lo sparo.", "say": "Resta nel fucile."}], "quiz": [{"q": "L'istruttore dice «You lifted your head». Dove è andato molto probabilmente il colpo?", "options": ["Dietro", "Sopra", "Sotto", "Davanti"], "answer": 1, "why": "L'occhio è la tacca di mira: quando la testa si alza, il colpo di solito va sopra."}, {"q": "Un istruttore grida «Stop aiming!». Che cosa vuole?", "options": ["Non puntare come con una carabina: guarda il piattello e muovi il fucile", "Mira con più precisione", "Cessate il fuoco immediatamente", "Abbassa il fucile"], "answer": 0, "why": "In bocca a un istruttore «aiming» è un difetto (colpo punzecchiato); il rimedio è occhi sul piattello e uno swing libero."}, {"q": "«You rode it too long» significa…", "options": ["Il tiratore ha sparato troppo presto", "La macchina era troppo lenta", "Il tiratore è partito troppo dietro", "Il tiratore ha seguito il piattello troppo a lungo prima di sparare"], "answer": 3, "why": "Cavalcare il piattello significa seguirlo troppo a lungo, così rallenta o scende e la linea si perde."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Errori di imbracciata: in ritardo, viso al fucile, fucile inclinato", "body": ["Molti errori cominciano prima dello swing, nell'imbracciata: il movimento che porta il fucile alla guancia e alla spalla. Le parole dell'istruttore per descriverla sono brevi e fisiche.", "Imbracciata in ritardo (late mount): il fucile arriva alla spalla dopo il momento in cui il colpo avrebbe dovuto partire, quindi il tiratore si affretta o spara prima che la guancia sia giù. Il difetto opposto è un'imbracciata completata troppo presto, dopo la quale il fucile aspetta, fermo e pesante. Rimedio: «move, mount, shoot» (muoviti, imbraccia, spara), in cui le volate partono con il piattello e l'imbracciata si completa quando parte il colpo.", "Viso al fucile (face to the gun): invece di portare il calcio al viso, il tiratore abbassa la testa per andargli incontro. L'occhio finisce ogni volta in un punto diverso e il rinculo colpisce la guancia. Gli istruttori dicono: «porta il fucile al viso, non il viso al fucile». Anche un calcio che finisce sul braccio invece che nell'incavo della spalla fa male.", "Fucile inclinato (canting): il fucile è inclinato di lato al momento dello sparo e il colpo devia dalla linea. Spesso va insieme a una spalla abbassata. Rimedio: «keep the gun level» (tieni il fucile dritto), «turn from the hips» (ruota dai fianchi).", "Nelle gare FITASC di Parcours de Chasse – Sporting™ il fucile non può essere imbracciato prima che compaia il piattello, quindi «pre-mount this one» (imbraccia prima su questo) è solo un esercizio di allenamento. Imbracciare in anticipo in una gara di Sporting™ comporta un avvertimento e un cartellino giallo. Nel Compak® Sporting il fucile può essere già alla spalla al momento della chiamata. Traduci l'esercizio come esercizio e non aggiungere nulla di tuo."], "key_points": ["Imbracciata in ritardo: un colpo affrettato; rimedio: muoviti, imbraccia, spara.", "Viso al fucile: l'occhio si sposta e il rinculo fa male; porta il fucile al viso.", "Fucile inclinato: il colpo devia dalla linea; tieni il fucile dritto, ruota dai fianchi.", "Imbracciare prima è un esercizio: in una gara di Sporting™ non è ammesso prima che compaia il piattello, nel Compak® Sporting è ammesso alla chiamata."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Porta il calcio alla guancia; non abbassare la testa sul calcio.", "say": "Porta il fucile al viso, non il viso al fucile."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Comincia a muoverti con il piattello, completa l'imbracciata mentre spari, in un'unica azione fluida.", "say": "Muoviti, imbraccia, spara, tutto insieme."}, {"en": "You canted the gun, keep it level.", "meaning": "Il fucile era inclinato di lato al momento dello sparo.", "say": "Hai inclinato il fucile, tienilo dritto."}, {"en": "Mount on the line.", "meaning": "Il fucile deve salire già sulla traiettoria del piattello.", "say": "Imbraccia sulla linea."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Esercizio di allenamento con il fucile già alla spalla; non ammesso in una gara di Sporting™.", "say": "Su questo imbraccia prima, solo per allenamento."}], "quiz": [{"q": "In allenamento un istruttore dice a un tiratore che si prepara per una gara FITASC di Sporting™: «Pre-mount this one». Che cosa è vero?", "options": ["È ammesso in tutte le gare FITASC", "L'interprete dovrebbe rifiutarsi di tradurlo", "È un esercizio di allenamento; in una gara di Sporting™ il fucile non può essere imbracciato prima che compaia il piattello", "Significa imbracciare dopo lo sparo"], "answer": 2, "why": "Lo Sporting™ richiede la posizione di attesa con il fucile non imbracciato finché non compare il piattello; un'imbracciata anticipata in gara comporta un avvertimento con cartellino giallo."}, {"q": "«You canted the gun» significa…", "options": ["Il fucile era inclinato di lato al momento dello sparo", "Il fucile è stato imbracciato troppo tardi", "Il fucile si è fermato", "La sicura era inserita"], "answer": 0, "why": "Il canting è un'inclinazione laterale del fucile, che porta il colpo fuori dalla linea."}, {"q": "Quale istruzione corregge il «viso al fucile»?", "options": ["Spingi la testa ancora più giù", "Porta il fucile al viso", "Chiudi un occhio", "Tieni il fucile più in basso sul braccio"], "answer": 1, "why": "Il calcio deve salire fino al viso, così l'occhio è ogni volta nello stesso punto."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "I doppi: il secondo piattello", "body": ["Su un doppio molti tiratori rompono il primo piattello e sbagliano il secondo. L'istruttore allora parla di transition, il passaggio dal primo al secondo piattello, e di recovery, il recupero del controllo di fucile e testa dopo il primo colpo.", "La regola d'oro è «eyes first, then the gun»: prima gli occhi, poi il fucile. Gli occhi lasciano il primo piattello rotto e trovano il secondo; il fucile segue. Un tiratore che guarda il primo piattello rompersi, o che sposta il fucile prima di aver trovato il secondo, perde tempo. Gli istruttori dicono «eyes to the second» (occhi sul secondo) o indicano semplicemente con la mano.", "Recupero: il rinculo solleva le volate e a volte la testa. «Let the gun recover, then go» significa: guancia di nuovo giù e fucile di nuovo sulla linea prima di andare sul secondo piattello. Una buona posizione con il peso in avanti rende il recupero più rapido.", "Pianificazione: mentre legge il doppio, l'istruttore decide quale piattello prendere per primo e dove romperlo perché il secondo sia facile da trovare. Frasi tipiche: «take the dropping one first» (prima quello che scende), «break the first early» (rompi presto il primo), «stick to the plan» (rispetta il piano). Un tiratore che cambia l'ordine in pedana «went for the wrong one», è andato sul piattello sbagliato.", "Qui contano le regole. Nel Parcours de Chasse – Sporting™ la posizione del fucile è libera tra i due piattelli di qualsiasi doppio e il tiratore ha due cartucce per il doppio, che possono essere sparate entrambe allo stesso piattello. Nel Compak® Sporting in un doppio è ammessa una sola cartuccia per piattello. Non spiegare tu le penalizzazioni: traduci l'istruttore e lascia le domande sul regolamento all'arbitro."], "key_points": ["Prima gli occhi, poi il fucile.", "Recupero: guancia di nuovo sul calcio e fucile sulla linea prima del secondo piattello.", "Mentre legge il doppio, l'istruttore pianifica l'ordine e i punti di rottura.", "Sporting™: posizione del fucile libera tra i piattelli, ed entrambe le cartucce possono andare a un solo piattello; Compak® Sporting: una cartuccia per piattello."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Trova il secondo piattello con gli occhi prima di muovere il fucile.", "say": "Prima gli occhi sul secondo, poi il fucile."}, {"en": "Let the gun recover, then go to the second.", "meaning": "Dopo il rinculo, sistema fucile e guancia prima del secondo colpo.", "say": "Lascia che il fucile si riassesti, poi vai sul secondo."}, {"en": "Take the dropping one first.", "meaning": "Spara prima al piattello che sparirà o cadrà per primo.", "say": "Prima quello che scende."}, {"en": "Don't watch the first one break.", "meaning": "Sposta subito gli occhi sul secondo piattello.", "say": "Non guardare il primo che si rompe."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "Il tiratore ha cambiato l'ordine pianificato; un'osservazione tecnica, non una violazione delle regole.", "say": "Sei andato prima su quello sbagliato, rispetta il piano."}], "quiz": [{"q": "Che cosa significa «eyes first, then the gun» su un doppio?", "options": ["Chiudere gli occhi dopo il primo colpo", "Guardare la canna prima del secondo colpo", "Imbracciare il fucile prima di chiamare il doppio", "Trovare il secondo piattello con gli occhi prima di portarci il fucile"], "answer": 3, "why": "In una buona transizione gli occhi guidano e il fucile segue."}, {"q": "In un doppio di Compak® Sporting il tiratore sbaglia il primo piattello e vuole sparargli anche la seconda cartuccia. È consentito?", "options": ["Sì, come nello Sporting™", "Sì, ma solo in un doppio simultaneo", "No: in un doppio di Compak® Sporting è ammessa una sola cartuccia per piattello", "Solo con il permesso dell'arbitro"], "answer": 2, "why": "Il Compak® Sporting vieta di sparare due volte al primo piattello di un doppio; lo Sporting™ ammette entrambe le cartucce su un solo piattello."}, {"q": "In un doppio di Sporting™, il tiratore può abbassare il fucile tra il primo e il secondo piattello?", "options": ["Sì, la posizione del fucile è libera tra i due piattelli", "No, il fucile deve restare imbracciato", "Solo in un doppio allo sparo", "Solo se l'arbitro lo permette"], "answer": 0, "why": "La posizione libera vale tra i piattelli di qualsiasi doppio, ma non prima del primo."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Capire l'istruttore: comandi brevi e segnali", "body": ["In pedana l'istruttore parla a frammenti: «Behind.» «Head.» «More.» «Again.» (Dietro. Testa. Di più. Ancora.) Tra un piattello e l'altro ci sono solo pochi secondi, quindi la brevità è voluta. La tua traduzione deve essere altrettanto breve; una frase lunga arriva dopo la chiamata successiva.", "Molti istruttori chiedono prima di spiegare: «Where did it go?» (dov'è andato?) o «What did you see?» (che cosa hai visto?). È una domanda didattica, non un esame per l'interprete. Traduci la domanda, lascia rispondere il tiratore e ritraduci la risposta esattamente, anche se sembra sbagliata. L'istruttore ha bisogno di sapere che cosa ha percepito il tiratore.", "I segnali con le mani dicono molto. I più comuni: mani che si allontanano o si avvicinano per più o meno anticipo, una mano piatta che scende per «più basso», un colpetto sulla guancia per «testa giù», un dito che traccia la linea del piattello, un pollice in su per «uguale anche il prossimo». I segnali cambiano da istruttore a istruttore, quindi concordali prima della sessione, e non tradurre un gesto che il tiratore ha già visto.", "Alcune parole sono puro ritmo e incoraggiamento: «commit», «trust it», «smooth», «good, same again» (deciditi, fidati, fluido, bene, uguale anche il prossimo). Mantieni il tono. «Bad luck» (sfortuna) dopo un errore è gentilezza, non un commento sull'arbitro.", "In gara l'assistenza tecnica (coaching) è vietata: l'arbitro dà al concorrente un cartellino giallo e allontana l'istruttore dall'area di tiro. Il regolamento non dice se un interprete possa riferire i consigli di un istruttore durante una gara: è una questione aperta per la FITASC. La pratica sicura: in gara traduci solo per l'arbitro, la giuria e l'organizzatore."], "key_points": ["Gli istruttori parlano a frammenti; traduci altrettanto brevemente.", "«Where did it go?» è una domanda didattica: traduci esattamente la risposta del tiratore.", "Concorda i segnali con le mani prima della sessione.", "Niente coaching in gara; traduci solo per l'arbitro, la giuria e l'organizzatore."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "L'istruttore chiede dove il tiratore pensa sia andato il colpo; una domanda didattica.", "say": "Dov'è andato?"}, {"en": "What did you see?", "meaning": "Descrivi l'immagine al momento dello sparo.", "say": "Che cosa hai visto?"}, {"en": "More.", "meaning": "Nel contesto quasi sempre «più anticipo».", "say": "Di più."}, {"en": "Good, same again.", "meaning": "Ripeti esattamente quello che hai appena fatto.", "say": "Bene, uguale anche il prossimo."}, {"en": "Trust it, commit to it.", "meaning": "Smetti di esitare; deciditi e spara.", "say": "Fidati, deciditi."}, {"en": "Bad luck.", "meaning": "Comprensione dopo un errore; non una lamentela sull'arbitro.", "say": "Sfortuna."}], "quiz": [{"q": "L'istruttore chiede al tiratore «Where did it go?». Che cosa deve fare l'interprete?", "options": ["Rispondere al posto del tiratore", "Tradurre la domanda, poi esattamente la risposta del tiratore", "Spiegare l'errore con parole proprie", "Non dire nulla: è una domanda retorica"], "answer": 1, "why": "L'istruttore vuole la percezione del tiratore, quindi la risposta deve arrivargli invariata."}, {"q": "Durante una gara l'istruttore del tiratore ti chiede di riferire: «Give the next one more lead». Qual è la pratica sicura?", "options": ["Riferirlo a bassa voce", "Riferirlo solo tra una pedana e l'altra", "Non riferire consigli tecnici in gara; tradurre solo per l'arbitro, la giuria e l'organizzatore", "Chiedere prima agli altri tiratori"], "answer": 2, "why": "Il coaching in gara è vietato e il regolamento non dice se un interprete possa riferirlo; restarne fuori protegge il tiratore."}, {"q": "Che cosa succede secondo il regolamento se l'arbitro ritiene che un concorrente stia ricevendo assistenza tecnica?", "options": ["Cartellino giallo per il concorrente; l'istruttore viene allontanato dall'area di tiro", "Niente: il coaching è ammesso", "Il piattello si ripete", "Tutta la batteria viene squalificata"], "answer": 0, "why": "Entrambi i regolamenti danno al concorrente un cartellino giallo, con penalizzazioni più pesanti in caso di recidiva, e allontanano l'istruttore."}]}]}, {"id": "sporting", "icon": "flag", "title": "Il regolamento del Parcours de Chasse – Sporting™", "intro": "Il Parcours de Chasse – Sporting™ è la disciplina FITASC che imita la caccia su terreno naturale. Questa missione ti guida nelle sue regole così come le applica un arbitro: serie e pedane, la partenza con il fucile non imbracciato, singoli e doppi, la presentazione dei piattelli, i malfunzionamenti e i limiti di tempo. Tutto è una parafrasi; i riferimenti alle regole aprono la guida al regolamento di ClayArena.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Serie, pedane e ordine di tiro", "body": ["Una gara di Parcours de Chasse – Sporting™ si conta in serie da 25 piattelli. Una gara internazionale è di 200 piattelli, quindi otto serie; ogni serie si tira su un layout (un insieme di pedane, in italiano «campo») o su una linea.", "Ogni layout dà 15 singoli e 5 doppi. Il numero di pedane e di macchine dipende dal sistema: il vecchio sistema usa 5 macchine per 3 pedane, mentre le linee del nuovo sistema hanno 4 o 5 pedane con 3 o 4 macchine ciascuna. Le macchine sono contrassegnate A, B, C, D da sinistra a destra come si vedono dalla pedana. Il menu davanti alla pedana le elenca nell'ordine di tiro, insieme agli eventuali piattelli speciali: 90, 70 o 60 mm, battuta, lepre.", "La pedana stessa è un quadrato di 1 m o un cerchio di 1 m di diametro. Ogni traiettoria ha una classe di difficoltà: A (un tiratore medio ne rompe più dell'80%), B (dal 60 all'80%) o C (dal 40 al 60%).", "I tiratori girano in batterie di massimo sei, formate per sorteggio. A ogni pedana tutti tirano prima i singoli e poi i doppi, e l'ordine di tiro ruota a ogni pedana e di nuovo per i doppi. Gli altri aspettano lì vicino, senza disturbare chi sta tirando.", "L'arbitro, o una persona sotto la sua supervisione, tiene lo statino e segna ogni piattello sotto la lettera della sua macchina. Lasciando ogni pedana, ogni tiratore controlla il punteggio; un disaccordo va segnalato subito all'arbitro, e la decisione dell'arbitro è definitiva."], "key_points": ["Serie = 25 piattelli su un layout: 15 singoli + 5 doppi; gara internazionale = 200 piattelli.", "Macchine A, B, C, D da sinistra a destra come si vedono dalla pedana; il menu indica l'ordine e i piattelli speciali.", "Batterie di massimo sei; prima i singoli, poi i doppi; l'ordine ruota.", "Controlla il punteggio quando lasci ogni pedana; decide l'arbitro."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "L'ordine standard a ogni pedana.", "say": "Prima i singoli, poi i doppi."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "Il cartello del menu elenca le macchine nell'ordine in cui verranno tirate.", "say": "Leggi il menu: le macchine vanno A, B, C."}, {"en": "Next shooter.", "meaning": "L'arbitro chiama in pedana la persona successiva.", "say": "Il prossimo tiratore."}, {"en": "Check your score before you leave the stand.", "meaning": "Qualsiasi disaccordo va segnalato adesso, non dopo.", "say": "Controlla il punteggio prima di lasciare la pedana."}], "quiz": [{"q": "Quanti piattelli dà un layout di Sporting™ e come sono suddivisi?", "options": ["20: 10 singoli e 5 doppi", "25: tutti singoli", "25: 15 singoli e 5 doppi", "50: 25 singoli e 25 doppi"], "answer": 2, "why": "Ogni tipo di layout dà 15 singoli più 5 doppi, cioè 25 piattelli."}, {"q": "In che ordine tira una batteria su una pedana?", "options": ["Prima i doppi, poi i singoli", "Tutti tirano prima i singoli, poi i doppi, e l'ordine ruota", "Ogni tiratore tira tutto il layout in una volta", "I tiratori scelgono liberamente"], "answer": 1, "why": "Prima i singoli, poi i doppi, a rotazione, salvo diversa decisione della giuria."}, {"q": "Lasciando la pedana, un tiratore vede che un piattello colpito è stato segnato come errore. Che cosa deve fare?", "options": ["Aspettare la fine della serie e ricorrere alla giuria", "Correggere lo statino da solo", "Chiedere alla batteria di votare", "Dirlo subito all'arbitro; decide l'arbitro"], "answer": 3, "why": "I punteggi si controllano lasciando ogni pedana; decide solo l'arbitro, e dopo non c'è appello."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "La partenza con il fucile non imbracciato", "body": ["La regola più visibile del Parcours de Chasse – Sporting™ è la partenza con il fucile non imbracciato (gun-down, in gergo «fucile sbracciato»). Prima della chiamata il tiratore sta con entrambi i piedi dentro la pedana, il tallone del calcio a contatto con il corpo e il punto superiore posteriore del calcio sotto una linea sul gilet. Questa posizione di attesa si mantiene finché il piattello non è stato lanciato ed è visibile.", "La linea è segnata sul gilet o sulla giacca 25 cm sotto l'asse delle spalle, parallela a esso, in un colore che contrasta con il gilet in modo che l'arbitro possa vederla. La regola vale per ogni tipo di calcio, compresi quelli con nasello regolabile.", "Il fucile può salire solo quando compare il piattello. Ogni piattello, lepri comprese, si tira con il fucile alla spalla; sparare dal fianco non è ammesso. Tra il primo e il secondo piattello di qualsiasi doppio la posizione del fucile è libera, ma prima del primo piattello vale la posizione di attesa.", "Penalizzazioni: la prima volta che un tiratore chiama in posizione scorretta o imbraccia prima che compaia il piattello, l'arbitro dà un avvertimento verbale con cartellino giallo. Ogni ulteriore infrazione sullo stesso layout comporta il cartellino rosso, e il piattello viene contato zero su un singolo, zero e No bird su un doppio allo sparo, zero e zero su un doppio simultaneo o a raffica.", "Anche imbracciare e seguire la linea immaginaria prima di chiamare (simulazione di tiro, mock shooting) è vietato: prima un avvertimento, poi uno zero. Se un istruttore fa esercitare una partenza con il fucile imbracciato prima di una gara FITASC, traduci anche la parola «esercizio»."], "key_points": ["Prima della chiamata: entrambi i piedi nella pedana, calcio a contatto con il corpo, parte superiore del calcio sotto la linea del gilet.", "La linea del gilet è 25 cm sotto l'asse delle spalle, in un colore contrastante.", "Imbraccia solo quando compare il piattello; spara sempre dalla spalla; posizione libera tra i piattelli di un doppio.", "Prima infrazione: avvertimento + cartellino giallo; la successiva sullo stesso layout: cartellino rosso e piattello conteggiato."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Arbitro: porta il calcio sotto la linea del gilet prima di chiamare.", "say": "Fucile giù, per favore."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Prima infrazione sulla posizione del fucile: avvertimento verbale con cartellino giallo.", "say": "Il calcio era sopra la linea. Questo è un avvertimento."}, {"en": "Don't mount before the target appears.", "meaning": "Il fucile può salire solo quando il piattello è visibile.", "say": "Non imbracciare prima che compaia il piattello."}, {"en": "Red card, zero.", "meaning": "Una recidiva sullo stesso layout; il singolo è perso.", "say": "Cartellino rosso, zero."}], "quiz": [{"q": "Prima pedana. Un tiratore chiama con il fucile già alla spalla. È la sua prima infrazione su questo layout. Qual è la decisione dell'arbitro?", "options": ["Il piattello vale zero", "Un avvertimento verbale con cartellino giallo", "No bird e nient'altro", "Espulsione"], "answer": 1, "why": "La prima infrazione sulla posizione del fucile è un avvertimento verbale accompagnato da un cartellino giallo."}, {"q": "Stesso layout, due pedane dopo: lo stesso tiratore chiama un singolo con il calcio sopra la linea del gilet. Decisione?", "options": ["Un altro cartellino giallo", "No bird", "Cartellino rosso e il piattello si ripete", "Cartellino rosso e il singolo vale zero"], "answer": 3, "why": "Dopo l'avvertimento, un'ulteriore infrazione sullo stesso layout è un cartellino rosso: zero su un singolo."}, {"q": "Doppio allo sparo. Dopo aver rotto il primo piattello, il tiratore abbassa leggermente il fucile prima del secondo. Decisione?", "options": ["Consentito: la posizione del fucile è libera tra i due piattelli", "Cartellino giallo", "Zero sul secondo piattello", "No bird"], "answer": 0, "why": "La posizione libera vale tra i piattelli di qualsiasi doppio; la posizione di attesa è richiesta solo prima del primo."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Singoli e doppi", "body": ["Un singolo è un piattello da una macchina. Nel Parcours de Chasse – Sporting™ il tiratore può sparargli due cartucce, quindi un errore con la prima canna si può ancora recuperare con la seconda. Ogni singolo deve lasciare il tempo per due colpi.", "Un doppio è formato da due piattelli e il tiratore ha solo due cartucce a disposizione; possono andare entrambe allo stesso piattello. Ci sono tre tipi. Allo sparo: il secondo piattello parte da 0 a 3 secondi dopo il colpo sparato al primo, fatto partire da quel colpo. Simultaneo: entrambi partono nello stesso momento, da una o da due macchine. A raffica (rafale): due piattelli dalla stessa macchina sulla stessa traiettoria, il secondo appena la macchina si ricarica. Nei doppi simultanei e a raffica i piattelli si possono prendere in qualsiasi ordine. I doppi usano solo piattelli già presentati come singoli dalla stessa pedana.", "Decisioni che l'arbitro deve prendere spesso: se un colpo rompe entrambi i piattelli di qualsiasi doppio, contano entrambi, uno e uno. Se il tiratore non spara a un doppio a raffica o simultaneo senza un motivo valido, è zero e zero.", "In un doppio allo sparo, un primo piattello irregolare significa che il doppio si ripete; se il primo piattello o i suoi pezzi rompono il secondo prima del secondo colpo, o il secondo è irregolare, il doppio si ripete e il primo risultato resta valido. Nei doppi simultanei e a raffica, un piattello irregolare significa ripetizione senza registrare alcun punteggio.", "Consiglio: riporta il risultato di un doppio come coppia, nell'ordine dell'arbitro."], "key_points": ["Singolo: due cartucce ammesse.", "Doppio: due cartucce in tutto, possono andare entrambe a un solo piattello; tipi: allo sparo, simultaneo, a raffica.", "Un colpo rompe entrambi i piattelli: uno e uno.", "Non sparare a un doppio simultaneo o a raffica senza motivo: zero e zero."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Istruttore: il secondo piattello parte con il colpo sparato al primo.", "say": "Doppio allo sparo: il secondo parte con il tuo colpo."}, {"en": "On the rafale, take either one first.", "meaning": "Nel doppio a raffica l'ordine è libero.", "say": "Sulla raffica prendi prima quello che vuoi."}, {"en": "One and one.", "meaning": "Arbitro: entrambi i piattelli del doppio sono colpiti.", "say": "Buono e buono."}, {"en": "No Bird, repeat the double.", "meaning": "Piattello irregolare; il doppio viene lanciato di nuovo.", "say": "No bird, si ripete il doppio."}], "quiz": [{"q": "Doppio simultaneo. Un colpo rompe entrambi i piattelli. Qual è la decisione dell'arbitro?", "options": ["Uno e uno", "Uno e No bird", "No bird, il doppio si ripete", "Uno e zero"], "answer": 0, "why": "Nello Sporting™ due piattelli rotti con un solo colpo in qualsiasi doppio valgono uno e uno (nel Compak® Sporting è diverso)."}, {"q": "Doppio allo sparo. Il tiratore rompe il primo piattello e un suo pezzo distrugge il secondo prima del secondo colpo. Decisione?", "options": ["Uno e uno", "Il doppio si ripete e il primo risultato resta valido", "Zero sul secondo piattello", "Uno e zero"], "answer": 1, "why": "Quando il primo piattello o i suoi pezzi rompono il secondo prima del secondo colpo, il doppio si ripete e il primo risultato resta valido."}, {"q": "Doppio a raffica. Entrambi i piattelli volano regolarmente, ma il tiratore abbassa il fucile e non spara a nessuno dei due, senza dare un motivo valido. Decisione?", "options": ["No bird", "Zero e No bird", "Solo un cartellino giallo", "Zero e zero"], "answer": 3, "why": "Un piattello regolare a cui non si spara senza motivo valido è perso; in un doppio a raffica o simultaneo questo significa zero e zero."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "La presentazione dei piattelli", "body": ["Prima che una batteria tiri su una pedana, l'arbitro fa presentare i piattelli. La presentazione serve a leggere i piattelli: linea, velocità, distanza e che cosa fa il piattello. Tutte le traiettorie vengono mostrate al primo tiratore della batteria, che deve essere pronto in pedana.", "Il tiratore in pedana può chiedere all'arbitro di ripetere la presentazione, fino a due piattelli per ogni piattello della sequenza del menu.", "I doppi allo sparo non vengono presentati, perché il secondo piattello parte solo al rumore del colpo. I doppi simultanei e a raffica vengono mostrati al primo tiratore di ogni batteria e, su richiesta, ripetuti fino a due doppi presentati.", "Durante la presentazione i fucili sono aperti e scarichi, come a ogni interruzione, e si richiudono solo quando l'arbitro lo consente. Sparare o simulare il tiro durante la presentazione è vietato ed è punito come un'infrazione sulla posizione del fucile: prima un avvertimento, poi un cartellino rosso.", "Se una macchina si guasta o il tiro si ferma per più di dieci minuti, l'arbitro fa presentare di nuovo i piattelli di quella pedana. Prima della gara nessuno può allenarsi sui layout di gara.", "In allenamento la presentazione è il momento preferito dell'istruttore: «watch where it turns» (guarda dove gira). In gara la presentazione fa parte della competizione, quindi anche qui vale il divieto di coaching: resta in silenzio, a meno che l'arbitro o il tiratore non abbiano bisogno di una traduzione procedurale."], "key_points": ["Tutte le traiettorie vengono mostrate al primo tiratore, pronto in pedana.", "Ripetizioni su richiesta: fino a due per ogni piattello del menu.", "I doppi allo sparo non vengono mai presentati; i simultanei e a raffica sì.", "Fucili aperti durante la presentazione; niente spari né simulazioni di tiro.", "Interruzione oltre i 10 minuti: i piattelli vengono presentati di nuovo."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Il tiratore all'arbitro: inizi la presentazione.", "say": "Mi fa vedere i piattelli, per favore?"}, {"en": "Again, please, B only.", "meaning": "Richiesta di ripetere un piattello del menu.", "say": "Ancora, per favore, solo la B."}, {"en": "Guns open during the show.", "meaning": "Arbitro: aprite e scaricate finché non dice di chiudere.", "say": "Fucili aperti durante la presentazione."}, {"en": "Watch where it turns.", "meaning": "Istruttore in allenamento: nota il punto in cui il piattello cambia direzione o forma.", "say": "Guarda dove gira."}], "quiz": [{"q": "Quali doppi NON vengono mostrati nella presentazione?", "options": ["Simultanei", "A raffica", "Allo sparo", "Nessuno: si mostrano tutti"], "answer": 2, "why": "Il secondo piattello di un doppio allo sparo parte solo con il colpo, quindi questi doppi non vengono presentati."}, {"q": "Quante ripetizioni di un piattello può chiedere il tiratore in pedana?", "options": ["Nessuna", "Fino a due per ogni piattello del menu", "Quante ne servono", "Una per pedana"], "answer": 1, "why": "Su richiesta l'arbitro ripete la presentazione, fino a due piattelli per ogni piattello della sequenza del menu."}, {"q": "Durante la presentazione un tiratore chiude il fucile e segue la linea di un piattello. Che cosa si applica?", "options": ["È vietato: si applicano le penalizzazioni sulla posizione del fucile, prima un avvertimento poi un cartellino rosso", "Niente: la presentazione è libera", "Il piattello viene presentato di nuovo", "Viene ammonito solo l'istruttore"], "answer": 0, "why": "Durante la presentazione i fucili restano aperti, e sparare o simulare il tiro è punito secondo le regole dell'avvertimento e del cartellino rosso."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Malfunzionamenti del fucile e della cartuccia", "body": ["Un malfunzionamento è un guasto del fucile o della cartuccia: un colpo mancato (misfire), una seconda canna che non spara, oppure entrambe le canne che sparano insieme (doppia scarica, double discharge). Nel Parcours de Chasse – Sporting™ gli incidenti si contano per serie da 25 piattelli.", "Prima di tutto, che cosa deve fare il tiratore: restare al suo posto, con il fucile puntato verso il campo, senza aprirlo né toccare la sicura finché l'arbitro non l'ha esaminato. Se apre il fucile o tocca la sicura prima, il piattello o i piattelli valgono zero.", "Il primo incidente in una serie è un No bird con un avvertimento, e il piattello si ripete. Dal secondo incidente nella stessa serie, il piattello non si ripete più ma vale zero.", "Dettagli di un primo incidente: se il primo colpo non parte, un singolo o qualsiasi doppio si ripete, ma se il tiratore spara comunque il secondo colpo, quel risultato resta valido. Se il secondo colpo non parte su un singolo, il piattello si ripete e allora può essere rotto solo con il secondo colpo; una rottura con il primo colpo vale zero. In un doppio allo sparo il primo risultato resta valido e il doppio si ripete. Una doppia scarica su un singolo, o sul primo piattello di qualsiasi doppio, è un No bird senza registrare nulla.", "Se il fucile viene riparato prima che la batteria finisca la pedana, il tiratore può tirare per ultimo con il permesso dell'arbitro; altrimenti può continuare subito con un altro fucile, oppure finire in un'altra batteria con l'approvazione della giuria. Fucile, strozzatore o canne non si possono cambiare una volta in pedana."], "key_points": ["Dopo un guasto: resta fermo, fucile verso il campo, non aprirlo né toccare la sicura.", "Primo incidente in una serie: No bird + avvertimento, il piattello si ripete.", "Secondo incidente nella stessa serie: zero, nessuna ripetizione.", "Guasto al secondo colpo su un singolo: nella ripetizione conta solo una rottura con il secondo colpo."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Arbitro: aspetta il controllo; aprire prima costa il piattello.", "say": "Resti lì, non apra il fucile."}, {"en": "Let me see the gun.", "meaning": "L'arbitro esamina il fucile o la cartuccia.", "say": "Mi faccia vedere il fucile."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Primo incidente nella serie: il piattello si ripete.", "say": "Malfunzionamento. No bird, primo avvertimento."}, {"en": "Second malfunction this round. Zero.", "meaning": "Questa volta nessuna ripetizione; il piattello è perso.", "say": "Secondo malfunzionamento in questa serie. Zero."}], "quiz": [{"q": "Primo problema al fucile nella serie: su un singolo la prima cartuccia non parte. Il tiratore aspetta l'arbitro con il fucile puntato verso il campo. Decisione?", "options": ["Zero", "No bird con avvertimento; il piattello si ripete", "Uno", "Cartellino giallo e zero"], "answer": 1, "why": "Il primo incidente di fucile o munizioni in una serie è un No bird con avvertimento, e il singolo si ripete."}, {"q": "La cartuccia non parte e il tiratore, seccato, apre il fucile per guardare l'innesco prima che arrivi l'arbitro. Decisione?", "options": ["No bird", "Il piattello si ripete dopo un avvertimento", "Zero", "Cartellino rosso e il piattello si ripete"], "answer": 2, "why": "Aprire il fucile o toccare la sicura prima del controllo dell'arbitro significa che il piattello vale zero."}, {"q": "Singolo, primo incidente: il primo colpo sbaglia e la seconda cartuccia non parte, quindi il piattello si ripete. Nella ripetizione il tiratore lo rompe con il primo colpo. Decisione?", "options": ["Uno", "Di nuovo No bird", "Uno, con avvertimento", "Zero: in questa ripetizione conta solo una rottura con il secondo colpo"], "answer": 3, "why": "Dopo un guasto al secondo colpo il singolo ripetuto può essere rotto solo con il secondo colpo, quindi il primo colpo deve essere un errore volontario."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Limiti di tempo e ritardi", "body": ["Il Parcours de Chasse – Sporting™ ha un ritmo serrato e diverse regole lo proteggono. Quando il tiratore chiama «pull» o «ready», l'arbitro trasmette la chiamata al puller con un segnale acustico, e il piattello deve partire entro tre secondi; un piattello più tardivo è un No bird.", "Tra un singolo e l'altro, o tra un doppio e l'altro, il tiratore ha al massimo 15 secondi. La prima volta che li supera l'arbitro dà un avvertimento; dopo si applicano le penalizzazioni del cartellino rosso. Dopo una decisione definitiva su un reclamo, il tiratore deve riprendere entro 15 secondi, altrimenti conta come rifiuto di obbedire; le perdite di tempo deliberate sono trattate allo stesso modo.", "Ritardo: quando manca un tiratore, l'arbitro chiama il nome e il numero tre volte nell'arco di un minuto. Arrivare prima del proprio turno sui singoli della prima pedana non costa nulla. Dopo, ogni piattello non tirato vale zero; unirsi a una pedana successiva significa che tutti i piattelli delle pedane precedenti valgono zero. Un layout con pedane saltate non può mai essere ritirato in un'altra batteria.", "Un tiratore in ritardo per motivi indipendenti dalla sua volontà non deve rientrare nella batteria in quella serie, ma ricorrere per iscritto alla giuria. Se la giuria accetta, la serie si tira in un'altra batteria; altrimenti, 25 zeri per ogni layout non tirato.", "Salire in pedana senza protezioni auditive o occhiali di protezione equivale a essere assenti. Per uno spareggio non in programma, i tiratori devono essere pronti entro 15 minuti dalla chiamata.", "Per te: non trattenere mai la batteria con una traduzione lunga. Breve adesso, i dettagli dopo la pedana."], "key_points": ["Piattello entro 3 secondi dal segnale dell'arbitro, altrimenti No bird.", "Massimo 15 secondi tra singoli o doppi: avvertimento, poi cartellino rosso.", "Riprendere entro 15 secondi dopo una decisione definitiva, altrimenti è rifiuto di obbedire.", "Ritardo: nome e numero chiamati tre volte in un minuto; i piattelli saltati valgono zero."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "L'arbitro chiama un tiratore assente (tre volte nell'arco di un minuto).", "say": "Tiratore numero ventitré!"}, {"en": "Watch your time.", "meaning": "Promemoria del limite di 15 secondi tra un piattello e l'altro.", "say": "Attenzione al tempo."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Prima volta oltre il limite: avvertimento; la prossima volta una penalizzazione.", "say": "Oltre i quindici secondi. Questo è un avvertimento."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Senza protezione per gli occhi il tiratore è considerato assente.", "say": "Metta gli occhiali, altrimenti non può tirare."}], "quiz": [{"q": "Il tiratore chiama, l'arbitro trasmette il segnale, ma il piattello parte circa cinque secondi dopo. Il tiratore spara e sbaglia. Decisione?", "options": ["Zero", "No bird", "Uno", "Un avvertimento per il tiratore"], "answer": 1, "why": "Un piattello lanciato più di tre secondi dopo il segnale dell'arbitro è un No bird."}, {"q": "Un tiratore arriva mentre la sua batteria sta ancora tirando i singoli alla pedana 1, prima che sia arrivato il suo turno. Che cosa succede?", "options": ["Si unisce senza penalità", "25 zeri", "Zero su tutti i singoli della pedana 1", "Deve tirare con un'altra batteria"], "answer": 0, "why": "Arrivare prima di aver perso il proprio turno sui singoli della prima pedana non comporta penalità."}, {"q": "Tra due singoli un tiratore impiega circa 25 secondi, per la prima volta oggi. Decisione?", "options": ["Zero sul piattello successivo", "Cartellino rosso", "Nessuna conseguenza", "Un avvertimento dell'arbitro"], "answer": 3, "why": "Il limite è di 15 secondi; la prima volta che si supera l'arbitro avverte, e solo dopo seguono le penalizzazioni."}]}]}, {"id": "compak", "icon": "grid", "title": "Il regolamento del Compak® Sporting", "intro": "Il Compak® Sporting concentra la varietà del Parcours de Chasse – Sporting™ in un piccolo campo: cinque pedane in linea, sei macchine e un rettangolo fisso che i piattelli devono sorvolare. Molte regole sembrano uguali, ma posizione del fucile, limiti di tempo, doppi e penalizzazioni sono diversi. Un interprete che confonde le due discipline dà al tiratore informazioni sbagliate.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Campo, menu e rotazione", "body": ["Un campo di Compak® Sporting è compatto per definizione. I piattelli devono sorvolare un rettangolo delimitato largo da 35 a 40 m e profondo 25 m, con una bandierina o un segnale a ogni angolo. Di fronte ci sono cinque pedane di tiro, ognuna un quadrato di 1 m, in linea da 4 a 8 m dietro il lato anteriore; la pedana 3 sta al centro.", "Ci sono sei macchine, contrassegnate dalla A alla F da sinistra a destra, ognuna con un cartello. Ogni Compak® deve comprendere un traversone da sinistra a destra, un traversone da destra a sinistra e un piattello in allontanamento; le altre traiettorie sono a scelta dell'organizzatore. Ogni pedana ha un limitatore dell'angolo di tiro (Firing Angle Limiter), un telaio che impedisce al fucile di ruotare troppo e tiene il tiratore dentro la pedana.", "Una serie è di 25 piattelli, cinque per pedana: cinque singoli, tre singoli e un doppio, oppure un singolo e due doppi. Su uno stesso Compak® il tipo di doppio è lo stesso su tutte le pedane. Il menu, cioè l'ordine dei piattelli, è esposto a ogni pedana, e il primo piattello di ogni doppio è l'ultimo piattello tirato alla pedana precedente.", "Rotazione in una batteria di massimo sei: si comincia sempre dalla pedana 1, e il sesto tiratore aspetta dietro di essa. Quando il tiratore della pedana 5 ha finito, va ad aspettare dietro la pedana 1, tutti si spostano di una pedana verso destra e il tiratore in attesa sale sulla pedana 1. Si cambia pedana con il fucile aperto e scarico, senza disturbare chi sta ancora tirando.", "Il Compak® in linea funziona diversamente: ogni tiratore di un gruppo va dalla pedana 1 alla pedana 5."], "key_points": ["Rettangolo di 35–40 m × 25 m; cinque pedane di 1 m; sei macchine A–F.", "Obbligatori: traversone da sinistra a destra, traversone da destra a sinistra, piattello in allontanamento.", "Serie = 25 piattelli, 5 per pedana; un solo tipo di doppio per Compak®.", "Ogni doppio comincia con l'ultimo piattello della pedana precedente.", "Dopo la pedana 5: si aspetta dietro la pedana 1; tutti si spostano di una pedana a destra."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Rotazione dopo che il tiratore della pedana 5 ha finito.", "say": "Spostatevi di una pedana a destra."}, {"en": "Gun open when you change stations.", "meaning": "Tra una pedana e l'altra il fucile è aperto e scarico.", "say": "Fucile aperto quando cambi pedana."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "La regola della concatenazione del menu del Compak®.", "say": "Il tuo doppio comincia con l'ultimo piattello della pedana precedente."}, {"en": "You're waiting behind one.", "meaning": "Il sesto tiratore sta dietro la pedana 1.", "say": "Tu aspetti dietro la uno."}], "quiz": [{"q": "Quante macchine e quante pedane ha un campo di Compak® Sporting?", "options": ["4 macchine, 3 pedane", "6 macchine, 5 pedane", "5 macchine, 5 pedane", "8 macchine, 6 pedane"], "answer": 1, "why": "Un Compak® usa sei macchine, dalla A alla F, e cinque pedane di tiro."}, {"q": "Il tiratore della pedana 5 ha finito il suo menu. Dove va?", "options": ["Alla pedana 1", "Resta sulla pedana 5", "Dietro la pedana 1, ad aspettare", "Dall'arbitro a firmare lo statino"], "answer": 2, "why": "Diventa il tiratore in attesa dietro la pedana 1, mentre tutti gli altri si spostano di una pedana verso destra."}, {"q": "Su un Compak®, il primo piattello di ogni doppio è…", "options": ["qualsiasi piattello scelga il tiratore", "sempre la macchina A", "un piattello mostrato solo su richiesta", "l'ultimo piattello tirato alla pedana precedente"], "answer": 3, "why": "Il menu concatena le pedane: ogni doppio comincia con il piattello che ha chiuso la pedana precedente."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Posizione del fucile, chiamata e tempo", "body": ["Qui il Compak® Sporting si differenzia nel modo più visibile dal Parcours de Chasse – Sporting™. Alla chiamata la posizione del fucile è libera: il fucile può essere già alla spalla oppure no. Non c'è la partenza con il fucile non imbracciato e non c'è la linea sul gilet. Ogni piattello si tira comunque con il fucile alla spalla.", "Lancio: le macchine vengono azionate a mano, con un telecomando o con un phonopull (sonopull) a comando vocale. Con il lancio manuale il piattello deve partire da 0 a 3 secondi dopo la chiamata; il phonopull ha un ritardo fisso di 0,5 secondi. Le gare internazionali in linea usano solo il phonopull. Un piattello lanciato più di 3 secondi dopo la chiamata, o uno che il tiratore non ha chiamato, è un No bird.", "Tempo: il tiratore ha al massimo 10 secondi per chiamare dopo che è stato tirato il piattello della pedana precedente, meno dei 15 secondi dello Sporting™. La prima volta l'arbitro annota un avvertimento sullo statino; se succede di nuovo nella stessa serie, è un cartellino rosso e i piattelli vengono conteggiati: singolo zero, doppio allo sparo zero e No bird, doppio simultaneo zero e zero.", "Presentazione: nel tiro a batterie i piattelli vengono mostrati una sola volta al mattino, alla prima batteria. Il tiratore della pedana 1 chiama ogni singolo, dalla A alla F; poi l'arbitro mostra i doppi simultanei e dice «start» o «competition» (si comincia, gara). Dopo un'interruzione di più di 10 minuti, i sei singoli vengono mostrati di nuovo.", "Caricamento: solo sulla propria pedana, con il fucile aperto e puntato verso il campo dentro il limitatore dell'angolo di tiro; chiudilo solo quando tocca a te."], "key_points": ["Alla chiamata la posizione del fucile è libera; si spara sempre dalla spalla.", "Lancio manuale 0–3 s dopo la chiamata; phonopull fisso 0,5 s; oltre 3 s = No bird.", "Massimo 10 secondi per chiamare: avvertimento annotato, poi piattelli conteggiati zero.", "I piattelli si mostrano una sola volta al mattino alla prima batteria; di nuovo dopo una pausa di oltre 10 minuti."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Arbitro: la presentazione è finita e comincia il tiro valido per il punteggio.", "say": "Start! / Gara!"}, {"en": "Gun up or down, your choice here.", "meaning": "Istruttore: nel Compak® la posizione del fucile alla chiamata è libera.", "say": "Fucile su o giù, qui scegli tu."}, {"en": "Ten seconds, call your target.", "meaning": "Promemoria del limite di 10 secondi per chiamare.", "say": "Dieci secondi, chiama il piattello."}, {"en": "Warning: time.", "meaning": "Prima volta oltre i 10 secondi; annotato sullo statino.", "say": "Avvertimento: tempo."}], "quiz": [{"q": "Nel Compak® Sporting un tiratore chiama con il fucile già alla spalla. Qual è la decisione dell'arbitro?", "options": ["Cartellino giallo", "Consentito: la posizione del fucile alla chiamata è libera", "Zero", "Consentito solo sui doppi"], "answer": 1, "why": "Il Compak® Sporting non ha la partenza con il fucile non imbracciato né la linea sul gilet; solo il colpo deve essere sparato dalla spalla."}, {"q": "Lancio manuale. Il piattello parte circa quattro secondi dopo la chiamata e il tiratore sbaglia. Decisione?", "options": ["Zero", "Uno", "Solo un avvertimento al puller, lo zero resta", "No bird"], "answer": 3, "why": "Un piattello lanciato più di 3 secondi dopo la chiamata è un No bird e viene lanciato di nuovo."}, {"q": "Per la seconda volta nella stessa serie un tiratore impiega più di 10 secondi per chiamare. Il piattello è un singolo. Decisione?", "options": ["Zero", "Solo un altro avvertimento", "No bird", "Espulsione"], "answer": 0, "why": "Dopo il primo avvertimento, una recidiva nella stessa serie è punita secondo la tabella: un singolo vale zero."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Singoli e doppi nel Compak®", "body": ["Il Compak® Sporting usa le stesse parole del Parcours de Chasse – Sporting™, ma i suoi doppi seguono regole diverse. Un interprete che trasferisce le regole dello Sporting™ darà risposte sbagliate.", "Singoli: ogni singolo deve consentire due colpi da ciascuna delle cinque pedane, quindi la seconda canna è una seconda possibilità legittima.", "Il regolamento del Compak® definisce due tipi di doppio: allo sparo (la chiamata fa partire il primo piattello, il colpo fa partire il secondo; una o due macchine) e simultaneo (due piattelli con una sola chiamata, sempre da due macchine diverse, presi in qualsiasi ordine). Il doppio a raffica non esiste.", "La differenza chiave: in un doppio del Compak® si può sparare una sola cartuccia a ciascun piattello. Sparare entrambi i colpi al primo piattello è vietato, e la guida rapida per gli arbitri conta zero e zero un doppio colpo volontario su un solo piattello. Nello Sporting™ entrambe le cartucce possono andare a un solo piattello.", "Due piattelli con un colpo: in un doppio allo sparo il primo risultato resta valido, il secondo è un No bird e il doppio si ritira. In un doppio simultaneo è un No bird senza registrare nulla e il doppio si ripete; lo stesso la seconda volta; la terza volta è zero e zero. Nello Sporting™ lo stesso colpo vale semplicemente uno e uno.", "Piattelli irregolari: se il primo piattello di un doppio allo sparo, o uno qualsiasi dei piattelli di un doppio simultaneo, è irregolare, si lancia un nuovo doppio. Se il secondo piattello di un doppio allo sparo è irregolare o viene rotto dal primo, il primo risultato resta valido e il doppio si ripete."], "key_points": ["Solo due tipi di doppio: allo sparo e simultaneo; niente raffica.", "Una cartuccia per piattello in un doppio; entrambe su un solo piattello = zero e zero (guida rapida).", "Doppio allo sparo, due con un colpo: primo risultato valido, secondo No bird, doppio ripetuto.", "Simultaneo, due con un colpo: No bird due volte, zero e zero la terza."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Istruttore: nel Compak® ogni piattello di un doppio riceve una sola cartuccia.", "say": "Qui sui doppi un colpo per piattello."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Arbitro su un doppio simultaneo: nessun punteggio, si ripete.", "say": "Tutti e due con un colpo. No bird, si ritira il doppio."}, {"en": "Choose your order on the show.", "meaning": "Istruttore: decidi quale piattello del simultaneo prendere per primo mentre guardi la presentazione.", "say": "Scegli l'ordine durante la presentazione."}, {"en": "Zero, zero.", "meaning": "Arbitro: nessuno dei due piattelli del doppio è valido.", "say": "Zero, zero."}], "quiz": [{"q": "Doppio simultaneo nel Compak®. Un colpo rompe entrambi i piattelli; è la prima volta che succede. Decisione?", "options": ["Uno e uno", "No bird, nessun punteggio, il doppio si ripete", "Uno e No bird", "Zero e zero"], "answer": 1, "why": "Nel Compak® un doppio simultaneo rotto con un solo colpo è un No bird la prima e la seconda volta, e zero e zero la terza."}, {"q": "Doppio allo sparo nel Compak®. Un colpo rompe entrambi i piattelli. Decisione?", "options": ["Uno e uno", "Zero e zero", "Il primo risultato resta valido, il secondo è un No bird e il doppio si ripete", "No bird, nessun punteggio"], "answer": 2, "why": "In un doppio allo sparo si registra il risultato del primo piattello e il doppio si ritira per assegnare il secondo."}, {"q": "In un doppio del Compak® un tiratore sbaglia il primo piattello e gli spara volutamente anche la seconda cartuccia. Come lo conta la guida rapida per gli arbitri?", "options": ["Zero e zero", "È consentito, come nello Sporting™", "Il doppio si ripete", "Conta solo il secondo colpo"], "answer": 0, "why": "In un doppio del Compak® è ammessa una sola cartuccia per piattello; un doppio colpo volontario su un solo piattello vale zero e zero."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "I malfunzionamenti nel Compak®", "body": ["Nel Compak® Sporting, come nel Parcours de Chasse – Sporting™, i guasti del fucile e della cartuccia si contano per serie da 25 piattelli: il primo incidente comporta un No bird e un cartellino giallo; con un secondo incidente dello stesso tipo, i piattelli a cui non si è sparato valgono zero, con un cartellino rosso.", "Che cosa deve fare il tiratore: restare al suo posto, con il fucile puntato verso il campo, senza aprirlo né toccare la sicura finché l'arbitro non l'ha esaminato. Aprirlo prima costa il piattello o i piattelli: zero.", "Primo incidente, quando entrambe le canne sparano insieme o la prima cartuccia non parte: un singolo viene lanciato di nuovo, un doppio allo sparo o un doppio simultaneo viene lanciato di nuovo, e del tentativo fallito non si registra nulla. Quando non parte la seconda cartuccia: su un singolo il piattello viene lanciato di nuovo, ma può valere solo il secondo colpo, quindi il primo deve essere un errore volontario; in un doppio allo sparo il primo risultato resta valido e il doppio si ripete per il secondo; in un doppio simultaneo, un nuovo doppio.", "Dopo un malfunzionamento il tiratore ha due minuti per riparare o sostituire il fucile. In via eccezionale può farsi prestare un fucile da un tiratore che non fa parte della sua batteria, con l'accordo del proprietario e dell'arbitro. Senza un fucile funzionante, i piattelli rimanenti valgono zero. Per il resto, durante una serie non si possono cambiare fucile, strozzatore o canne.", "La stessa logica vale per una lepre mancata con il primo colpo che si rompe prima del secondo: No bird, e nella ripetizione conta solo il secondo colpo."], "key_points": ["Primo incidente in una serie: No bird + cartellino giallo; secondo dello stesso tipo: zero + cartellino rosso.", "Non aprire il fucile né toccare la sicura prima del controllo dell'arbitro.", "Guasto della seconda cartuccia su un singolo: nella ripetizione conta solo il secondo colpo.", "Due minuti per riparare o sostituire; prestito solo da fuori della propria batteria, con il consenso del proprietario e dell'arbitro."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Arbitro: dopo un guasto aspetta il controllo.", "say": "Non si muova, tenga il fucile chiuso."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Primo incidente di questo tipo nella serie; il piattello viene lanciato di nuovo.", "say": "Primo malfunzionamento. Cartellino giallo, No bird."}, {"en": "You have two minutes.", "meaning": "Tempo per riparare o sostituire il fucile.", "say": "Ha due minuti."}, {"en": "Only the second shot counts on this one.", "meaning": "Ripetizione dopo un guasto della seconda cartuccia: sbaglia di proposito con il primo colpo.", "say": "Su questo conta solo il secondo colpo."}], "quiz": [{"q": "Primo incidente della serie nel Compak®: la prima cartuccia non parte su un singolo. Il tiratore aspetta correttamente. Decisione?", "options": ["No bird con cartellino giallo; viene lanciato un nuovo piattello", "Zero", "Cartellino rosso e zero", "Uno"], "answer": 0, "why": "Il primo incidente di fucile o cartuccia in una serie è un No bird con un primo avvertimento indicato da un cartellino giallo."}, {"q": "Il fucile di un tiratore si guasta. Vuole farsi prestare il fucile di un compagno di batteria. È consentito?", "options": ["Sì, con il consenso del proprietario", "Sì, se l'arbitro è d'accordo", "Sì, senza condizioni", "No: chi presta deve essere fuori dalla sua batteria, e devono essere d'accordo sia il proprietario sia l'arbitro"], "answer": 3, "why": "Il Compak® vieta di condividere un fucile all'interno di un gruppo; il prestito eccezionale è possibile solo da fuori, con entrambi i consensi."}, {"q": "Secondo guasto al fucile dello stesso tipo in questa serie, su un singolo a cui il tiratore non ha potuto sparare. Decisione?", "options": ["Di nuovo No bird", "No bird e un avvertimento", "Zero, con cartellino rosso", "Il piattello viene presentato di nuovo"], "answer": 2, "why": "Dal secondo incidente dello stesso tipo, i piattelli a cui non si è sparato valgono zero."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Abbigliamento e comportamento", "body": ["Le gare di Compak® Sporting sono pubbliche, quindi l'abbigliamento deve essere adeguato e pratico. I pantaloncini corti sono vietati, ma i bermuda che finiscono non più di 5 cm sopra il ginocchio vanno bene. Le magliette devono avere almeno le maniche corte e arrivare al collo; una T-shirt va bene, il petto nudo sotto il gilet no. I sandali sono vietati in allenamento e in gara. Il pettorale si porta sulla schiena, ben visibile; una prima violazione comporta un avvertimento, poi le sanzioni.", "Le protezioni per orecchie e occhi sono obbligatorie. Presentarsi in pedana senza di esse equivale all'assenza: non si tira.", "Puntualità: presentati all'arbitro in tempo. Nel tiro a batterie, arrivare dopo che il primo tiratore della batteria ha chiamato il primo piattello costa 25 zeri per la serie; il ricorso va presentato per iscritto alla giuria lo stesso giorno.", "Comportamento: l'assistenza tecnica (coaching) durante la gara è vietata; il concorrente riceve un cartellino giallo e l'istruttore viene allontanato dall'area di tiro. Contestare una decisione definitiva dopo la ripresa del tiro, o criticare apertamente una decisione come tiratore o come spettatore, è un tentativo di influenzare l'arbitro e può portare all'esclusione. Alla fine di ogni serie il tiratore firma lo statino; rifiutarsi di firmare significa perdere il diritto di reclamo.", "Vicino alla pedana fai parte del pubblico: indossa le protezioni, stai in silenzio durante la chiamata, non commentare mai una decisione. Se tu possa riferire le parole di un istruttore in gara è una questione aperta per la FITASC; la pratica sicura è tradurre solo per l'arbitro, la giuria e l'organizzatore."], "key_points": ["Niente pantaloncini corti, niente petto nudo sotto il gilet, niente sandali (anche in allenamento); pettorale sulla schiena.", "Senza protezioni per orecchie o occhi in pedana = assente, non si tira.", "In ritardo dopo la prima chiamata della batteria: 25 zeri; ricorso scritto possibile lo stesso giorno.", "Niente coaching; nessuna critica pubblica alle decisioni; firma lo statino."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Arbitro: il pettorale deve essere ben visibile sulla schiena.", "say": "Il pettorale sulla schiena, per favore."}, {"en": "Ears and eyes on.", "meaning": "Metti le protezioni auditive e gli occhiali prima di salire in pedana.", "say": "Cuffie e occhiali."}, {"en": "Sign the sheet, please.", "meaning": "Fine della serie: il tiratore firma lo statino.", "say": "Firmi lo statino, per favore."}, {"en": "No coaching on the stand.", "meaning": "Avvertimento dell'arbitro: in gara il coaching è vietato.", "say": "Niente consigli tecnici in pedana."}], "quiz": [{"q": "Un tiratore si presenta in pedana con i sandali per una serie di allenamento. È consentito?", "options": ["Sì, solo in allenamento", "No: i sandali sono vietati in allenamento e in gara", "Sì, con i calzini", "Solo con il permesso dell'arbitro"], "answer": 1, "why": "Le regole sull'abbigliamento del Compak® vietano i sandali per sicurezza, in allenamento e in gara."}, {"q": "Tiro a batterie. Un tiratore arriva subito dopo che il primo tiratore della sua batteria ha chiamato il primo piattello. Risultato?", "options": ["Nessuna penalità", "Zero solo sul primo piattello", "Tira alla fine della batteria", "25 zeri per la serie; è possibile un ricorso scritto alla giuria lo stesso giorno"], "answer": 3, "why": "Il termine è la prima chiamata della batteria; dopo, il ritardatario riceve 25 zeri, a meno che la giuria non accetti un motivo valido."}, {"q": "Dopo la serie un tiratore si rifiuta di firmare lo statino perché non è d'accordo con una decisione. Qual è la conseguenza?", "options": ["Perde il diritto di presentare qualsiasi reclamo", "L'arbitro deve cambiare il risultato", "La serie si ripete", "Non succede nulla"], "answer": 0, "why": "Firmare lo statino alla fine di ogni serie è obbligatorio; rifiutarsi di firmare rende inammissibile qualsiasi reclamo."}]}]}, {"id": "referee", "icon": "whistle", "title": "Arbitro, punteggio e penalizzazioni", "intro": "In gara l'arbitro è la persona di cui tradurrai le parole più spesso e con più attenzione. Questa missione ti dà le chiamate verbali, lo statino, i cartellini e le penalizzazioni, la procedura di reclamo e le categorie d'età, perché ogni decisione arrivi al tuo tiratore esattamente come è stata presa.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "Che cosa dice l'arbitro in pedana", "body": ["La pedana ha un suo linguaggio breve. Il tiratore fa la chiamata quando è pronto, di solito «Pull!» o «Ready!» (in Italia anche «Pronto!» o «Via!»). Nel Parcours de Chasse – Sporting™ l'arbitro trasmette la chiamata al puller con un segnale acustico, e il piattello deve partire entro tre secondi; un piattello più tardivo è un No bird. Nel Compak® Sporting anche un lancio manuale deve arrivare entro tre secondi dalla chiamata, e un lancio a comando vocale (phonopull) ha un ritardo fisso di mezzo secondo.", "Prima che chiunque spari, l'arbitro controlla il fucile. Caricare è consentito solo in pedana, con il fucile puntato verso il campo, dopo che l'arbitro ha detto che il tiro può iniziare. Mentre i piattelli vengono presentati, e ogni volta che il tiro si ferma, i fucili sono aperti e scarichi e si richiudono solo su indicazione dell'arbitro. Nel Compak® l'arbitro avvia la serie con «Start» o «Competition».", "Dopo ogni piattello il regolamento conosce tre risultati: «uno» (colpito), «zero» (perso) e «No bird» (il piattello non conta e viene lanciato di nuovo). Nel mondo sentirai anche «dead», «good», «lost» o semplicemente silenzio per un piattello colpito; in Italia l'arbitro dice «Buono» e «Zero». Nel Compak® l'arbitro deve annunciare ogni zero ad alta voce o con un segnale acustico, così un tiratore che non è d'accordo può reclamare subito.", "Anche il tiratore ha una parola formale: con la mano alzata, «Protest!» o «Appeal!» (reclamo). Quando traduci, mantieni queste chiamate brevi e sempre identiche. Concorda con il tuo tiratore prima della serie quali parole userai, e non aggiungere mai nulla di tuo tra la chiamata e lo sparo."], "key_points": ["Il tiratore chiama «Pull!» o «Ready!»; il piattello deve arrivare entro 3 secondi", "Si carica solo in pedana e solo quando l'arbitro lo consente; fucili aperti durante la presentazione e le pause", "Parole del regolamento: uno = colpito, zero = perso, No bird = si rilancia", "Compak®: ogni zero viene annunciato ad alta voce o con un segnale acustico", "Reclamo = mano alzata + «Protest!» o «Appeal!»"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "L'arbitro consente l'inizio del tiro: inserisci ora le cartucce, con il fucile puntato verso il campo.", "say": "Può caricare."}, {"en": "No bird!", "meaning": "Quel piattello non conta; non sparargli. Verrà lanciato di nuovo.", "say": "No bird!"}, {"en": "Lost.", "meaning": "L'arbitro ha contato il piattello come errore (zero).", "say": "Zero."}, {"en": "Dead. / Good.", "meaning": "Il piattello è colpito (uno).", "say": "Buono."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Tutti aprono e scaricano; l'arbitro lancerà i piattelli per la presentazione.", "say": "Fucili aperti, per favore: presentiamo i piattelli."}, {"en": "Start. / Competition.", "meaning": "Compak®: la presentazione è finita, la serie conta da adesso.", "say": "Start. / Gara."}], "quiz": [{"q": "Nel Parcours de Chasse – Sporting™ il piattello parte cinque secondi dopo il segnale dell'arbitro. Qual è la decisione?", "options": ["Conta normalmente", "No bird", "Zero, perché il tiratore ha chiamato troppo presto", "Solo un avvertimento al puller"], "answer": 1, "why": "Un piattello deve partire entro tre secondi dal segnale dell'arbitro; uno più tardivo è un No bird e viene lanciato di nuovo."}, {"q": "Quando può caricare il fucile un tiratore?", "options": ["Mentre va verso la pedana", "Dietro la pedana mentre aspetta", "In pedana, con il fucile puntato verso il campo, dopo che l'arbitro ha consentito il tiro", "Quando lo dice l'istruttore"], "answer": 2, "why": "Caricare è consentito solo in pedana, puntando verso il campo, e solo dopo che l'arbitro ha autorizzato l'inizio."}, {"q": "Quale parola apre un reclamo formale in pedana?", "options": ["«Protest!» o «Appeal!» con la mano alzata", "«Pull!»", "«No bird!»", "«Arbitro, guardi!»"], "answer": 0, "why": "Entrambi i regolamenti indicano «protest» o «appeal» con la mano alzata; «No bird» spetta solo all'arbitro."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Statini, risultati e parità", "body": ["Ogni piattello finisce su uno statino. Nel Parcours de Chasse – Sporting™ lo statino lo tiene l'arbitro, o una persona sotto la sua supervisione. Il modello FITASC riporta la lettera della macchina di ogni piattello, con X per un piattello colpito e O per un errore, un totale e una colonna per la firma. Prima che la batteria vada avanti, l'arbitro fotografa lo statino.", "I tiratori devono controllare il punteggio quando lasciano ogni pedana. Un disaccordo va subito all'arbitro; l'arbitro decide, eventualmente dopo aver sentito altri, e dopo non c'è appello. Nel Compak® Sporting il tiratore firma lo statino alla fine della serie, e un tiratore che si rifiuta di firmare perde il diritto di reclamo. Traduci «check your card» come un'istruzione urgente, non come un'osservazione cortese.", "Una gara internazionale è di 200 piattelli in serie da 25. Quando ci sono tiratori a pari merito per i primi tre posti, si tira uno spareggio (shoot-off) di 25 piattelli; se sono ancora pari, segue la morte improvvisa (sudden death), in cui il primo zero elimina. Sotto il terzo posto non c'è spareggio: i tiratori a pari merito condividono la posizione e vengono ordinati con lo spareggio a ritroso (countback), dall'ultimo (ottavo) layout o Compak® a ritroso fino al primo. Le squadre non fanno mai spareggi.", "Gli spareggi nascondono un'altra trappola per l'interprete. Se non è stato fissato un orario, i tiratori devono essere pronti entro quindici minuti dalla chiamata. Un tiratore assente è «squalificato» (disqualified) nel regolamento dello Sporting™ e «considerato ritirato» (considered withdrawn) in quello del Compak®. Usa la parola della disciplina in cui ti trovi."], "key_points": ["X = colpito, O = errore sugli statini FITASC", "Sporting™: controlla il punteggio lasciando ogni pedana; Compak®: firma lo statino o perdi il diritto di reclamo", "Parità per i posti 1–3: spareggio su 25 piattelli, poi morte improvvisa", "Sotto il 3º posto: spareggio a ritroso dall'8º layout o Compak®; niente spareggi a squadre", "Pronti entro 15 minuti dalla chiamata per uno spareggio"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Guarda adesso i tuoi segni; le obiezioni successive non vengono accettate.", "say": "Controlla lo statino prima di lasciare la pedana."}, {"en": "Sign here, please.", "meaning": "Compak®: la firma conferma il punteggio; rifiutarsi significa perdere il diritto di reclamo.", "say": "Firmi qui, per favore."}, {"en": "Twenty-three — you dropped two.", "meaning": "Punteggio di 23 su 25; due piattelli persi.", "say": "Ventitré: ne hai persi due."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Trovati al layout indicato, pronto a tirare entro quindici minuti.", "say": "C'è una parità per il terzo posto: spareggio tra quindici minuti."}, {"en": "Sudden death: first zero is out.", "meaning": "Dopo lo spareggio su 25 piattelli, il primo tiratore che sbaglia (a parità di piattelli tirati) viene eliminato.", "say": "Morte improvvisa: il primo zero è fuori."}], "quiz": [{"q": "Su uno statino FITASC, che cosa significa O?", "options": ["Un piattello colpito", "Un No bird", "Un errore", "Una pedana vuota"], "answer": 2, "why": "Il modello FITASC segna un piattello colpito con X e un errore con O."}, {"q": "Due tiratori sono a pari merito al 7º posto. Che cosa succede?", "options": ["Uno spareggio su 25 piattelli", "Subito la morte improvvisa", "Il lancio di una moneta da parte della giuria", "Condividono la posizione e vengono ordinati con lo spareggio a ritroso"], "answer": 3, "why": "Gli spareggi sono solo per i posti 1–3; sotto, i tiratori a pari merito vengono classificati con lo spareggio a ritroso dall'ottavo layout o Compak®."}, {"q": "Nel Compak® Sporting il tuo tiratore si rifiuta di firmare lo statino. Qual è la conseguenza?", "options": ["Perde il diritto di presentare qualsiasi reclamo", "La serie si ripete", "Firma l'arbitro e non cambia nulla", "Riceve automaticamente 25 zeri"], "answer": 0, "why": "Il regolamento del Compak® dice che un tiratore che si rifiuta di firmare perde il diritto di reclamo."}]}, {"id": "referee-cards", "minutes": 5, "title": "Avvertimenti, cartellini e penalizzazioni", "body": ["Le penalizzazioni FITASC salgono per gradini. Iscrivendosi a una gara il tiratore accetta il regolamento e le sanzioni. La prima violazione di una regola comporta normalmente un avvertimento, mostrato con un cartellino giallo. Nel Parcours de Chasse – Sporting™ un esempio classico è la posizione del fucile: un calcio sopra la linea del gilet, o un fucile imbracciato prima che compaia il piattello, comporta un avvertimento verbale e un cartellino giallo.", "Una recidiva sullo stesso layout (o sullo stesso Compak®) comporta un cartellino rosso, e il piattello viene conteggiato secondo una tabella: zero su un singolo, zero e No bird su un doppio allo sparo, zero e zero su un doppio simultaneo o a raffica. La stessa scala si applica allo sparare a un No bird dichiarato e, nello Sporting™, al superamento dei quindici secondi tra un piattello e l'altro. Nel Compak® Sporting il limite è di dieci secondi per chiamare.", "Anche l'assistenza tecnica (coaching) durante una gara è punita: il tiratore riceve un cartellino giallo, le recidive portano a ulteriori sanzioni e l'arbitro allontana dall'area di tiro la persona che ha dato i consigli. Per un interprete questo è il cartellino più importante di tutto il regolamento.", "Per le recidive, il rifiuto di obbedire o i tentativi di influenzare un arbitro, la giuria può togliere un piattello, un'intera serie da 25 o espellere il tiratore. Lanciare un fucile, insulti o violenza, e sparare deliberatamente ad animali vivi possono comportare l'espulsione immediata. Un'espulsione viene registrata dalla FITASC per cinque anni e non dà diritto ad alcun rimborso. Traduci «warning», «yellow card» e «red card» alla lettera (avvertimento, cartellino giallo, cartellino rosso), con calma e subito."], "key_points": ["Prima violazione: avvertimento con cartellino giallo", "Recidiva sullo stesso layout o Compak®: cartellino rosso + piattello conteggiato secondo la tabella", "Coaching in gara: cartellino giallo per il tiratore, istruttore allontanato", "Scala della giuria: un piattello, una serie o espulsione", "Espulsione: registrata per 5 anni, nessun rimborso"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: il fucile era troppo alto prima che comparisse il piattello; la prossima volta su questo layout costa il piattello.", "say": "Avvertimento: il calcio era sopra la linea."}, {"en": "That’s a yellow card.", "meaning": "Un primo avvertimento ufficiale; viene registrato.", "say": "Questo è un cartellino giallo."}, {"en": "Red card — the target is zero.", "meaning": "Una recidiva: il piattello viene contato come perso.", "say": "Cartellino rosso: il piattello è zero."}, {"en": "You’re over time.", "meaning": "Il tiratore ha impiegato più del tempo consentito (15 s nello Sporting™, 10 s per chiamare nel Compak®).", "say": "Ha superato il tempo."}, {"en": "Sir, please leave the shooting area.", "meaning": "L'arbitro sta allontanando qualcuno, per esempio una persona sorpresa a dare consigli tecnici.", "say": "Signore, per favore lasci l'area di tiro."}], "quiz": [{"q": "Sporting™: dopo un cartellino giallo per il fucile imbracciato, il tiratore imbraccia di nuovo in anticipo sullo stesso layout, su un singolo. Qual è il risultato?", "options": ["Un altro avvertimento", "Cartellino rosso e il piattello è zero", "No bird", "Espulsione immediata"], "answer": 1, "why": "Dopo il primo avvertimento, un'ulteriore infrazione sullo stesso layout comporta il cartellino rosso; su un singolo il piattello è zero."}, {"q": "L'arbitro vede un istruttore che dà consigli a un tiratore durante una gara. Che cosa dice il regolamento?", "options": ["Niente, il coaching è consentito tra una pedana e l'altra", "L'istruttore riceve un cartellino rosso", "Il tiratore riceve un cartellino giallo e l'istruttore viene allontanato dall'area di tiro", "La serie viene annullata"], "answer": 2, "why": "Entrambi i regolamenti danno al concorrente un cartellino giallo e fanno allontanare dall'arbitro la persona che dà i consigli."}, {"q": "Quale di queste sanzioni la giuria NON può infliggere secondo la scala delle penalizzazioni?", "options": ["La perdita di un piattello", "La perdita di una serie da 25", "L'espulsione", "Una multa in denaro pagata all'arbitro"], "answer": 3, "why": "La scala della giuria prevede la perdita di un piattello, la perdita di una serie o l'espulsione; non esiste una multa all'arbitro."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Reclami, cauzioni e giuria", "body": ["Un reclamo va fatto sul posto. Il tiratore alza la mano e dice «Protest!» o «Appeal!» in pedana, prima di chiamare il piattello successivo (nel Compak® Sporting, prima che chiami il tiratore successivo). L'arbitro ferma il tiro e ascolta il motivo. Chiamando il piattello successivo il tiratore accetta la decisione precedente, quindi qui come interprete devi essere rapido.", "Se l'arbitro è sicuro, la decisione viene confermata e diventa definitiva. In caso di dubbio, l'arbitro può chiedere a un altro arbitro, al puller o ai tiratori della batteria, solo a titolo di parere, e poi decide da solo. I tiratori non possono mai andare sul campo o raccogliere un piattello per controllarlo, e un piattello rotto dietro un ostacolo naturale o oltre un limite di tiro è una decisione dell'arbitro.", "Alcune decisioni non possono mai andare alla giuria: se un piattello era uno o zero, un No bird, e se una traiettoria era regolare. Le altre decisioni possono essere impugnate davanti alla giuria per iscritto con una cauzione: nel Parcours de Chasse – Sporting™ è il 40% della quota d'iscrizione; nel Compak® l'importo in vigore quel giorno, e solo per incidenti dello stesso giorno. Se il reclamo viene accolto, la cauzione viene restituita.", "Dopo la decisione definitiva il tiratore deve riprendere entro quindici secondi nello Sporting™ e dieci nel Compak®; altrimenti è un rifiuto di obbedire. Continuare a discutere, sfidare l'arbitro per fare scena, o altre persone che criticano apertamente una decisione, vale come tentativo di influenzare l'arbitro. Il tuo compito è tradurre con precisione il reclamo e la risposta, non difendere la causa."], "key_points": ["Reclamo immediato, in pedana, con la mano alzata: «Protest!» / «Appeal!»", "Chiamare il piattello successivo = accettare la decisione precedente", "Mai impugnabili: uno/zero, No bird, regolarità della traiettoria", "Reclamo scritto alla giuria con cauzione (Sporting™: 40% della quota d'iscrizione)", "Riprendere entro 15 s (Sporting™) o 10 s (Compak®); continuare a discutere = influenzare l'arbitro"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "Il tiratore contesta formalmente la decisione e ne dà il motivo (qui: è stato lanciato un piattello già rotto).", "say": "Reclamo! Il piattello era rotto prima che sparassi."}, {"en": "I’m certain — the decision stands.", "meaning": "L'arbitro conferma; la decisione è definitiva.", "say": "Sono sicuro: la decisione resta."}, {"en": "Did anyone see a piece come off?", "meaning": "L'arbitro ha un dubbio e chiede alla batteria solo un parere; decide comunque l'arbitro.", "say": "Qualcuno ha visto staccarsi un pezzo?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Questa decisione è impugnabile; servono un reclamo scritto e una cauzione.", "say": "Può rivolgersi alla giuria per iscritto, con la cauzione."}, {"en": "Please carry on shooting.", "meaning": "La decisione è definitiva; riprendi adesso, altrimenti diventa un rifiuto di obbedire.", "say": "Prego, continui a tirare."}], "quiz": [{"q": "Il tuo tiratore pensa che un piattello contato zero fosse colpito, ma ha già chiamato il piattello successivo. Può ancora reclamare su quella decisione?", "options": ["Sì, alla fine della serie", "Sì, per iscritto alla giuria", "No: chiamare il piattello successivo significa accettare la decisione precedente", "Sì, se la batteria è d'accordo"], "answer": 2, "why": "Chiamando il piattello successivo il tiratore accetta la decisione precedente, e comunque le decisioni uno/zero non vanno mai alla giuria."}, {"q": "Quale decisione PUÒ essere impugnata davanti alla giuria?", "options": ["Se un piattello era uno o zero", "Un No bird", "Se una traiettoria era regolare", "Un'altra decisione dell'arbitro, per esempio una penalizzazione per ritardo"], "answer": 3, "why": "Le decisioni su uno/zero, No bird e traiettoria sono definitive; le altre decisioni dell'arbitro possono andare alla giuria per iscritto con una cauzione."}, {"q": "Nel Parcours de Chasse – Sporting™, a quanto ammonta la cauzione per un reclamo scritto alla giuria?", "options": ["Il 40% della quota d'iscrizione", "L'intera quota d'iscrizione", "50 euro fissi", "Non serve alcuna cauzione"], "answer": 0, "why": "Il regolamento dello Sporting™ fissa la cauzione al 40% della quota d'iscrizione; viene restituita se la giuria dà ragione al tiratore."}]}, {"id": "referee-categories", "minutes": 5, "title": "Le categorie: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Oltre alla classifica assoluta (open), in cui tutti gareggiano insieme, le gare FITASC classificano i tiratori in categorie per età e sesso. Dal 1º gennaio 2027 la tabella internazionale per il Parcours de Chasse – Sporting™ e il Compak® Sporting ha sei categorie: Junior (13–20), Lady (dai 13 anni), Men (21–55), Senior (56–65), Veteran (66–72) e Master (dai 73 anni, uomini e donne). Per le gare precedenti a questa data, controlla sul sito FITASC la tabella allora in vigore.", "Conta l'anno di nascita, non il compleanno. Un tiratore passa a una nuova categoria il 1º gennaio dell'anno in cui compie l'età. Per la stagione 2027 questo significa: Junior nati nel 2007–2014, Men nati nel 1972–2006, Senior 1962–1971, Veteran 1955–1961, Master nati prima del 1955. I limiti avanzano di un anno ogni stagione.", "La trappola più grande per l'interprete è «Senior». Nell'inglese di tutti i giorni suona come «adulto», ma nella FITASC Senior indica la fascia d'età 56–65; la principale categoria degli adulti è Men. Non tradurlo con «adulti» o «seniores» in senso generico. Anche «Master» è una trappola: la categoria d'età FITASC dai 73 anni non ha niente a che fare con la «Master class» della NSCA, che è un livello di abilità.", "Le squadre hanno regole proprie: di solito tre tiratori, ma la squadra Men nello Sporting™ ne ha quattro. Un junior inserito nella squadra Men, o una junior nella squadra Lady, deve iscriversi anche individualmente in quella categoria. Le federazioni nazionali e i club possono usare categorie proprie, quindi controlla sempre il programma della gara, e negli spareggi ricorda che le categorie hanno i loro primi tre posti."], "key_points": ["Sei categorie FITASC dal 2027: Junior, Lady, Men, Senior, Veteran, Master", "Decide l'anno di nascita; la nuova categoria comincia il 1º gennaio", "Senior = 56–65, non «adulti»; la principale categoria degli adulti è Men", "Master FITASC (73+) ≠ Master class NSCA", "Squadre di 3; squadra Men nello Sporting™ = 4; i programmi nazionali possono essere diversi"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Domanda alla registrazione: Junior, Lady, Men, Senior, Veteran o Master.", "say": "In che categoria tiri?"}, {"en": "He’s a Senior now.", "meaning": "In questa stagione è nella fascia 56–65.", "say": "Adesso è Senior."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Prima tra le donne, quarta nella classifica assoluta.", "say": "Ha vinto la categoria Lady ed è arrivata quarta assoluta."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Due o più Veteran sono a pari merito al terzo posto della loro categoria.", "say": "C'è uno spareggio per il bronzo Veteran."}], "quiz": [{"q": "Un tiratore nato nel 1971 si iscrive a una gara FITASC nel 2027. In quale categoria?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "Compie 56 anni nel 2027, quindi è Senior dal 1º gennaio, qualunque sia il suo compleanno."}, {"q": "Come dovresti tradurre per un cliente la categoria FITASC «Senior»?", "options": ["«Adulti»", "«Tiratori esperti»", "«Prima categoria»", "«La fascia d'età 56–65»"], "answer": 3, "why": "Nella FITASC Senior è la fascia d'età 56–65; la principale categoria degli adulti è Men."}, {"q": "Quanti tiratori ci sono in una squadra Men nel Parcours de Chasse – Sporting™?", "options": ["Quattro", "Tre", "Sei", "Cinque"], "answer": 0, "why": "Le squadre hanno di solito tre tiratori, ma la squadra Men nello Sporting™ ne ha quattro."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Sicurezza ed etichetta", "intro": "Su un campo di tiro la sicurezza viene prima di qualsiasi traduzione, e le buone maniere mantengono la batteria calma e concentrata. Questa missione mostra come si maneggiano i fucili, come ci si comporta intorno alla pedana e in una batteria, e che cosa devono indossare tutti, te compreso.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Sicurezza con il fucile: aperto, scarico, volate in sicurezza", "body": ["Ogni fucile va trattato come pericoloso, anche quando è scarico. Fuori dalla pedana si porta aperto: un sovrapposto spezzato sull'avambraccio, un semiautomatico con l'otturatore aperto, volate rivolte dritte verso l'alto o dritte verso il basso. Le cinghie non sono ammesse. Quando nessuno lo usa, il fucile sta in piedi in una rastrelliera. Nessuno tocca il fucile di un altro tiratore senza permesso.", "Le cartucce entrano nel fucile solo in pedana, con le volate puntate verso il campo, e solo quando l'arbitro o l'istruttore lo consente. Un semiautomatico ne contiene al massimo due. Prima di girarsi in pedana, il tiratore apre il fucile e toglie tutte le cartucce, sparate o no. Durante la presentazione dei piattelli, e durante qualsiasi pausa, i fucili restano aperti.", "Se il colpo non parte, il tiratore resta al suo posto, con il fucile puntato verso il campo, e non lo apre né tocca la sicura finché l'arbitro non l'ha controllato. È insieme una regola di sicurezza e una regola di punteggio: aprire prima costa il piattello. Non è ammesso neppure imbracciare e seguire un piattello immaginario fuori dalla pedana, o mentre tira qualcun altro, e i fucili si provano solo su una pedana di prova, mai sulla pedana di gara.", "Quando qualcuno grida «Stop!» o «Cease fire!» (cessate il fuoco), tutti si fermano subito e aprono il fucile. Non trasformarlo in una frase: ripeti «Stop!» ad alta voce nella lingua dei tuoi ospiti e controlla che i loro fucili siano aperti. Se un ospite si gira verso di te con il fucile per chiederti qualcosa, prima fagli abbassare le volate con un gesto e poi traduci."], "key_points": ["Fuori dalla pedana: fucile aperto, scarico, volate in alto o in basso, niente cinghie", "Si carica solo in pedana, puntando verso il campo, con il permesso; semiautomatico al massimo 2", "Aprire e scaricare prima di girarsi; fucili aperti durante la presentazione e le pause", "Dopo un colpo mancato: resta fermo, non aprire, aspetta l'arbitro", "«Stop!» si ripete, non si spiega"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "Andando alla pedana successiva il fucile è aperto, senza cartucce dentro.", "say": "Fucili aperti e scarichi tra una pedana e l'altra, per favore."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Apri il fucile (non romperlo!) così posso vedere che le camere sono vuote.", "say": "Apri il fucile e fammi vedere che è scarico."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Niente cartucce nel fucile mentre cammini o aspetti.", "say": "Non caricare finché non sei in pedana e te lo dico io."}, {"en": "Muzzles down when you turn round.", "meaning": "Non lasciare mai che le canne puntino verso le persone, nemmeno con il fucile aperto.", "say": "Volate in basso quando ti giri."}, {"en": "Stop! Stop! Guns open!", "meaning": "Arresto d'emergenza: smetti di sparare, apri il fucile, aspetta.", "say": "Stop! Stop! Fucili aperti!"}], "quiz": [{"q": "Come si porta un semiautomatico tra una pedana e l'altra?", "options": ["Chiuso, con la sicura inserita", "Con l'otturatore aperto, volata dritta in alto o in basso", "Con una cinghia sulla spalla", "Carico con una cartuccia"], "answer": 1, "why": "I fucili si portano aperti, i semiautomatici con l'otturatore aperto, volate dritte in alto o in basso; le cinghie non sono ammesse."}, {"q": "Il fucile fa clic ma il colpo non parte. Che cosa deve fare il tiratore?", "options": ["Aprirlo subito e guardare", "Girarsi per mostrarlo all'istruttore", "Restare al suo posto, fucile verso il campo, senza aprirlo né toccare la sicura finché l'arbitro non controlla", "Inserire la sicura e chiamare di nuovo"], "answer": 2, "why": "Entrambi i regolamenti chiedono al tiratore di restare fermo finché l'arbitro non controlla; aprire o toccare la sicura prima vale zero."}, {"q": "Qualcuno grida «Cease fire!». Qual è il primo compito dell'interprete?", "options": ["Ripetere «Stop!» ad alta voce e controllare che gli ospiti aprano i fucili", "Spiegare perché il tiro si è fermato", "Chiedere all'istruttore che cosa è successo", "Aspettare che l'ospite chieda"], "answer": 0, "why": "Un arresto d'emergenza si ripete subito; le spiegazioni vengono solo quando tutti i fucili sono aperti."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "Intorno alla pedana: silenzio, distanza, immobilità", "body": ["Un tiratore in pedana ha bisogno di concentrazione totale, da quando carica a quando apre il fucile dopo l'ultimo colpo. Il regolamento colloca i posti di attesa vicino alla pedana, ma dice che non devono disturbare il tiratore. In pratica significa: voce bassa o nessuna voce, nessun movimento brusco nel campo visivo del tiratore, fucili aperti e telefoni silenziosi e in tasca. Il regolamento non parla dei telefoni, ma ogni campo si aspetta questa cortesia.", "Resta dietro il tiratore, mai accanto o davanti alla pedana. Nel Compak® Sporting un telaio Firing Angle Limiter limita lo swing di ogni tiratore; nel Parcours de Chasse – Sporting™ su molti campi le pedane hanno una gabbia. Tutti gli altri aspettano dietro, fuori da qualsiasi possibile linea delle canne. Nel Compak® il tiratore in attesa sta dietro la pedana 1, e un tiratore che ha finito aspetta senza disturbare il successivo.", "Disturbare un tiratore ha conseguenze regolamentari. Se l'arbitro vede che un tiratore è stato chiaramente disturbato, il piattello è un No bird e viene lanciato di nuovo. La simulazione di tiro mentre spara un compagno di batteria non è ammessa. Spara solo il tiratore di turno, e solo al proprio piattello.", "Per te questa lezione è pratica. Smetti di parlare quando il tuo ospite sale in pedana, anche a metà frase. Non rispondere alle domande mentre il fucile è chiuso. Riprendi a parlare solo quando il fucile è aperto: tra un piattello e l'altro, tra un doppio e l'altro, o dopo la pedana. Un consiglio perso costa meno di un doppio rovinato dalla tua voce."], "key_points": ["Silenzio, immobilità, fucili aperti, telefoni silenziosi dietro il tiratore", "Stai dietro la pedana, la gabbia o il F.A.L., mai accanto o davanti", "Un tiratore chiaramente disturbato ha diritto a un No bird", "Niente simulazione di tiro mentre tira qualcun altro", "Interprete: parla solo quando il fucile è aperto"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "La tiratrice è in pedana; tutti smettono di parlare.", "say": "Silenzio dietro, per favore: tocca a lei."}, {"en": "Wait until he’s opened his gun.", "meaning": "Nessuno parla o si muove finché il tiratore non ha finito e aperto il fucile.", "say": "Aspetta che abbia aperto il fucile."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "In allenamento l'istruttore ti vuole proprio dietro, fuori dallo swing.", "say": "Mettiti proprio dietro di me, così vedi quello che vedo io."}, {"en": "Keep out of his line, please.", "meaning": "Sei nel campo visivo del tiratore o vicino alla traiettoria delle canne; spostati indietro.", "say": "Esci dalla sua linea, per favore."}], "quiz": [{"q": "Dove sta l'interprete mentre il suo ospite tira?", "options": ["Accanto al tiratore, per vederlo in faccia", "Davanti alla pedana, per vedere il piattello", "Dietro la pedana, fuori da qualsiasi linea delle canne", "Dove l'arbitro non può vederlo"], "answer": 2, "why": "Tutti aspettano dietro la pedana o la gabbia; accanto al tiratore è il posto più pericoloso."}, {"q": "Una telefonata ad alta voce dietro la pedana disturba chiaramente il tiratore al momento dello sparo. Che cosa può decidere l'arbitro?", "options": ["No bird: il piattello viene lanciato di nuovo", "Zero per il tiratore", "Niente, i telefoni non sono nel regolamento", "Cartellino giallo per il tiratore"], "answer": 0, "why": "Se l'arbitro vede che il tiratore è stato chiaramente disturbato, il piattello è un No bird."}, {"q": "Qual è il momento giusto per riferire il commento dell'istruttore?", "options": ["Mentre il tiratore chiama", "Tra la chiamata e lo sparo", "Appena l'istruttore finisce di parlare", "Quando il fucile è aperto: tra i piattelli, tra i doppi o dopo la pedana"], "answer": 3, "why": "La routine del tiratore non va interrotta; parla solo quando il fucile è aperto."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Le buone maniere in batteria", "body": ["Una batteria è un gruppo di massimo sei tiratori sorteggiati che tirano insieme. La puntualità è la prima cortesia ed è anche una regola. Nel Parcours de Chasse – Sporting™ un tiratore assente viene chiamato tre volte nell'arco di un minuto, e i piattelli non tirati valgono zero. Nel Compak® Sporting un tiratore che arriva dopo che il primo tiratore della batteria ha chiamato riceve 25 zeri per la serie, e presentarsi prima all'arbitro è obbligatorio.", "L'ordine conta. Nello Sporting™ l'ordine ruota a ogni pedana e per i doppi; nel Compak® i tiratori si spostano di una pedana a destra dopo ogni serie di piattelli. Nessuno sale in pedana finché il tiratore precedente non l'ha lasciata. Quando viene chiamato, il tiratore è subito pronto, con cartucce sufficienti per tutta la serie.", "Decide solo l'arbitro. I membri della batteria non commentano se un piattello è stato colpito, a meno che non sia l'arbitro a chiederlo. Le critiche aperte a una decisione, da parte di tiratori o spettatori, valgono come tentativo di influenzare l'arbitro. Perdere il controllo, per esempio lanciare un fucile o insultare qualcuno, finisce davanti alla giuria e può significare l'espulsione.", "Oltre alle regole ci sono le consuetudini. I tiratori di solito salutano l'arbitro e la batteria all'inizio, dicono «good shot» o «well shot» (bel colpo, bravo) dopo una buona pedana, e «bad luck» (sfortuna) dopo un errore, ma non commentano mai la tecnica di uno sconosciuto. Una parola di ringraziamento al puller e all'arbitro alla fine, una stretta di mano e la calma quando escono i risultati sono comuni su molti campi. Traduci queste cortesie con calore: sono importanti."], "key_points": ["Sii puntuale e presentati all'arbitro; il ritardo costa zeri", "Segui la rotazione; sali solo quando la pedana è libera", "Decide solo l'arbitro; nessun commento sui piattelli colpiti", "Perdere il controllo può significare l'espulsione", "Consuetudini: salutare, «bel colpo», ringraziare il puller e l'arbitro"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "L'arbitro sta chiamando un tiratore assente; se non arriva, i suoi piattelli saranno zeri.", "say": "Numero dodici, ultima chiamata!"}, {"en": "You’re next — get ready.", "meaning": "Preparati adesso: occhiali, cuffie, cartucce, ma non salire finché la pedana non è libera.", "say": "Sei il prossimo: preparati."}, {"en": "Well shot!", "meaning": "Un complimento sincero dopo un buon piattello o una buona pedana.", "say": "Bel colpo!"}, {"en": "Bad luck.", "meaning": "Comprensione amichevole dopo un errore, non una critica.", "say": "Sfortuna."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Ringraziare l'arbitro e il puller alla fine della serie.", "say": "Grazie, arbitro; grazie per i lanci."}], "quiz": [{"q": "Compak® Sporting, tiro a batterie: il tuo ospite arriva dopo che il primo tiratore della sua batteria ha chiamato il primo piattello. Che cosa succede?", "options": ["Si unisce alla pedana successiva", "Riceve 25 zeri per quella serie", "Tira per ultimo senza penalità", "La serie ricomincia"], "answer": 1, "why": "Nel Compak® a batterie il termine è la prima chiamata della batteria; dopo, il ritardatario riceve 25 zeri (è possibile un ricorso alla giuria)."}, {"q": "Un compagno di batteria dice ad alta voce all'arbitro che ha sbagliato su un piattello colpito. Come lo considera il regolamento?", "options": ["Un'informazione utile", "Un reclamo formale", "Un tentativo di influenzare l'arbitro", "Niente di particolare"], "answer": 2, "why": "Altre persone che criticano apertamente una decisione senza il permesso dell'arbitro tentano di influenzarlo; può reclamare solo il tiratore interessato."}, {"q": "Nel Parcours de Chasse – Sporting™, come funziona l'ordine di tiro in una batteria?", "options": ["Ruota a ogni pedana e per i doppi", "È fisso per tutta la giornata", "Comincia sempre il tiratore migliore", "Lo sceglie liberamente l'arbitro"], "answer": 0, "why": "Le batterie di sei vengono sorteggiate, e l'ordine ruota a ogni pedana e anche per i doppi."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Orecchie, occhi e abbigliamento: anche i tuoi", "body": ["Le protezioni auditive sono obbligatorie per tutti quelli che si trovano su un campo o vicino: tiratori, arbitri, personale e spettatori. Nel Parcours de Chasse – Sporting™ gli occhiali di protezione sono obbligatori, senza eccezioni, per tiratori, arbitri, personale e chiunque si trovi vicino a una pedana. Nel Compak® Sporting la regola sugli occhiali indica concorrenti, arbitri e personale. Un tiratore che sale in pedana senza l'una o l'altra protezione è considerato assente.", "Questo vale anche per te. Stando dietro la pedana, sei «vicino a un campo». Le cuffie elettroniche sono lo strumento migliore dell'interprete: attenuano lo sparo ma lasciano passare le voci, così senti l'istruttore e l'arbitro. Gli occhiali da tiro, chiari o colorati, ti proteggono anche dai frammenti di piattello che cadono; aiuta anche un cappellino.", "Le regole sull'abbigliamento riguardano sicurezza e rispetto. Niente pantaloncini corti: solo bermuda lunghi che finiscono non più di 5 cm sopra il ginocchio. Le camicie devono avere almeno le maniche corte e un colletto o uno scollo rotondo tipo T-shirt; un gilet sul petto nudo non è ammesso. I sandali sono vietati, e nel Compak® il divieto vale sia in allenamento sia in gara. Il pettorale si porta sulla schiena, tra le spalle e la vita, ben visibile, non piegato né tagliato.", "Una prima violazione delle regole sull'abbigliamento o sul pettorale comporta un avvertimento; se non viene corretta, seguono penalizzazioni fino all'esclusione da parte della giuria. Alle cerimonie i membri delle squadre indossano la divisa della nazionale o pantaloni eleganti e una giacca, e tutti i premiati devono partecipare alla premiazione. Vestiti come un professionista tranquillo: scarpe chiuse, abiti neutri, niente che svolazzi o brilli negli occhi del tiratore."], "key_points": ["Protezioni auditive per tutti vicino a un campo, spettatori e interpreti compresi", "Occhiali: Sporting™ — chiunque sia vicino a una pedana; Compak® — concorrenti, arbitri, personale", "Senza protezioni il tiratore è considerato assente", "Bermuda al massimo 5 cm sopra il ginocchio, maniche, niente petto nudo sotto il gilet, niente sandali", "Pettorale sulla schiena, ben visibile; prima violazione = avvertimento"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Metti occhiali e protezioni auditive prima di uscire verso i campi.", "say": "Occhiali e cuffie prima di uscire dalla club house."}, {"en": "Where are your ears?", "meaning": "«Ears» = protezioni auditive, non le orecchie vere e proprie.", "say": "Dove sono le tue cuffie?"}, {"en": "You can’t shoot in sandals here.", "meaning": "Per sicurezza servono scarpe chiuse.", "say": "Qui non si può tirare con i sandali."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "Il pettorale sulla schiena deve essere completo e visibile; altrimenti un avvertimento.", "say": "Il tuo pettorale è piegato: deve essere ben visibile."}], "quiz": [{"q": "Il tuo tiratore sale in pedana senza occhiali di protezione. Come lo considera il regolamento?", "options": ["Riceve un avvertimento e può tirare", "Può tirare se l'istruttore è d'accordo", "Perde un piattello", "È considerato assente"], "answer": 3, "why": "In entrambe le discipline un tiratore in pedana senza protezioni per occhi o orecchie è considerato assente."}, {"q": "Quali pantaloncini sono ammessi?", "options": ["Qualsiasi pantaloncino sportivo", "Bermuda che finiscono non più di 5 cm sopra il ginocchio", "Pantaloncini solo nel Compak®", "Nessun pantaloncino"], "answer": 1, "why": "I pantaloncini corti sono vietati; si accettano bermuda lunghi non più alti di 5 cm sopra il ginocchio."}, {"q": "Perché le cuffie elettroniche sono una buona scelta per un interprete?", "options": ["Attenuano lo sparo ma lasciano passare le voci", "Per gli interpreti non sono obbligatorie", "Bloccano completamente ogni suono", "Registrano l'istruttore"], "answer": 0, "why": "Le protezioni auditive sono obbligatorie vicino a un campo, e le cuffie elettroniche ti permettono di sentire l'istruttore e l'arbitro."}]}]}, {"id": "interpreter", "icon": "speech", "title": "L'interprete al lavoro", "intro": "Qui si unisce tutto ciò che hai imparato: che cosa puoi e non puoi dire, dove metterti, le parole che ingannano anche i linguisti esperti, numeri e unità di misura, il lessico britannico e americano e, infine, un'intera sessione di allenamento dal primo «buongiorno» al resoconto finale.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "Il tuo ruolo: allenamento e gara", "body": ["In allenamento sei la voce dell'istruttore. Rendi ogni istruzione per intero, nell'ordine e nel tono dell'istruttore: fermo quando si tratta di sicurezza, caloroso quando è un complimento. Non ammorbidire le critiche, non aggiungere motivazioni che l'istruttore non ha dato e non aggiungere mai consigli tecnici tuoi, anche quando conosci la risposta. Se non hai sentito una parola, chiedi prima di tradurre.", "Una gara è diversa. L'assistenza tecnica (coaching) a un concorrente durante la gara è vietata sia nel Parcours de Chasse – Sporting™ sia nel Compak® Sporting: il tiratore riceve un cartellino giallo, le recidive portano a ulteriori sanzioni e l'arbitro allontana dall'area di tiro la persona che ha dato i consigli. Inoltre decide solo l'arbitro: nessuno della batteria commenta i piattelli colpiti, e le critiche aperte a una decisione valgono come tentativo di influenzare l'arbitro.", "Ecco la parte onesta. I regolamenti FITASC non parlano affatto degli interpreti. Se riferire parola per parola il consiglio di un istruttore durante una gara valga come coaching, e dove possa stare un interprete, il regolamento non lo dice. È una questione aperta per la FITASC, e non dovresti presentare nessuna risposta come ufficiale.", "Finché la FITASC non risponde, segui la pratica sicura. In gara traduci solo la comunicazione con l'arbitro, la giuria e l'organizzatore: chiamate, decisioni, avvertimenti, reclami, orari e batterie. Prima della gara, di' all'arbitro o all'organizzatore chi sei e concorda dove ti metterai. Se un istruttore ti chiede di riferire un consiglio durante la gara, rifiuta gentilmente e spiega perché. Così proteggi il tuo tiratore da un cartellino giallo."], "key_points": ["Allenamento: la voce dell'istruttore, per intero, stesso tono, niente di tuo", "Gara: il coaching è vietato (cartellino giallo, istruttore allontanato)", "Questione FITASC aperta: i regolamenti non parlano degli interpreti", "Pratica sicura: in gara traduci solo la comunicazione con arbitro, giuria e organizzatore", "Presentati all'arbitro e concorda dove ti metti"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Allenamento: riferiscilo per intero quando il fucile è aperto.", "say": "Dille che sul secondo piattello alza la testa."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Gara: questo è coaching. Rifiuta gentilmente; non riferirlo.", "say": "Svelto, digli di dare più anticipo al traversone."}, {"en": "Who are you with?", "meaning": "L'arbitro chiede perché sei vicino alla pedana; presentati e spiega il tuo ruolo.", "say": "Lei con chi è?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Una domanda procedurale all'arbitro: puoi tradurla.", "say": "Chiedi all'arbitro se posso ancora cambiare gli strozzatori."}], "quiz": [{"q": "Durante una serie di gara l'istruttore ti chiede di dire al tiratore «più anticipo sul traversone». Che cosa fai?", "options": ["Lo sussurri in fretta", "Lo traduci dopo il piattello successivo", "Rifiuti gentilmente: sarebbe coaching, che è vietato", "Chiedi all'arbitro di riferirlo"], "answer": 2, "why": "Il coaching durante la gara è vietato e il tiratore riceverebbe un cartellino giallo; il regolamento non dice se riferire un consiglio sia consentito, quindi resta sul sicuro."}, {"q": "Che cosa dicono i regolamenti FITASC sugli interpreti?", "options": ["Possono stare in pedana", "Hanno bisogno di una licenza da arbitro", "Valgono come istruttori", "Niente: è una questione aperta"], "answer": 3, "why": "I regolamenti non parlano degli interpreti, quindi la loro posizione esatta in gara è una questione aperta per la FITASC."}, {"q": "In allenamento l'istruttore dice «Not bad, but you stopped the gun». Come traduci?", "options": ["Per intero e con lo stesso tono, entrambe le parti", "Solo il complimento, per far contento l'ospite", "Solo il difetto, per risparmiare tempo", "Aggiungendo un tuo consiglio su come correggere"], "answer": 0, "why": "Non ammorbidisci e non gonfi: tutto il messaggio, nel tono dell'istruttore, senza niente di tuo."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Dove metterti e quando parlare", "body": ["In allenamento mettiti proprio dietro il tiratore, accanto all'istruttore, dietro la pedana o la gabbia e fuori da qualsiasi linea delle canne. Da lì vedi quello che vede l'istruttore, il piattello e le volate insieme, e l'istruttore può parlarti a bassa voce. Accanto al tiratore è il posto più pericoloso; davanti alla pedana è fuori discussione.", "Scegli la modalità in base al momento. L'interpretazione consecutiva (l'istruttore parla, fa una pausa, parli tu) è adatta al briefing sulla sicurezza, al tragitto tra le pedane e al resoconto finale. L'interpretazione sussurrata, lo chuchotage, permette all'istruttore di continuare a parlare mentre tu sussurri all'orecchio del tiratore da dietro; è faticosa, quindi alterna le due. Concorda un segnale di «pausa, sto traducendo», per esempio il palmo alzato.", "Il tempo è tutto. La routine del tiratore va dalla chiusura del fucile allo sparo. Parla solo quando il fucile è aperto: tra un piattello e l'altro, tra un doppio e l'altro, dopo la pedana. Tra un doppio e l'altro, ripeti come uno specchio i brevi spunti dell'istruttore, «più davanti», «testa giù», «uguale anche il prossimo», e tieni le spiegazioni lunghe per dopo. Ricorda il cronometro: nel Parcours de Chasse – Sporting™ un tiratore ha al massimo 15 secondi tra un piattello o un doppio e l'altro, e nel Compak® Sporting 10 secondi per chiamare. Anche le tue parole consumano quel tempo.", "In gara aspetta dove aspetta la batteria, vicino alla pedana ma senza mai disturbare il tiratore: un tiratore chiaramente disturbato ha diritto a un No bird, e nessuno vuole esserne la causa. Impara all'inizio i segnali con le mani dell'istruttore e traducili una volta per i tuoi ospiti; dopo avranno meno bisogno di te, ed è un buon segno."], "key_points": ["Allenamento: proprio dietro il tiratore, accanto all'istruttore, fuori dalla linea delle canne", "Consecutiva per briefing e resoconti; chuchotage in pedana; alterna", "Parla solo quando il fucile è aperto", "Spunti brevi tra i doppi; limiti di tempo 15 s (Sporting™) e 10 s (Compak®)", "Gara: aspetta con la batteria, non disturbare mai"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Dietro l'istruttore e il tiratore, fuori dallo swing.", "say": "Mettiti proprio dietro di me."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Passa allo chuchotage e riferisci lo spunto a bassa voce; l'istruttore non si fermerà.", "say": "Testa sul calcio: diglielo sottovoce, io vado avanti."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "L'istruttore spiega un segnale con le mani; traducilo una volta per il gruppo.", "say": "Quando faccio così, mani larghe, vuol dire più davanti."}, {"en": "Wait — let him finish the pair.", "meaning": "Tieni il consiglio finché il fucile non è di nuovo aperto.", "say": "Aspetta: lascia che finisca il doppio."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Chiedi di nuovo proponendo le due opzioni che hai sentito; è più veloce di «ripeta, per favore».", "say": "Scusi, ha detto «sotto» o «sopra»?"}], "quiz": [{"q": "Dove dovresti metterti durante una sessione di allenamento su una pedana di Sporting™?", "options": ["Accanto al tiratore, per vedergli gli occhi", "Dietro il tiratore, accanto all'istruttore, fuori dalla linea delle canne", "Davanti alla gabbia, di fronte al tiratore", "Accanto alla macchina"], "answer": 1, "why": "Da dietro vedi quello che vede l'istruttore e resti al sicuro; accanto o davanti è pericoloso."}, {"q": "Che cos'è lo chuchotage?", "options": ["Interpretare dopo che l'oratore fa una pausa", "La traduzione scritta del regolamento", "La traduzione dei segnali con le mani", "L'interpretazione simultanea sussurrata all'orecchio dell'ascoltatore"], "answer": 3, "why": "Lo chuchotage è l'interpretazione simultanea sussurrata; la consecutiva è la modalità con pausa e poi traduzione."}, {"q": "Nel Compak® Sporting, quanto tempo ha un tiratore per chiamare dopo che è stato tirato il piattello della pedana precedente?", "options": ["10 secondi", "15 secondi", "30 secondi", "Nessun limite"], "answer": 0, "why": "Il Compak® concede al massimo 10 secondi per chiamare; lo Sporting™ ammette 15 secondi tra un piattello o un doppio e l'altro."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Falsi amici sul campo di tiro", "body": ["La trappola peggiore è il fumo. Lo «Smoked it!» di un istruttore (o «inked it», «powdered it») significa un colpo perfetto: il piattello è sparito in una nuvola. Ma nel regolamento un piattello che emette solo polvere o fumo, senza un pezzo visibile, è uno zero. Una «chip», una piccola scheggia visibile, è un piattello colpito. Quindi traduci lo «smoked it» dell'istruttore con «polverizzato», e il «only dust» dell'arbitro con «solo polvere: zero».", "Le parole del punteggio non vanno prese alla lettera. «Dead» e «kill» indicano un piattello colpito («buono», «colpito»), mai «morto» o «uccisione». «Lost» è un errore («zero», «mancato»), non «perso» nel senso di smarrito. «Dropped two» significa due piattelli mancati. «Straight» in «25 straight» indica una serie perfetta (25 su 25), non «dritto».", "Parole su attrezzatura e luoghi. Un «trap» è la macchina che lancia i piattelli («macchina»), non una «trappola» (Trap è anche una disciplina olimpica, la Fossa). Uno «stand» è una singola postazione, la pedana, non uno «stand» espositivo; un «peg» è il punto segnato, non un «picchetto»; un «broken gun» è un fucile aperto. «Pull!» è la chiamata, «pull-away» un metodo di anticipo, «length of pull» una misura del calcio. Una «card» è uno statino oppure un cartellino giallo o rosso. «On report» significa al rumore dello sparo. Una «squad» è il gruppo FITASC di massimo sei tiratori; in ClayAway indica anche un sottogruppo di un tour.", "Le altre lingue aggiungono trappole. Il francese «chandelle» è un piattello quasi verticale (un teal inglese), non la chandelle inglese. Il francese «en battue» e l'italiano «in battuta» indicano la selvaggina spinta dai battitori, non il piattello battuta; il portoghese «batida» è il piattello battuta, «de batida» significa selvaggina spinta. Per un piattello colpito un arbitro francese dice «Bon», uno italiano «Buono»; l'addetto al lancio è un «pulleur» o un «puller». Il regolamento italiano usa parole diverse per la squad: batteria nel Parcours de Chasse – Sporting™, squadra di tiro nel Compak®."], "key_points": ["«Smoked it» dell'istruttore = colpo perfetto; «solo polvere o fumo» del regolamento = zero", "Dead / kill = colpito; lost / dropped = mancato; straight = serie perfetta", "Trap = macchina; stand = una postazione (pedana); peg = il punto; broken gun = fucile aperto", "Pull, card, report e squad hanno ciascuno più di un significato", "La chandelle francese e «en battue» sono diverse dalle parole inglesi"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Colpo perfetto, il piattello è diventato polvere. Non è il «solo fumo» del regolamento.", "say": "Polverizzato!"}, {"en": "Only dust — zero.", "meaning": "Arbitro: non si è staccato nessun pezzo visibile, quindi è un errore.", "say": "Solo polvere: zero."}, {"en": "Just a chip, but it’s dead.", "meaning": "Si è staccato un piccolo pezzo visibile: conta come colpito.", "say": "Solo una scheggia, ma è buono."}, {"en": "Break your gun.", "meaning": "Apri il fucile. Non ha niente a che fare con il romperlo.", "say": "Apri il fucile."}, {"en": "Step into the peg.", "meaning": "Mettiti sul punto di tiro segnato.", "say": "Sali sulla postazione."}, {"en": "The second one’s on report.", "meaning": "Il secondo piattello parte al rumore del tuo primo colpo.", "say": "Il secondo è allo sparo."}], "quiz": [{"q": "Dopo un colpo l'istruttore grida «Smoked it!». Che cosa è successo?", "options": ["Si è alzato solo fumo: uno zero", "Il piattello è stato distrutto: un colpo perfetto", "La cartuccia non è partita", "Era un piattello flash"], "answer": 1, "why": "Nel gergo degli istruttori «smoked it» è un colpo perfetto; nel regolamento «solo polvere o fumo» è uno zero: significati opposti."}, {"q": "Qual è la migliore resa in italiano del «Lost.» dell'arbitro?", "options": ["«Smarrito»", "«Tempo perso»", "«Zero»", "«Il piattello è sparito»"], "answer": 2, "why": "«Lost» è la parola del punteggio per un errore (zero), non qualcosa che si è smarrito."}, {"q": "Un ospite francese dice che adora tirare «en battue». Che cosa intende?", "options": ["La selvaggina spinta (uccelli spinti verso i fucili)", "Il piattello battuta, piatto", "Un piattello lanciato in un doppio", "Un piattello rotto"], "answer": 0, "why": "Il francese «en battue» (l'italiano «in battuta») indica la selvaggina spinta; il piattello battuta è un'altra cosa."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Numeri e unità: piedi, iarde, calibri, numeri dei pallini", "body": ["Gli istruttori britannici e americani misurano l'anticipo in piedi: «give it three feet» (dagli tre piedi), «a yard in front» (una iarda davanti), «half a bird» (mezzo piattello), «a barrel's width» (una canna). È un'immagine, non una misura. Traduci l'unità così come viene detta, «tre piedi», e non convertirla a metà istruzione: 0,9 m suona preciso e cambia il significato. Spiega una volta, prima della sessione, che i piedi degli istruttori sono un'impressione, e mantieni «more», «less», «double it» (di più, di meno, raddoppia) esattamente come vengono detti.", "Le distanze dai piattelli sono un'altra cosa. «It's about thirty yards» si può rendere in metri con «circa» («circa 27 metri»), perché una iarda è poco meno di un metro. Le direzioni arrivano spesso con il quadrante dell'orologio: dritto davanti è ore 12, quindi «pick it up at eleven o'clock» (prendilo a ore undici) è leggermente a sinistra. Mantieni l'orologio; non trasformarlo in gradi.", "Il calibro funziona al contrario. Un «12-bore» o «12 gauge» non è di 12 mm; più piccolo è il numero, più larga è la canna, quindi un calibro 20 è più stretto. Entrambi i regolamenti FITASC ammettono al massimo il calibro 12, con canne di almeno 66 cm (26 pollici). La linea sul gilet nel Parcours de Chasse – Sporting™ è a 25 cm, che i tiratori britannici possono chiamare poco meno di dieci pollici.", "Cartucce: la FITASC ammette al massimo 28 g di piombo, vicino alla «one-ounce load» (carica da un'oncia) di cui parlano i tiratori britannici, con pallini da 2,0 a 2,5 mm. I numeri dei pallini non sono uguali in tutti i paesi: un n. 9 è di circa 2 mm quasi ovunque, ma altri numeri possono differire leggermente tra il sistema britannico, quello americano e quello continentale. Quando conta, chiedi i millimetri. Gli strozzatori possono essere indicati con nomi, frazioni o «thou» (millesimi di pollice); traduci il sistema usato dall'istruttore."], "key_points": ["L'anticipo in piedi è un'immagine: mantieni l'unità, non convertire mai a metà istruzione", "Distanza dal piattello: le iarde possono diventare «circa … metri»", "Quadrante dell'orologio per le direzioni: ore 12 = dritto davanti", "Calibro 12 ≠ 12 mm; massimo FITASC calibro 12, canne ≥ 66 cm (26 pollici)", "28 g ≈ un'oncia; pallini 2,0–2,5 mm; i numeri dei pallini cambiano da paese a paese: chiedi i mm"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "L'immagine di anticipo che vuole l'istruttore; una distanza percepita, non misurata.", "say": "Dagli tre piedi."}, {"en": "Half that.", "meaning": "Usa metà dell'anticipo precedente.", "say": "La metà."}, {"en": "Pick it up at eleven o’clock.", "meaning": "Cerca il piattello leggermente a sinistra rispetto al dritto davanti.", "say": "Prendilo a ore undici."}, {"en": "It’s about forty yards out.", "meaning": "Il piattello è a circa 37 metri.", "say": "È a una quarantina di iarde."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Metti una cartuccia con pallino n. 9 (circa 2 mm) nella canna inferiore, che di solito spara per prima.", "say": "Metti un 9 nella canna di sotto."}], "quiz": [{"q": "L'istruttore dice «Give it four feet». Qual è l'interpretazione migliore?", "options": ["«Anticipo: circa 1,22 metri»", "«Anticipo: quattro piedi»", "«Spara quattro metri più avanti»", "«Quattro piattelli avanti»"], "answer": 1, "why": "L'anticipo in piedi è un'immagine; convertirlo a metà istruzione aggiunge una falsa precisione e cambia il messaggio."}, {"q": "Qual è il calibro più grande ammesso nello Sporting™ e nel Compak® FITASC?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Entrambi i regolamenti ammettono al massimo il calibro 12; un numero di calibro più piccolo significa una canna più larga, quindi il 10 non è ammesso."}, {"q": "Un ospite britannico chiede se le sue cartucce «one-ounce» sono regolari in una gara FITASC. Che cosa sai?", "options": ["Il limite FITASC è di 28 g di piombo (+2%), cioè circa un'oncia", "La FITASC ammette 36 g", "È ammessa qualsiasi carica", "Sono ammessi solo 24 g"], "answer": 0, "why": "Il regolamento ammette fino a 28 g di piombo con una tolleranza del +2%; un'oncia è circa 28 g. Anche la misura del pallino (2,0–2,5 mm) deve rientrare."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Parole britanniche e americane a confronto con la FITASC", "body": ["Molti istruttori con cui lavorerai sono cresciuti con l'English Sporting, regolato in Inghilterra dalla CPSA, o con lo Sporting Clays americano della NSCA. Le parole sono simili a quelle della FITASC, ma le regole dietro di esse no, e la differenza più grande è la posizione del fucile.", "Nell'English Sporting e nella NSCA un tiratore può partire «gun up», già imbracciato, prima di chiamare. Nel Parcours de Chasse – Sporting™ questo non è ammesso: il calcio resta sotto la linea del gilet finché non compare il piattello, e ogni piattello si tira dalla spalla. Il Compak® Sporting sta nel mezzo: la posizione del fucile alla chiamata è libera. Quindi «pre-mount this one» in allenamento è un esercizio, ma in una gara FITASC di Sporting™ è un cartellino giallo. Traducilo e, se l'ospite sta per gareggiare, chiedi all'istruttore se citare la regola.", "I doppi hanno nomi diversi. Un «true pair» (inglese e americano) è un doppio simultaneo FITASC. Un «report pair» è un doppio allo sparo. Un «following pair» è un doppio a raffica (rafale) FITASC. Uno «show pair» è la presentazione dei piattelli prima del tiro. Un «peg» è la postazione di tiro, «station» è la parola americana per la pedana e una «cage» è il telaio che la circonda.", "Anche il linguaggio dei risultati è diverso. «HOA», High Over All, è il vincitore assoluto. Classi come AA, A, B o C sono livelli nazionali di abilità basati sulle medie, non categorie d'età FITASC, e nemmeno le classi di difficoltà FITASC A, B e C, che classificano le traiettorie. Anche all'interno della FITASC i doppi sono diversi: nello Sporting™ entrambe le cartucce possono andare a un solo piattello di un doppio, nel Compak® solo una cartuccia per piattello. Chiediti sempre quale regolamento ha in mente chi parla."], "key_points": ["Gun up: ammesso nell'English Sporting e nella NSCA, vietato nello Sporting™ FITASC, libero nel Compak®", "True pair = simultaneo; report pair = allo sparo; following pair = a raffica", "Peg = punto di tiro; station = pedana (USA); cage = telaio di protezione", "HOA = vincitore assoluto; le classi AA/A/B/C non sono categorie FITASC né classi di difficoltà", "Sporting™: ammessi entrambi i colpi su un solo piattello; Compak®: uno per piattello"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Esercizio di allenamento: parti con il fucile alla spalla. Non ammesso in una gara FITASC di Sporting™.", "say": "Per ora su questo imbraccia prima."}, {"en": "It’s a true pair.", "meaning": "Entrambi i piattelli partono nello stesso momento (FITASC: doppio simultaneo).", "say": "È un doppio simultaneo."}, {"en": "Following pair off the left trap.", "meaning": "Due piattelli dalla stessa macchina uno dopo l'altro (FITASC: doppio a raffica).", "say": "Raffica dalla macchina di sinistra."}, {"en": "Let’s see a show pair.", "meaning": "Lancia il doppio una volta perché tutti possano guardarlo prima di tirare.", "say": "Vediamo il doppio in presentazione."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Una classe nazionale di abilità alta, e vincitore assoluto della gara.", "say": "È in classe AA e l'anno scorso ha vinto l'assoluto."}], "quiz": [{"q": "Un istruttore britannico dice «It's a true pair». Qual è il termine FITASC?", "options": ["Un doppio allo sparo", "Un doppio a raffica", "Un doppio simultaneo", "Un doppio regolare"], "answer": 2, "why": "«True pair» è il nome inglese e americano per due piattelli lanciati insieme, un doppio simultaneo FITASC."}, {"q": "In quale disciplina NON è ammessa la partenza «gun up»?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "Lo Sporting™ FITASC richiede il calcio sotto la linea del gilet finché non compare il piattello; il Compak® lascia libera la posizione del fucile."}, {"q": "Un ospite legge «Class C» in una classifica britannica. Che cos'è?", "options": ["Una categoria d'età FITASC", "Un livello nazionale di abilità basato sulle medie", "La classe di traiettoria FITASC più difficile", "Un tipo di cartuccia"], "answer": 1, "why": "Nelle classifiche britanniche e americane le classi sono livelli di abilità; la FITASC usa A/B/C solo per la difficoltà delle traiettorie e ha invece le categorie d'età."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Un'intera sessione di allenamento, passo per passo", "body": ["Prima della sessione, incontra l'istruttore per cinque minuti. Concorda un segnale di pausa, chiedi quale metodo insegna e quali parole usa per l'anticipo, e impara i suoi segnali con le mani. Poi il gruppo si riunisce per il briefing sulla sicurezza: interpretalo in consecutiva, frase per frase, con fermezza e per intero.", "Sulla prima pedana l'istruttore di solito comincia senza cartucce: un controllo dell'occhio dominante, poi la posizione e la posizione di attesa. In un contesto FITASC il fucile parte basso, sotto la linea del gilet. Sussurra le sue correzioni da dietro mentre sistema piedi e mani.", "Poi si legge il piattello. L'istruttore lo fa vedere, chiede dove il tiratore lo vede nitido per la prima volta e fissa il punto di presa visiva, il punto di attesa e il punto di rottura. Mantieni questi tre termini uguali per tutto il giorno, «punto di presa visiva», «punto di attesa», «punto di rottura», così l'ospite li impara.", "Ora si spara. Tra un piattello e l'altro l'istruttore dà spunti da due a cinque parole; tu li rispecchi, stessa lunghezza, stesso ordine, mentre il fucile è aperto. Quando viene diagnosticato un errore, «dietro», «sopra», «ti sei fermato», traduci insieme la diagnosi e la correzione. I complimenti si traducono con la stessa energia.", "Poi i doppi: quale piattello per primo, «prima gli occhi, poi il fucile», il secondo colpo. Infine il resoconto, di nuovo in consecutiva, in cui l'istruttore riassume due o tre punti. Scrivili in entrambe le lingue e dai il foglio all'ospite. Qui sotto trovi una catena reale di frasi, nell'ordine in cui le sentirai."], "key_points": ["Prima: segnale di pausa, metodo, parole per l'anticipo, segnali con le mani", "Briefing sulla sicurezza: consecutiva, con fermezza, per intero", "Gli stessi tre termini tutto il giorno: presa visiva, attesa, rottura", "Spunti tra i piattelli: stessa lunghezza, fucile aperto; diagnosi + correzione insieme", "Resoconto: scrivi i punti chiave in entrambe le lingue"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Inizio della sessione; interpreta il briefing in consecutiva e per intero.", "say": "Buongiorno a tutti. Prima di caricare qualsiasi cosa, un breve briefing sulla sicurezza."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "Niente fucili chiusi fuori dalla pedana; si carica solo su indicazione dell'istruttore.", "say": "I fucili restano aperti finché non siete in pedana e non dico «caricare»."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Controllo dell'occhio dominante: se il dito salta, l'occhio destro non è l'occhio dominante.", "say": "Indica il mio naso, con entrambi gli occhi aperti. Ora chiudi l'occhio sinistro."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Posizione: orienta i piedi verso il punto in cui verrà rotto il piattello; inclinati leggermente in avanti.", "say": "Piede avanti verso il punto di rottura, peso in avanti."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "Posizione di attesa FITASC: il fucile sale solo dopo che compare il piattello.", "say": "Fucile basso, calcio sotto la linea. Imbraccia solo quando lo vedi."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "L'istruttore sta fissando il punto di presa visiva.", "say": "Guarda questo. Dove lo vedi nitido per la prima volta?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Punto di attesa tra presa visiva e punto di rottura, leggermente sotto la traiettoria del piattello.", "say": "Tieni le volate più o meno a metà strada indietro, appena sotto la linea."}, {"en": "Behind it. Give it more.", "meaning": "La rosata è passata dietro il piattello: più anticipo.", "say": "Dietro. Dagliene di più."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "L'immagine di anticipo da vedere allo sparo; i piedi come impressione, mantieni l'unità.", "say": "Diciamo tre piedi: è questa l'immagine che vuoi."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Errore sopra, causato dalla guancia che si è staccata dal calcio.", "say": "Sopra. Hai alzato la testa: resta nel fucile."}, {"en": "Smoked it! Same again.", "meaning": "Colpo perfetto; ripeti esattamente quello che hai fatto.", "say": "Polverizzato! Uguale anche il prossimo."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Errore dietro perché lo swing si è fermato; accompagna il colpo.", "say": "Hai fermato il fucile. Tienilo in movimento durante lo sparo."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "La lepre parte al rumore del colpo sparato al traversone.", "say": "Ora un doppio allo sparo: prima il traversone, poi la lepre."}, {"en": "Eyes first, then the gun.", "meaning": "Sul secondo piattello, trovalo con gli occhi prima di muovere le volate.", "say": "Prima gli occhi, poi il fucile."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Resta basso su un piattello che rotola, così anche un salto incontra la rosata.", "say": "Tieni le volate sotto la lepre."}, {"en": "Change to quarter and half for this stand.", "meaning": "Monta strozzatori da 1/4 e 1/2 (aperto, poi un po' più stretto).", "say": "Per questa pedana passa a un quarto e mezzo."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Fine della sessione; l'istruttore riassume: scrivili per l'ospite.", "say": "Per oggi basta. Tre cose per domani: piedi, testa, accompagnamento."}], "quiz": [{"q": "Quando si interpreta il briefing sulla sicurezza, e come?", "options": ["Brevemente in chuchotage mentre gli ospiti caricano", "All'inizio, in consecutiva, frase per frase e per intero", "Solo se un ospite lo chiede", "Dopo la prima pedana"], "answer": 1, "why": "La sicurezza viene prima e non va abbreviata; la consecutiva permette a ogni regola di arrivare."}, {"q": "L'istruttore dice «Behind it. Give it more». Qual è la resa breve migliore tra un piattello e l'altro?", "options": ["«È un po' in ritardo, riprovi, magari un po' più veloce»", "«Dietro. Più anticipo.»", "«Spara prima»", "«Bene, uguale»"], "answer": 1, "why": "Rispecchia l'istruttore: stessa lunghezza, stesso ordine, diagnosi più correzione, niente di aggiunto."}, {"q": "Perché mantenere «pick-up point», «hold point» e «break point» con le stesse parole italiane per tutto il giorno?", "options": ["Lo richiede il regolamento", "Perché l'istruttore capisca l'italiano", "Perché l'ospite impari tre concetti stabili e non li confonda", "Non ha importanza"], "answer": 2, "why": "Termini coerenti costruiscono la mappa mentale dell'ospite su una pedana; cambiare parole fa sembrare sei concetti quelli che sono tre."}]}]}]};
